  { raw : Metal_raw.handle
  ; lifetime : lifetime
  ; command_buffer : command_buffer
  }

let make_device raw =
  ({ raw; lifetime = lifetime (); registry_id = Metal_raw.device_registry_id raw }
    : device)

let attach_finalizer ?(on_finalize = fun () -> ()) value lifetime parent =
  Gc.finalise (fun _ -> finalize_child lifetime parent on_finalize) value

let command_resource_lifetime = function
  | Command_buffer_buffer buffer -> buffer.lifetime
  | Command_buffer_acceleration_structure value -> value.lifetime
  | Command_buffer_texture texture -> texture.lifetime
  | Command_buffer_sampler sampler -> sampler.lifetime
  | Command_buffer_depth_stencil value -> value.lifetime
  | Command_buffer_visible_table value -> value.lifetime
  | Command_buffer_intersection_table value -> value.lifetime
  | Command_buffer_render_pipeline pipeline -> pipeline.lifetime
  | Command_residency_set residency_set -> residency_set.lifetime
  | Command_buffer_indirect value -> value.lifetime
  | Command_buffer_fence value -> value.lifetime
  | Command_buffer_heap value -> value.lifetime
  | Command_buffer_drawable value -> value.lifetime

let rec command_texture_heap (value : texture) =
  match value.parent with
  | Texture_resource (Heap_resource heap) -> Some heap
  | Texture_resource (Device_resource _ | External_resource _)
  | Texture_io_surface_resource _ -> None
  | Texture_drawable_resource _ -> None
  | Texture_buffer_resource backing ->
      (match backing.buffer.parent with
       | Heap_resource heap -> Some heap
       | Device_resource _ | External_resource _ -> None)
  | Texture_view parent -> command_texture_heap parent

let command_resource_heap = function
  | Command_buffer_buffer { parent = Heap_resource heap; _ } -> Some heap
  | Command_buffer_buffer
      { parent = (Device_resource _ | External_resource _); _ } -> None
  | Command_buffer_acceleration_structure _ -> None
  | Command_buffer_texture texture -> command_texture_heap texture
  | Command_buffer_sampler _ -> None
  | Command_buffer_depth_stencil _ | Command_buffer_visible_table _
  | Command_buffer_intersection_table _ -> None
  | Command_buffer_render_pipeline _ | Command_residency_set _
  | Command_buffer_indirect _ | Command_buffer_fence _ -> None
  | Command_buffer_heap heap -> Some heap
  | Command_buffer_drawable _ -> None

let release_command_resources resources =
  let retained = !resources in
  resources := [];
  List.iter
    (fun resource ->
      detach (command_resource_lifetime resource);
      Option.iter (fun heap -> Atomic.decr heap.active_uses)
        (command_resource_heap resource))
    retained

let command4_resource_lifetime = function
  | Command4_argument_table table -> table.lifetime
  | Command4_buffer buffer -> buffer.lifetime
  | Command4_texture texture -> texture.lifetime
  | Command4_sampler sampler -> sampler.lifetime
  | Command4_depth_stencil state -> state.lifetime
  | Command4_compute_pipeline pipeline -> pipeline.lifetime
  | Command4_render_pipeline pipeline -> pipeline.lifetime
  | Command4_other lifetime -> lifetime

let command4_resource_heap = function
  | Command4_buffer { parent = Heap_resource heap; _ } -> Some heap
  | Command4_buffer
      { parent = (Device_resource _ | External_resource _); _ } -> None
  | Command4_texture texture -> command_texture_heap texture
  | Command4_argument_table _ | Command4_sampler _ | Command4_depth_stencil _
  | Command4_compute_pipeline _ | Command4_render_pipeline _ -> None
  | Command4_other _ -> None

let release_command4_resources resources =
  let retained = !resources in
  resources := [];
  List.iter
    (fun resource ->
      detach (command4_resource_lifetime resource);
      Option.iter (fun heap -> Atomic.decr heap.active_uses)
        (command4_resource_heap resource))
    retained

let retain_command4_argument_table (command_buffer : command4_buffer)
    (table : command4_argument_table) =
  let retained =
    List.exists
      (function
        | Command4_argument_table candidate ->
            candidate.lifetime == table.lifetime
        | Command4_buffer _ | Command4_texture _ | Command4_sampler _
        | Command4_depth_stencil _
        | Command4_compute_pipeline _ | Command4_render_pipeline _
        | Command4_other _ -> false)
      !(command_buffer.resources)
  in
  if not retained then begin
    attach table.lifetime;
    command_buffer.resources :=
      Command4_argument_table table :: !(command_buffer.resources)
  end

