module Device = struct
  type t = device

  type io_queue_type = Serial | Concurrent
  let io_queue_type_code = function Serial -> 0 | Concurrent -> 1

  let new_io_queue (value : t) ?(queue_type = Concurrent)
      ?(max_command_buffers = 2L) ?(max_commands_in_flight = 1L) ?label () =
    let operation = "Metal.Device.new_io_queue" in
    on_main operation (fun () ->
      match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () when max_command_buffers <= 0L || max_commands_in_flight < 0L ->
          error operation Invalid_argument "IO queue limits are invalid"
      | Ok () when option_exists contains_nul label ->
          error operation Invalid_argument "IO queue label contains a NUL byte"
      | Ok () ->
          match Metal_raw.io_queue_create value.raw (io_queue_type_code queue_type)
                  max_command_buffers max_commands_in_flight label with
          | Error message -> native_error operation message
          | Ok (raw, registry_id) when registry_id <> value.registry_id ->
              ignore (Metal_raw.destroy raw);
              error operation Device_mismatch
                "IO queue constructor returned another device identity"
          | Ok (raw, _registry_id) ->
              let queue : io_queue =
                { raw; lifetime = lifetime (); device = value }
              in
              attach value.lifetime;
              attach_finalizer queue queue.lifetime value.lifetime;
              Ok queue)

  let open_io_file (value : t) ?label path =
    let operation = "Metal.Device.open_io_file" in
    on_main operation (fun () ->
      match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () when path = "" || contains_nul path ->
          error operation Invalid_argument "IO file path is empty or contains NUL"
      | Ok () when option_exists contains_nul label ->
          error operation Invalid_argument "IO file label contains a NUL byte"
      | Ok () ->
          match Metal_raw.io_file_create value.raw path label with
          | Error message -> native_error operation message
          | Ok (raw, registry_id) when registry_id <> value.registry_id ->
              ignore (Metal_raw.destroy raw);
              error operation Device_mismatch
                "IO file constructor returned another device identity"
          | Ok (raw, _registry_id) ->
              let file : io_file =
                { raw; lifetime = lifetime (); device = value }
              in
              attach value.lifetime;
              attach_finalizer file file.lifetime value.lifetime;
              Ok file)

  let new_event(value:t)=let operation="Metal.Device.new_event"in on_main operation(fun()->match ensure_live operation value.lifetime with Error _ as e->e|Ok()->match Metal_raw.command_event_create value.raw with Error m->native_error operation m|Ok(raw,registry_id)when registry_id<>value.registry_id->ignore(Metal_raw.destroy raw);error operation Device_mismatch "event constructor returned another device identity"|Ok(raw,registry_id)->let event:command_event={raw;lifetime=lifetime();device=value;registry_id}in attach value.lifetime;attach_finalizer event event.lifetime value.lifetime;Ok event)
  let new_shared_event(value:t)=let operation="Metal.Device.new_shared_event"in on_main operation(fun()->match ensure_live operation value.lifetime with Error _ as e->e|Ok()->match Metal_raw.command_shared_event_create value.raw with Error m->native_error operation m|Ok(raw,registry_id)when registry_id<>value.registry_id->ignore(Metal_raw.destroy raw);error operation Device_mismatch "shared-event constructor returned another device identity"|Ok(raw,registry_id)->match Metal_raw.command_shared_event_value raw with Error m->ignore(Metal_raw.destroy raw);native_error operation m|Ok current->let event:command_shared_event={raw;lifetime=lifetime();device=value;registry_id;value=current}in attach value.lifetime;attach_finalizer event event.lifetime value.lifetime;Ok event)

  type family =
    | Apple1
    | Apple2
    | Apple3
    | Apple4
    | Apple5
    | Apple6
    | Apple7
    | Apple8
    | Apple9
    | Apple10
    | Mac2
    | Common1
    | Common2
    | Common3
    | Metal3
    | Metal4

  type info =
    { name : string
    ; registry_id : int64
    ; low_power : bool
    ; removable : bool
    ; headless : bool
    ; unified_memory : bool
    ; recommended_max_working_set_size : int64
    ; current_allocated_size : int64
    ; max_buffer_length : int64
    ; max_threadgroup_memory_length : int64
    ; raytracing : bool
    ; raytracing_from_render : bool
    ; dynamic_libraries : bool
    ; function_pointers : bool
    }

  type argument_buffers_tier = Tier_1 | Tier_2 | Unknown_argument_buffers_tier of int64
  type location = Built_in | Slot | External | Unspecified | Unknown_location of int64
  type read_write_texture_tier =
    | No_read_write_textures
    | Read_write_tier_1
    | Read_write_tier_2
    | Unknown_read_write_texture_tier of int64

  type capabilities =
    { argument_buffers_tier : argument_buffers_tier
    ; location : location
    ; location_number : int64
    ; max_argument_buffer_sampler_count : int64
    ; max_transfer_rate : int64
    ; maximum_concurrent_compilation_task_count : int64
    ; peer_count : int64
    ; peer_group_id : int64
    ; peer_index : int64
    ; programmable_sample_positions : bool
    ; raster_order_groups : bool
    ; read_write_texture_tier : read_write_texture_tier
    ; supports_32_bit_float_filtering : bool
    ; supports_32_bit_msaa : bool
    ; supports_primitive_motion_blur : bool
    ; supports_pull_model_interpolation : bool
    ; supports_query_texture_lod : bool
    ; supports_render_dynamic_libraries : bool
    ; supports_shader_barycentric_coordinates : bool
    }

  let system_default () =
    on_main "Metal.Device.system_default" (fun () ->
      match Metal_raw.default_device () with
      | Ok raw -> Ok (make_device raw)
      | Error message -> native_error "Metal.Device.system_default" message)

  let all () =
    on_main "Metal.Device.all" (fun () ->
      match Metal_raw.all_devices () with
      | Ok devices -> Ok (Array.to_list (Array.map make_device devices))
      | Error message -> native_error "Metal.Device.all" message)

  let generation (value : t) = Metal_raw.generation value.raw
  let registry_id (value : t) = value.registry_id
  let same = same_device
  let destroyed (value : t) = is_destroyed value.lifetime

  let info (value : t) =
    let operation = "Metal.Device.info" in
    on_main operation (fun () ->
      match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () ->
          (match Metal_raw.device_max_threadgroup_memory_length value.raw with
           | Error message -> native_error operation message
           | Ok max_threadgroup_memory_length ->
               Ok
                 { name = Metal_raw.device_name value.raw
                 ; registry_id = value.registry_id
                 ; low_power = Metal_raw.device_is_low_power value.raw
                 ; removable = Metal_raw.device_is_removable value.raw
                 ; headless = Metal_raw.device_is_headless value.raw
                 ; unified_memory = Metal_raw.device_has_unified_memory value.raw
                 ; recommended_max_working_set_size =
                     Metal_raw.device_recommended_max_working_set_size value.raw
                 ; current_allocated_size =
                     Metal_raw.device_current_allocated_size value.raw
                 ; max_buffer_length =
                     Metal_raw.device_max_buffer_length value.raw
                 ; max_threadgroup_memory_length
                 ; raytracing = Metal_raw.device_supports_raytracing value.raw
                 ; raytracing_from_render =
                     Metal_raw.device_supports_raytracing_from_render value.raw
                 ; dynamic_libraries =
                     Metal_raw.device_supports_dynamic_libraries value.raw
                 ; function_pointers =
                     Metal_raw.device_supports_function_pointers value.raw
                 }))

  let capabilities (value : t) =
    let operation = "Metal.Device.capabilities" in
    let argument_buffers_tier_of_code = function
      | 0L -> Tier_1
      | 1L -> Tier_2
      | code -> Unknown_argument_buffers_tier code
    in
    let location_of_code = function
      | 0L -> Built_in
      | 1L -> Slot
      | 2L -> External
      | 3L -> Unspecified
      | code -> Unknown_location code
    in
    let read_write_texture_tier_of_code = function
      | 0L -> No_read_write_textures
      | 1L -> Read_write_tier_1
      | 2L -> Read_write_tier_2
      | code -> Unknown_read_write_texture_tier code
    in
    let native = function
      | Ok value -> Ok value
      | Error message -> native_error operation message
    in
    on_main operation (fun () ->
      match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () ->
          let ( let* ) result callback = Result.bind result callback in
          let* argument_buffers_tier = native (Metal_raw.generated_mtl_device_argument_buffers_support value.raw) in
          let* location = native (Metal_raw.generated_mtl_device_location value.raw) in
          let* location_number = native (Metal_raw.generated_mtl_device_location_number value.raw) in
          let* max_argument_buffer_sampler_count = native (Metal_raw.generated_mtl_device_max_argument_buffer_sampler_count value.raw) in
          let* max_transfer_rate = native (Metal_raw.generated_mtl_device_max_transfer_rate value.raw) in
          let* maximum_concurrent_compilation_task_count = native (Metal_raw.generated_mtl_device_maximum_concurrent_compilation_task_count value.raw) in
          let* peer_count = native (Metal_raw.generated_mtl_device_peer_count value.raw) in
          let* peer_group_id = native (Metal_raw.generated_mtl_device_peer_group_id value.raw) in
          let* peer_index = native (Metal_raw.generated_mtl_device_peer_index value.raw) in
          let* programmable_sample_positions = native (Metal_raw.generated_mtl_device_are_programmable_sample_positions_supported value.raw) in
          let* raster_order_groups = native (Metal_raw.generated_mtl_device_are_raster_order_groups_supported value.raw) in
          let* read_write_texture_tier = native (Metal_raw.generated_mtl_device_read_write_texture_support value.raw) in
          let* supports_32_bit_float_filtering = native (Metal_raw.generated_mtl_device_supports32_bit_float_filtering value.raw) in
          let* supports_32_bit_msaa = native (Metal_raw.generated_mtl_device_supports32_bit_msaa value.raw) in
          let* supports_primitive_motion_blur = native (Metal_raw.generated_mtl_device_supports_primitive_motion_blur value.raw) in
          let* supports_pull_model_interpolation = native (Metal_raw.generated_mtl_device_supports_pull_model_interpolation value.raw) in
          let* supports_query_texture_lod = native (Metal_raw.generated_mtl_device_supports_query_texture_lod value.raw) in
          let* supports_render_dynamic_libraries = native (Metal_raw.generated_mtl_device_supports_render_dynamic_libraries value.raw) in
          let* supports_shader_barycentric_coordinates = native (Metal_raw.generated_mtl_device_supports_shader_barycentric_coordinates value.raw) in
          Ok
            { argument_buffers_tier = argument_buffers_tier_of_code argument_buffers_tier
            ; location = location_of_code location
            ; location_number
            ; max_argument_buffer_sampler_count
            ; max_transfer_rate
            ; maximum_concurrent_compilation_task_count
            ; peer_count
            ; peer_group_id
            ; peer_index
            ; programmable_sample_positions
            ; raster_order_groups
            ; read_write_texture_tier = read_write_texture_tier_of_code read_write_texture_tier
            ; supports_32_bit_float_filtering
            ; supports_32_bit_msaa
            ; supports_primitive_motion_blur
            ; supports_pull_model_interpolation
            ; supports_query_texture_lod
            ; supports_render_dynamic_libraries
            ; supports_shader_barycentric_coordinates
            })

