let ensure_metal4 operation (device : Device.t) =
  match ensure_live operation device.lifetime with
  | Error _ as failure -> failure
  | Ok ()
    when not
           (Metal_raw.device_supports_family device.raw
              (Device.family_code Device.Metal4)) ->
      error operation Unsupported "the Metal device does not support Metal 4"
  | Ok () -> Ok ()

module Pipeline_dataset = struct
  type t = pipeline_dataset

  type capture =
    | Descriptors
    | Binaries

  let capture_bit = function Descriptors -> 1 | Binaries -> 2

  let validate_captures operation captures =
    match captures with
    | [] ->
        error operation Invalid_argument
          "at least one pipeline-dataset capture mode is required"
    | _ when List.length captures <> List.length (List.sort_uniq compare captures)
      ->
        error operation Invalid_argument
          "pipeline-dataset capture modes contain a duplicate"
    | _ ->
        Ok
          (List.fold_left
             (fun bits capture -> bits lor capture_bit capture)
             0 captures)

  let create ~device captures =
    let operation = "Metal.Pipeline_dataset.create" in
    on_main operation (fun () ->
      let ( let* ) value callback = Result.bind value callback in
      let* () = ensure_metal4 operation device in
      let* configuration = validate_captures operation captures in
      match Metal_raw.pipeline_dataset_create device.raw configuration with
      | Error message -> native_error operation message
      | Ok raw ->
          let value : t =
            { raw; lifetime = lifetime (); device; configuration }
          in
          attach device.lifetime;
          attach_finalizer value value.lifetime device.lifetime;
          Ok value)

  let captures (value : t) =
    let captured bit capture reversed =
      if value.configuration land bit <> 0 then capture :: reversed
      else reversed
    in
    [] |> captured 1 Descriptors |> captured 2 Binaries |> List.rev

  let serialize_script (value : t) =
    let operation = "Metal.Pipeline_dataset.serialize_script" in
    on_main operation (fun () ->
      match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () when value.configuration land 1 = 0 ->
          error operation Invalid_state
            "pipeline descriptor capture was not enabled"
      | Ok () ->
          (match Metal_raw.pipeline_dataset_serialize_script value.raw with
           | Error message -> native_error operation message
           | Ok script -> Ok script))

  let serialize_archive (value : t) path =
    let operation = "Metal.Pipeline_dataset.serialize_archive" in
    on_main operation (fun () ->
      match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () when value.configuration land 2 = 0 ->
          error operation Invalid_state "pipeline binary capture was not enabled"
      | Ok () ->
          (match validate_absolute_path operation path with
           | Error _ as failure -> failure
           | Ok () ->
               match
                 Metal_raw.pipeline_dataset_serialize_archive value.raw path
               with
               | Error message -> native_error operation message
               | Ok () -> Ok ()))

  let device (value : t) = value.device
  let generation (value : t) = Metal_raw.generation value.raw
  let destroyed (value : t) = is_destroyed value.lifetime

  let destroy (value : t) =
    destroy_parent "Metal.Pipeline_dataset.destroy" value.lifetime value.raw
      (fun () -> detach value.device.lifetime)
end

module Binary_function = struct
  type t = binary_function
  type function_t = t

  let make device ~pipeline_independent ~name ~kind raw =
    let value : t =
      { raw
      ; lifetime = lifetime ()
      ; device
      ; pipeline_independent
      ; name
      ; kind
      }
    in
    attach device.lifetime;
    attach_finalizer value value.lifetime device.lifetime;
    value

  let device (value : t) = value.device
  let generation (value : t) = Metal_raw.generation value.raw
  let destroyed (value : t) = is_destroyed value.lifetime
  let pipeline_independent (value : t) = value.pipeline_independent
  let name (value : t) = value.name
  let kind (value : t) = value.kind

  let destroy (value : t) =
    destroy_leaf "Metal.Binary_function.destroy" value.lifetime value.raw
      (fun () -> detach value.device.lifetime)

  let render_pipeline_handle (source:t) ~(pipeline:render_pipeline) ~stage=
    let operation="Metal.Binary_function.render_pipeline_handle"in
    on_main operation(fun()->match ensure_live operation source.lifetime with Error _ as e->e|Ok()->match ensure_live operation pipeline.lifetime with Error _ as e->e|Ok()->Result.bind(ensure_same_device operation pipeline.device source.device)(fun()->Render_pipeline.Function_lookup.make operation pipeline[source.lifetime](Metal_raw.render93_function_handle pipeline.raw 1 source.raw(Render_pipeline.Function_lookup.stage_code stage))))

  module Descriptor = struct
    type t = binary_functions_descriptor
    type stage = Vertex | Fragment | Tile | Object | Mesh
    let stage_code = function Vertex->0|Fragment->1|Tile->2|Object->3|Mesh->4
    let create () =
      let operation="Metal.Binary_function.Descriptor.create" in
      on_main operation (fun () -> match Metal_raw.metal4_binary_functions_create() with
        | Error message->native_error operation message
        | Ok raw->
            let value={raw;lifetime=lifetime();descriptor_device=None;
              descriptor_stages=Array.make 5 []}in
            Gc.finalise(fun (value:t)->if Atomic.compare_and_set value.lifetime.destroyed false true then begin
              Array.iter(List.iter(fun(function_:binary_function)->detach function_.lifetime))value.descriptor_stages;
              ignore(Metal_raw.destroy value.raw)end)value;
            Ok value)
    let destroyed (value:t)=is_destroyed value.lifetime
    let validate operation (value:t) functions =
      let rec loop (device:device option) (seen:binary_function list)
          (remaining:binary_function list)=match remaining with
        |[]->Ok device
        |(function_:binary_function)::rest->
            if List.exists(fun(other:binary_function)->other.lifetime==function_.lifetime)seen then error operation Invalid_argument "duplicate binary function"
            else Result.bind(ensure_live operation function_.lifetime)(fun()->
              match device with
              |None->loop(Some function_.device)(function_::seen)rest
              |Some device->Result.bind(ensure_same_device operation device function_.device)(fun()->loop(Some device)(function_::seen)rest))in
      loop value.descriptor_device[]functions
    let set (value:t) stage functions =
      let operation="Metal.Binary_function.Descriptor.set"in
      on_main operation(fun()->Result.bind(ensure_live operation value.lifetime)(fun()->
        Result.bind(validate operation value functions)(fun device->
          match Metal_raw.metal4_binary_functions_set value.raw(stage_code stage)
            (Array.of_list(List.map(fun(function_:binary_function)->function_.raw)functions))with
          |Error message->native_error operation message
          |Ok()->let index=stage_code stage in
              List.iter(fun(function_:binary_function)->detach function_.lifetime)value.descriptor_stages.(index);
              List.iter(fun(function_:binary_function)->attach function_.lifetime)functions;
              value.descriptor_stages.(index)<-functions;value.descriptor_device<-device;Ok())) )
    let get (value:t) stage =
      let operation="Metal.Binary_function.Descriptor.get"in
      on_main operation(fun()->Result.bind(ensure_live operation value.lifetime)(fun()->
        match Metal_raw.metal4_binary_functions_get value.raw(stage_code stage)with
        |Error message->native_error operation message
        |Ok handles->
            let expected=value.descriptor_stages.(stage_code stage)in
            let rec verify index=
              if index=Array.length handles then if index=List.length expected then Ok expected else native_error operation "binary function array length changed"
              else match List.nth_opt expected index with
                |None->native_error operation "binary function array length changed"
                |Some(function_:binary_function)->
                    match Metal_raw.metal4_binary_function_info handles.(index)with
                    |Error message->native_error operation message
                    |Ok(name,kind) when name<>Some function_.name||Function.kind_of_code kind<>function_.kind->native_error operation "binary function identity changed"
                    |Ok _->verify(index+1)in
            let result=verify 0 in Array.iter(fun raw->ignore(Metal_raw.destroy raw))handles;result))
    let reset (value:t) =
      let operation="Metal.Binary_function.Descriptor.reset"in
      on_main operation(fun()->Result.bind(ensure_live operation value.lifetime)(fun()->
        match Metal_raw.metal4_binary_functions_reset value.raw with
        |Error message->native_error operation message
        |Ok()->Array.iteri(fun index functions->List.iter(fun(function_:binary_function)->detach function_.lifetime)functions;value.descriptor_stages.(index)<-[])value.descriptor_stages;value.descriptor_device<-None;Ok()))
    let relink_render_pipeline(value:t) (pipeline:render_pipeline)=let operation="Metal.Binary_function.Descriptor.relink_render_pipeline"in on_main operation(fun()->match ensure_live operation value.lifetime with Error _ as e->e|Ok()->match ensure_live operation pipeline.lifetime with Error _ as e->e|Ok()->(match value.descriptor_device with Some device->Result.bind(ensure_same_device operation pipeline.device device)(fun()->Render_pipeline.clone_relinked operation pipeline(Metal_raw.render93_relink pipeline.raw 1 value.raw))|None->Render_pipeline.clone_relinked operation pipeline(Metal_raw.render93_relink pipeline.raw 1 value.raw)))
    let destroy (value:t)=destroy_leaf "Metal.Binary_function.Descriptor.destroy" value.lifetime value.raw(fun()->Array.iter(List.iter(fun(function_:binary_function)->detach function_.lifetime))value.descriptor_stages)
  end
end

let validate_binary_function_source operation device
    (source : Function.t) ~name ~pipeline_independent =
  let ( let* ) value callback = Result.bind value callback in
  let* () = ensure_live operation source.lifetime in
  let* () = ensure_same_device operation device source.library.device in
  if name = "" || contains_nul name then
    error operation Invalid_argument
      "binary-function name must be nonempty and contain no NUL byte"
  else
    match Function.kind_of_code (Metal_raw.function_kind source.raw) with
    | (Function.Visible | Function.Intersection) as kind ->
        if
          pipeline_independent
          && not (Metal_raw.device_supports_function_pointers device.raw)
        then
          error operation Unsupported
            "pipeline-independent binary functions require Metal function-pointer support"
        else Ok kind
    | _ ->
        error operation Invalid_argument
          "binary-function source must be a visible or intersection function"

let binary_function_descriptor (source : Function.t) ~name
    ~pipeline_independent ~lookup_archives =
  ({ library = source.library.raw
   ; source_function = source.raw
   ; binary_name = name
   ; pipeline_independent
   ; lookup_archives
   }
    : Metal_raw.metal4_binary_function_descriptor)

module Pipeline_archive = struct
  type t = pipeline_archive

  let load_file ?label ~device path =
    let operation = "Metal.Pipeline_archive.load_file" in
    on_main operation (fun () ->
      let ( let* ) value callback = Result.bind value callback in
      let* () = ensure_metal4 operation device in
      let* () = validate_absolute_path operation path in
      if option_exists contains_nul label then
        error operation Invalid_argument
          "pipeline-archive label contains a NUL byte"
      else
        match Metal_raw.pipeline_archive_load_file device.raw path label with
        | Error message -> native_error operation message
        | Ok raw ->
            let value : t = { raw; lifetime = lifetime (); device } in
            attach device.lifetime;
            attach_finalizer value value.lifetime device.lifetime;
            Ok value)

  let device (value : t) = value.device
  let generation (value : t) = Metal_raw.generation value.raw
  let destroyed (value : t) = is_destroyed value.lifetime

  let label (value : t) =
    on_main "Metal.Pipeline_archive.label" (fun () ->
      match ensure_live "Metal.Pipeline_archive.label" value.lifetime with
      | Error _ as failure -> failure
      | Ok () -> Ok (Metal_raw.pipeline_archive_label value.raw))

  let load_binary_function ?(pipeline_independent = false) (value : t)
      ~(source : Function.t) ~name =
    let operation = "Metal.Pipeline_archive.load_binary_function" in
    on_main operation (fun () ->
      let ( let* ) result callback = Result.bind result callback in
      let* () = ensure_live operation value.lifetime in
      let* kind =
        validate_binary_function_source operation value.device source ~name
          ~pipeline_independent
      in
      let descriptor =
        binary_function_descriptor source ~name ~pipeline_independent
          ~lookup_archives:[||]
      in
      match
        Metal_raw.pipeline_archive_load_binary_function value.raw descriptor
      with
      | Error message -> native_error operation message
      | Ok raw ->
          Ok
            (Binary_function.make value.device ~pipeline_independent ~name
               ~kind raw))

  let compile_compute (value:t) ~(library:Library.t) function_name =
    let operation="Metal.Pipeline_archive.compile_compute"in
    if function_name=""||contains_nul function_name then error operation Invalid_argument "compute function name is invalid"else on_main operation(fun()->Result.bind(ensure_live operation value.lifetime)(fun()->Result.bind(ensure_live operation library.lifetime)(fun()->Result.bind(ensure_same_device operation value.device library.device)(fun()->
      let descriptor:Metal_raw.metal4_compute_descriptor={label=None;library=library.raw;function_name;reflection=false;threadgroup_size_multiple=false;max_total_threads=0L;required_threads_width=0L;required_threads_height=0L;required_threads_depth=0L;support_binary_linking=false;support_indirect_commands=false;preloaded_libraries=[||];max_call_stack_depth=0L;lookup_archives=[||];binary_linked_functions=[||];static_linking=None}in
      match Metal_raw.pipeline_archive_compute value.raw descriptor false with Error m->native_error operation m|Ok raw->Ok(Compute_pipeline.make value.device~reflection:false raw[||])))))

  let compile_render (value:t) ~(library:Library.t) ~vertex ?fragment ~color_format () =
    let operation="Metal.Pipeline_archive.compile_render"in
    let invalid_fragment=match fragment with Some name->name=""||contains_nul name|None->false in
    if vertex=""||contains_nul vertex||invalid_fragment then error operation Invalid_argument "render function name is invalid"else on_main operation(fun()->Result.bind(ensure_live operation value.lifetime)(fun()->Result.bind(ensure_live operation library.lifetime)(fun()->Result.bind(ensure_same_device operation value.device library.device)(fun()->
      let attachment=Render_pipeline.color_attachment color_format in let raw_attachment=Render_pipeline.raw_color_attachment attachment in
      let descriptor:Metal_raw.metal4_render_descriptor={label=None;library=library.raw;vertex_function=vertex;fragment_function=fragment;reflection=false;raster_sample_count=1L;color_attachments=[|raw_attachment|];rasterization_enabled=true;primitive_topology=3;support_indirect_commands=false;lookup_archives=[||];vertex_descriptor=None;support_vertex_binary_linking=false;support_fragment_binary_linking=false;vertex_dynamic_linking=None;fragment_dynamic_linking=None;vertex_static_linking=None;fragment_static_linking=None;alpha_to_coverage=false;alpha_to_one=false;max_vertex_amplification_count=1L;color_attachment_mapping=0}in
      match Metal_raw.pipeline_archive_render value.raw descriptor false with Error m->native_error operation m|Ok raw->let reflected:Metal_raw.render_pipeline_reflection={vertex_bindings=[||];fragment_bindings=[||];tile_bindings=[||];object_bindings=[||];mesh_bindings=[||]}in Ok(Render_pipeline.make value.device~kind:Render_pipeline.Render~raster_sample_count:1~alpha_to_coverage:false~alpha_to_one:false~max_vertex_amplification_count:1~color_attachment_mapping:Render_pipeline.Identity~color_formats:[color_format]~color_attachments:[attachment]~reflection:false raw reflected)))))

  let destroy (value : t) =
    destroy_leaf "Metal.Pipeline_archive.destroy" value.lifetime value.raw
      (fun () -> detach value.device.lifetime)
end

let validate_binary_functions operation device functions =
  let rec loop names seen = function
    | [] -> Ok ()
    | (function_ : binary_function) :: rest ->
        if
          List.exists
            (fun (value : binary_function) ->
              value.lifetime == function_.lifetime)
            seen
        then
          error operation Invalid_argument
            "binary-function list contains a duplicate handle"
        else
          (match ensure_live operation function_.lifetime with
           | Error _ as failure -> failure
           | Ok () ->
               (match ensure_same_device operation device function_.device with
                | Error _ as failure -> failure
                | Ok () ->
                    if List.mem function_.name names then
                      error operation Invalid_argument
                        "binary-function list contains a duplicate name"
                    else
                      loop (function_.name :: names) (function_ :: seen) rest))
  in
  loop [] [] functions

let validate_pipeline_archives operation device archives =
  let rec loop seen = function
    | [] -> Ok ()
    | (archive : pipeline_archive) :: rest ->
        if
          List.exists
            (fun (value : pipeline_archive) ->
              value.lifetime == archive.lifetime)
            seen
        then
          error operation Invalid_argument
            "pipeline-archive list contains a duplicate handle"
        else
          (match ensure_live operation archive.lifetime with
           | Error _ as failure -> failure
           | Ok () ->
               (match ensure_same_device operation device archive.device with
                | Error _ as failure -> failure
                | Ok () -> loop (archive :: seen) rest))
  in
  loop [] archives

module Compiler_task = struct
  type 'a t = 'a compiler_task

  type status =
    | None_
    | Scheduled
    | Compiling
    | Finished
    | Unknown_status of int

  type 'a poll =
    | Pending
    | Complete of ('a, error) result

  let make (compiler : compiler) raw_take decode raw =
    let take raw =
      Result.map (Option.map (Result.map decode)) (raw_take raw)
    in
    let value =
      { raw; lifetime = lifetime (); compiler; take; consumed = false }
    in
    attach compiler.lifetime;
    attach_finalizer value value.lifetime compiler.lifetime;
    value

  let status_of_code = function
    | 0 -> None_
    | 1 -> Scheduled
    | 2 -> Compiling
    | 3 -> Finished
    | code -> Unknown_status code

  let id (value : _ t) = Metal_raw.compiler_task_id value.raw
  let device (value : _ t) = value.compiler.device
  let generation (value : _ t) = Metal_raw.generation value.raw
  let destroyed (value : _ t) = is_destroyed value.lifetime
  let completion_capacity = Metal_raw.compiler_completion_capacity ()

  let status (value : _ t) =
    let operation = "Metal.Compiler_task.status" in
    on_main operation (fun () ->
      match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () -> Ok (status_of_code (Metal_raw.compiler_task_status value.raw)))

  let wait (value : _ t) =
    let operation = "Metal.Compiler_task.wait" in
    on_main operation (fun () ->
      match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () ->
          Metal_raw.compiler_task_wait value.raw;
          Ok ())

  let poll (value : 'a t) =
    let operation = "Metal.Compiler_task.poll" in
    on_main operation (fun () ->
      match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () when value.consumed ->
          error operation Invalid_state
            "compiler task completion was already consumed"
      | Ok () ->
          (match value.take value.raw with
           | Error message -> native_error operation message
           | Ok None -> Ok Pending
           | Ok (Some (Ok result)) ->
               value.consumed <- true;
               Ok (Complete (Ok result))
           | Ok (Some (Error message)) ->
               value.consumed <- true;
               Ok
                 (Complete
                    (Error { operation; kind = Native_error; message }))))

  let drain_completions ?(limit = completion_capacity) () =
    let operation = "Metal.Compiler_task.drain_completions" in
    on_main operation (fun () ->
      if limit <= 0 || limit > completion_capacity then
        error operation Invalid_argument
          "completion drain limit must be within the queue capacity"
      else
        let identifiers = Metal_raw.compiler_completion_drain limit in
        let dropped = Metal_raw.compiler_completion_dropped () in
        if dropped <> 0L then
          error operation Release_queue_overflow
            (Printf.sprintf
               "the bounded compiler-completion queue dropped %Ld identifier(s)"
               dropped)
        else Ok (Array.to_list identifiers))

  let dropped_completions () =
    let operation = "Metal.Compiler_task.dropped_completions" in
    on_main operation (fun () ->
      Ok (Metal_raw.compiler_completion_dropped ()))

  let pending_completions () =
    let operation = "Metal.Compiler_task.pending_completions" in
    on_main operation (fun () ->
      Ok (Metal_raw.compiler_completion_pending ()))

  let destroy (value : _ t) =
    destroy_leaf "Metal.Compiler_task.destroy" value.lifetime value.raw
      (fun () -> detach value.compiler.lifetime)
end

module Compiler = struct
  type t = compiler

  type static_function =
    { library : Library.t
    ; name : string
    }

  type static_linking =
    { functions : static_function list
    ; private_functions : static_function list
    ; groups : (string * static_function list) list
    }

  type stage_linking =
    { binary_functions : Binary_function.t list
    ; preloaded_libraries : Dynamic_library.t list
    ; max_call_stack_depth : int
    }

  let stage_linking ?(binary_functions = []) ?(preloaded_libraries = [])
      ?(max_call_stack_depth = 1) () =
    { binary_functions; preloaded_libraries; max_call_stack_depth }

  let validate_static_functions operation device category functions =
    let rec loop names reversed = function
      | [] -> Ok (Array.of_list (List.rev reversed))
      | function_ :: rest ->
          (match ensure_live operation function_.library.lifetime with
           | Error _ as failure -> failure
           | Ok () ->
               (match
                  ensure_same_device operation device function_.library.device
                with
                | Error _ as failure -> failure
                | Ok ()
                  when function_.name = "" || contains_nul function_.name ->
                    error operation Invalid_argument
                      (category
                       ^ " function name must be nonempty and contain no NUL byte")
                | Ok () when List.mem function_.name names ->
                    error operation Invalid_argument
                      (category ^ " function list contains a duplicate name")
                | Ok () ->
                    loop (function_.name :: names)
                      ((function_.library.raw, function_.name) :: reversed)
                      rest))
    in
    loop [] [] functions

  let validate_static_linking ?supports_public_linking operation device = function
    | None -> Ok None
    | Some ({ functions; private_functions; groups } : static_linking) ->
        let ( let* ) result callback = Result.bind result callback in
        if functions = [] && private_functions = [] && groups = [] then
          error operation Invalid_argument
            "static-linking descriptor must contain at least one function"
        else
          let* raw_functions =
            validate_static_functions operation device "public static-linked"
              functions
          in
          let* raw_private_functions =
            validate_static_functions operation device "private static-linked"
              private_functions
          in
          let public_names = List.map (fun value -> value.name) functions in
          let private_names =
            List.map (fun value -> value.name) private_functions
          in
          if List.exists (fun name -> List.mem name private_names) public_names
          then
            error operation Invalid_argument
              "a static-linked function cannot be both public and private"
          else
            let rec validate_groups names reversed = function
              | [] -> Ok (Array.of_list (List.rev reversed))
              | (name, _) :: _
                when name = "" || contains_nul name ->
                  error operation Invalid_argument
                    "static-link group name must be nonempty and contain no NUL byte"
              | (name, _) :: _ when List.mem name names ->
                  error operation Invalid_argument
                    "static-link groups contain a duplicate name"
              | (_, []) :: _ ->
                  error operation Invalid_argument
                    "static-link groups must contain at least one function"
              | (name, functions) :: rest ->
                  let* raw_group =
                    validate_static_functions operation device
                      ("static-link group " ^ name) functions
                  in
                  validate_groups (name :: names)
                    ((name, raw_group) :: reversed) rest
            in
            let* raw_groups = validate_groups [] [] groups in
            let supports_public_linking =
              match supports_public_linking with
              | Some supported -> supported
              | None ->
                  Metal_raw.device_supports_function_pointers device.raw
            in
            if
              (functions <> [] || groups <> [])
              && not supports_public_linking
            then
              error operation Unsupported
                "public static linking requires Metal function-pointer support"
            else
              Ok
                (Some
                   ({ functions = raw_functions
                    ; private_functions = raw_private_functions
                    ; groups = raw_groups
                    }
                     : Metal_raw.metal4_static_linking_descriptor))

  let make device dataset raw =
    let value : t = { raw; lifetime = lifetime (); device; dataset } in
    attach device.lifetime;
    Option.iter (fun (dataset : pipeline_dataset) -> attach dataset.lifetime)
      dataset;
    attach_finalizer
      ~on_finalize:(fun () ->
        Option.iter
          (fun (dataset : pipeline_dataset) -> detach dataset.lifetime)
          dataset)
      value value.lifetime device.lifetime;
    value

  let create ?label ?dataset device =
    let operation = "Metal.Compiler.create" in
    on_main operation (fun () ->
      let ( let* ) value callback = Result.bind value callback in
      let* () = ensure_metal4 operation device in
      if option_exists contains_nul label then
        error operation Invalid_argument "compiler label contains a NUL byte"
      else
        let* () =
          match dataset with
          | None -> Ok ()
          | Some (dataset : Pipeline_dataset.t) ->
              let* () = ensure_live operation dataset.lifetime in
              ensure_same_device operation device dataset.device
        in
        match
          Metal_raw.compiler_create device.raw
            (Option.map (fun (value : Pipeline_dataset.t) -> value.raw) dataset)
            label
        with
        | Error message -> native_error operation message
        | Ok raw -> Ok (make device dataset raw))

  let validate_library_source operation (value : t) ?name source =
    match ensure_live operation value.lifetime with
    | Error _ as failure -> failure
    | Ok () when source = "" ->
        error operation Invalid_argument "shader source is empty"
    | Ok () when contains_nul source ->
        error operation Invalid_argument "shader source contains a NUL byte"
    | Ok ()
      when option_exists
             (fun name -> name = "" || contains_nul name)
             name ->
        error operation Invalid_argument
          "library name must be nonempty and contain no NUL byte"
    | Ok () -> Ok ()

  let compile_source ?name (value : t) source =
    let operation = "Metal.Compiler.compile_source" in
    on_main operation (fun () ->
      match validate_library_source operation value ?name source with
      | Error _ as failure -> failure
      | Ok () ->
          (match Metal_raw.compiler_compile_library value.raw source name with
           | Error message -> native_error operation message
           | Ok raw -> Ok (Library.make value.device raw)))

  let compile_source_async ?name (value : t) source =
    let operation = "Metal.Compiler.compile_source_async" in
    on_main operation (fun () ->
      match validate_library_source operation value ?name source with
      | Error _ as failure -> failure
      | Ok () ->
          (match
             Metal_raw.compiler_compile_library_async value.raw source name
           with
           | Error message -> native_error operation message
           | Ok raw ->
               Ok
                 (Compiler_task.make value
                    Metal_raw.compiler_task_take_library
                    (fun raw -> Library.make value.device raw)
                    raw)))

  let validate_dynamic_library_source operation (value : t) ?label
      (library : Library.t) =
    let ( let* ) result callback = Result.bind result callback in
    let* () = ensure_live operation value.lifetime in
    let* () = ensure_live operation library.lifetime in
    let* () = ensure_same_device operation value.device library.device in
    let* () = Dynamic_library.check_support operation value.device in
    if option_exists contains_nul label then
      error operation Invalid_argument
        "dynamic-library label contains a NUL byte"
    else if
      Library.kind_of_code (Metal_raw.library_kind library.raw)
      <> Library.Dynamic_library_source
    then
      error operation Invalid_argument
        "source library was not compiled as a dynamic library"
    else
      match Metal_raw.library_install_name library.raw with
      | Some install_name when install_name <> "" -> Ok ()
      | _ ->
          error operation Invalid_argument
            "dynamic-library source has no install name"

  let create_dynamic_library ?label (value : t) (library : Library.t) =
    let operation = "Metal.Compiler.create_dynamic_library" in
    on_main operation (fun () ->
      match validate_dynamic_library_source operation value ?label library with
      | Error _ as failure -> failure
      | Ok () ->
          (match
             Metal_raw.compiler_create_dynamic_library value.raw library.raw
               label
           with
           | Error message -> native_error operation message
           | Ok raw -> Ok (Dynamic_library.make value.device raw)))

  let create_dynamic_library_async ?label (value : t)
      (library : Library.t) =
    let operation = "Metal.Compiler.create_dynamic_library_async" in
    on_main operation (fun () ->
      match validate_dynamic_library_source operation value ?label library with
      | Error _ as failure -> failure
      | Ok () ->
          (match
             Metal_raw.compiler_create_dynamic_library_async value.raw
               library.raw label
           with
           | Error message -> native_error operation message
           | Ok raw ->
               Ok
                 (Compiler_task.make value
                    Metal_raw.compiler_task_take_dynamic_library
                    (fun raw -> Dynamic_library.make value.device raw)
                    raw)))

  let validate_dynamic_library_path operation (value : t) ?label path =
    let ( let* ) result callback = Result.bind result callback in
    let* () = ensure_live operation value.lifetime in
    let* () = Dynamic_library.check_support operation value.device in
    let* () = validate_absolute_path operation path in
    if option_exists contains_nul label then
      error operation Invalid_argument
        "dynamic-library label contains a NUL byte"
    else Ok ()

  let load_dynamic_library ?label (value : t) path =
    let operation = "Metal.Compiler.load_dynamic_library" in
    on_main operation (fun () ->
      match validate_dynamic_library_path operation value ?label path with
      | Error _ as failure -> failure
      | Ok () ->
          (match
             Metal_raw.compiler_load_dynamic_library value.raw path label
           with
           | Error message -> native_error operation message
           | Ok raw -> Ok (Dynamic_library.make value.device raw)))

  let load_dynamic_library_async ?label (value : t) path =
    let operation = "Metal.Compiler.load_dynamic_library_async" in
    on_main operation (fun () ->
      match validate_dynamic_library_path operation value ?label path with
      | Error _ as failure -> failure
      | Ok () ->
          (match
             Metal_raw.compiler_load_dynamic_library_async value.raw path label
           with
           | Error message -> native_error operation message
           | Ok raw ->
               Ok
                 (Compiler_task.make value
                    Metal_raw.compiler_task_take_dynamic_library
                    (fun raw -> Dynamic_library.make value.device raw)
                    raw)))

  let prepare_binary_function operation (value : t) source ~name
      ~pipeline_independent ~lookup_archives =
    let ( let* ) result callback = Result.bind result callback in
    let* () = ensure_live operation value.lifetime in
    let* kind =
      validate_binary_function_source operation value.device source ~name
        ~pipeline_independent
    in
    let* () =
      validate_pipeline_archives operation value.device lookup_archives
    in
    let descriptor =
      binary_function_descriptor source ~name ~pipeline_independent
        ~lookup_archives:
          (Array.of_list
             (List.map
                (fun (archive : Pipeline_archive.t) -> archive.raw)
                lookup_archives))
    in
    Ok (kind, descriptor)

  let create_binary_function ?(pipeline_independent = false)
      ?(lookup_archives = []) (value : t) ~(source : Function.t) ~name =
    let operation = "Metal.Compiler.create_binary_function" in
    on_main operation (fun () ->
      let ( let* ) result callback = Result.bind result callback in
      let* kind, descriptor =
        prepare_binary_function operation value source ~name
          ~pipeline_independent ~lookup_archives
      in
      match Metal_raw.compiler_create_binary_function value.raw descriptor with
      | Error message -> native_error operation message
      | Ok raw ->
          Ok
            (Binary_function.make value.device ~pipeline_independent ~name
               ~kind raw))

  let create_binary_function_async ?(pipeline_independent = false)
      ?(lookup_archives = []) (value : t) ~(source : Function.t) ~name =
    let operation = "Metal.Compiler.create_binary_function_async" in
    on_main operation (fun () ->
      let ( let* ) result callback = Result.bind result callback in
      let* kind, descriptor =
        prepare_binary_function operation value source ~name
          ~pipeline_independent ~lookup_archives
      in
      match
        Metal_raw.compiler_create_binary_function_async value.raw descriptor
      with
      | Error message -> native_error operation message
      | Ok raw ->
          Ok
            (Compiler_task.make value
               Metal_raw.compiler_task_take_binary_function
               (fun raw ->
                 Binary_function.make value.device ~pipeline_independent
                   ~name ~kind raw)
               raw))

  let product3 x y z =
    if x > max_int / y then None
    else
      let xy = x * y in
      if xy > max_int / z then None else Some (xy * z)

  let with_compute_descriptor operation callback ?label ?(reflection = false)
      ?(threadgroup_size_multiple = false)
      ?max_total_threads_per_threadgroup ?required_threads_per_threadgroup
      ?(support_binary_linking = false)
      ?(support_indirect_command_buffers = false)
      ?static_linking ?(binary_linked_functions = [])
      ?(preloaded_libraries = []) ?max_call_stack_depth
      ?(lookup_archives = []) (value : t) ~(library : Library.t)
      function_name =
    on_main operation (fun () ->
      let ( let* ) result callback = Result.bind result callback in
      let* () = ensure_live operation value.lifetime in
      let* () = ensure_live operation library.lifetime in
      let* () = ensure_same_device operation value.device library.device in
      if function_name = "" || contains_nul function_name then
        error operation Invalid_argument
          "compute function name must be nonempty and contain no NUL byte"
      else if option_exists contains_nul label then
        error operation Invalid_argument
          "compute-pipeline label contains a NUL byte"
      else if
        not
          (Array.exists (String.equal function_name)
             (Metal_raw.library_function_names library.raw))
      then
        error operation Invalid_argument
          "compute function is absent from the source library"
      else
        let* max_total_threads =
          match max_total_threads_per_threadgroup with
          | None -> Ok 0L
          | Some count when count <= 0 ->
              error operation Invalid_argument
                "maximum total threads must be positive"
          | Some count -> Ok (Int64.of_int count)
        in
        let* required_width, required_height, required_depth =
          match required_threads_per_threadgroup with
          | None -> Ok (0L, 0L, 0L)
          | Some (width, height, depth)
            when width <= 0 || height <= 0 || depth <= 0 ->
              error operation Invalid_argument
                "required threadgroup dimensions must be positive"
          | Some (width, height, depth) ->
              (match product3 width height depth with
               | None ->
                   error operation Invalid_argument
                     "required threadgroup cardinality overflows an OCaml integer"
               | Some product
                 when max_total_threads <> 0L
                      && Int64.of_int product <> max_total_threads ->
                   error operation Invalid_argument
                     "configured maximum threads must equal the required threadgroup cardinality"
               | Some _ ->
                   Ok
                     ( Int64.of_int width
                     , Int64.of_int height
                     , Int64.of_int depth ))
        in
        if
          support_binary_linking
          && not
               (Metal_raw.device_supports_function_pointers value.device.raw)
        then
          error operation Unsupported
            "binary linking requires Metal function-pointer support"
        else
          let* () =
            validate_dynamic_libraries operation value.device
              preloaded_libraries
          in
          let* () =
            validate_binary_functions operation value.device
              binary_linked_functions
          in
          let* static_linking =
            validate_static_linking operation value.device static_linking
          in
          if binary_linked_functions <> [] && not support_binary_linking then
            error operation Invalid_argument
              "binary linked functions require binary-linking support"
          else if
            preloaded_libraries <> []
            && not
                 (Metal_raw.device_supports_dynamic_libraries value.device.raw)
          then
            error operation Unsupported
              "preloaded libraries require Metal dynamic-library support"
          else
            let* max_call_stack_depth =
              match max_call_stack_depth with
              | None ->
                  Ok
                    (if
                       preloaded_libraries = []
                       && binary_linked_functions = []
                     then 0L
                     else 1L)
              | Some depth when depth <= 0 ->
                  error operation Invalid_argument
                    "maximum call-stack depth must be positive"
              | Some depth -> Ok (Int64.of_int depth)
            in
            let* () =
              validate_pipeline_archives operation value.device lookup_archives
            in
            let descriptor : Metal_raw.metal4_compute_descriptor =
              { label
              ; library = library.raw
              ; function_name
              ; reflection
              ; threadgroup_size_multiple
              ; max_total_threads
              ; required_threads_width = required_width
              ; required_threads_height = required_height
              ; required_threads_depth = required_depth
              ; support_binary_linking
              ; support_indirect_commands = support_indirect_command_buffers
              ; preloaded_libraries =
                  Array.of_list
                    (List.map
                       (fun (library : Dynamic_library.t) -> library.raw)
                       preloaded_libraries)
              ; max_call_stack_depth
              ; lookup_archives =
                  Array.of_list
                    (List.map
                       (fun (archive : Pipeline_archive.t) -> archive.raw)
                       lookup_archives)
              ; binary_linked_functions =
                  Array.of_list
                    (List.map
                       (fun (function_ : Binary_function.t) -> function_.raw)
                       binary_linked_functions)
              ; static_linking
              }
            in
            callback reflection descriptor)

  let create_compute_pipeline ?label ?(reflection = false)
      ?(threadgroup_size_multiple = false)
      ?max_total_threads_per_threadgroup ?required_threads_per_threadgroup
      ?(support_binary_linking = false)
      ?(support_indirect_command_buffers = false)
      ?static_linking ?(binary_linked_functions = [])
      ?(preloaded_libraries = []) ?max_call_stack_depth
      ?(lookup_archives = []) (value : t) ~(library : Library.t)
      function_name =
    let operation = "Metal.Compiler.create_compute_pipeline" in
    with_compute_descriptor operation
      (fun reflection descriptor ->
        match
          Metal_raw.compiler_create_compute_pipeline value.raw descriptor
        with
        | Error message -> native_error operation message
        | Ok (raw, raw_bindings) ->
            Ok
              (Compute_pipeline.make value.device ~reflection raw
                 raw_bindings))
      ?label ~reflection ~threadgroup_size_multiple
      ?max_total_threads_per_threadgroup ?required_threads_per_threadgroup
      ~support_binary_linking ~support_indirect_command_buffers
      ?static_linking ~binary_linked_functions ~preloaded_libraries
      ?max_call_stack_depth ~lookup_archives value ~library function_name

  let create_compute_pipeline_async ?label ?(reflection = false)
      ?(threadgroup_size_multiple = false)
      ?max_total_threads_per_threadgroup ?required_threads_per_threadgroup
      ?(support_binary_linking = false)
      ?(support_indirect_command_buffers = false)
      ?static_linking ?(binary_linked_functions = [])
      ?(preloaded_libraries = []) ?max_call_stack_depth
      ?(lookup_archives = []) (value : t) ~(library : Library.t)
      function_name =
    let operation = "Metal.Compiler.create_compute_pipeline_async" in
    with_compute_descriptor operation
      (fun reflection descriptor ->
        let uses_dynamic_linking =
          Array.length descriptor.preloaded_libraries <> 0
          || Array.length descriptor.binary_linked_functions <> 0
          || descriptor.max_call_stack_depth <> 0L
        in
        if
          uses_dynamic_linking
          && not
               (Metal_raw.device_supports_family value.device.raw
                  (Device.family_code Device.Apple9))
        then
          error operation Unsupported
            "asynchronous dynamic compute linking requires an Apple9/M3-or-newer GPU"
        else
          match
            Metal_raw.compiler_create_compute_pipeline_async value.raw
              descriptor
          with
          | Error message -> native_error operation message
          | Ok raw ->
              Ok
                (Compiler_task.make value
                   Metal_raw.compiler_task_take_compute_pipeline
                   (fun (raw, raw_bindings) ->
                     Compute_pipeline.make value.device ~reflection raw
                       raw_bindings)
                   raw))
      ?label ~reflection ~threadgroup_size_multiple
      ?max_total_threads_per_threadgroup ?required_threads_per_threadgroup
      ~support_binary_linking ~support_indirect_command_buffers
      ?static_linking ~binary_linked_functions ~preloaded_libraries
      ?max_call_stack_depth ~lookup_archives value ~library function_name

  let validate_pipeline_entry operation (library : Library.t) ~stage name =
    if name = "" || contains_nul name then
      error operation Invalid_argument
        (stage ^ " function name must be nonempty and contain no NUL byte")
    else if
      not
        (Array.exists (String.equal name)
           (Metal_raw.library_function_names library.raw))
    then
      error operation Invalid_argument
        (stage ^ " function is absent from the source library")
    else Ok ()

  let validate_optional_pipeline_entry operation library ~stage = function
    | None -> Ok ()
    | Some name -> validate_pipeline_entry operation library ~stage name

  let resolve_color_attachments operation ?color_formats ?color_attachments () =
    match color_formats, color_attachments with
    | Some _, Some _ ->
        error operation Invalid_argument
          "color_formats and color_attachments are mutually exclusive"
    | Some formats, None ->
        Ok (List.map Render_pipeline.color_attachment formats)
    | None, Some attachments -> Ok attachments
    | None, None ->
        Ok [ Render_pipeline.color_attachment Texture.Bgra8_unorm ]

  let raw_stage_dynamic_linking operation device ~support_binary_linking
      ~stage = function
    | None -> Ok None
    | Some (linking : stage_linking) ->
        let ( let* ) result callback = Result.bind result callback in
        if linking.max_call_stack_depth <= 0 then
          error operation Invalid_argument
            (stage ^ " dynamic-link call-stack depth must be positive")
        else
          let* () =
            validate_binary_functions operation device linking.binary_functions
          in
          let* () =
            validate_dynamic_libraries operation device
              linking.preloaded_libraries
          in
          if linking.binary_functions <> [] && not support_binary_linking then
            error operation Invalid_argument
              (stage ^ " binary functions require binary-linking support")
          else if
            linking.preloaded_libraries <> []
            && not (Metal_raw.device_supports_dynamic_libraries device.raw)
          then
            error operation Unsupported
              (stage ^ " preloaded libraries require dynamic-library support")
          else
            Ok
              (Some
                 ({ max_call_stack_depth =
                      Int64.of_int linking.max_call_stack_depth
                  ; binary_linked_functions =
                      Array.of_list
                        (List.map
                           (fun (function_ : Binary_function.t) -> function_.raw)
                           linking.binary_functions)
                  ; preloaded_libraries =
                      Array.of_list
                        (List.map
                           (fun (library : Dynamic_library.t) -> library.raw)
                           linking.preloaded_libraries)
                  }
                   : Metal_raw.metal4_stage_dynamic_linking_descriptor))

  let validate_render_target operation (device : Device.t) ~has_fragment
      ~raster_sample_count ~color_attachments ~rasterization_enabled =
    if rasterization_enabled <> has_fragment then
      error operation Invalid_argument
        "rasterization requires exactly one fragment function"
    else if
      (rasterization_enabled && color_attachments = [])
      || ((not rasterization_enabled) && color_attachments <> [])
      || List.length color_attachments > 8
    then
      error operation Invalid_argument
        "render color attachments must match rasterization and not exceed eight"
    else if
      List.exists
        (fun (attachment : Render_pipeline.color_attachment) ->
          Metal_format.is_depth_or_stencil attachment.format)
        color_attachments
    then
      error operation Invalid_argument
        "render color attachments require color pixel formats"
    else if
      List.exists
        (fun (attachment : Render_pipeline.color_attachment) ->
          List.length attachment.write_mask
          <> List.length (List.sort_uniq compare attachment.write_mask))
        color_attachments
    then
      error operation Invalid_argument
        "render color-write masks contain duplicate channels"
    else if raster_sample_count <= 0 then
      error operation Invalid_argument
        "render raster sample count must be positive"
    else if
      not
        (Metal_raw.device_supports_texture_sample_count device.raw
           raster_sample_count)
    then
      error operation Unsupported
        "the Metal device does not support the render sample count"
    else
      Ok
        ( Int64.of_int raster_sample_count
        , List.map
            (fun (attachment : Render_pipeline.color_attachment) ->
              attachment.format)
            color_attachments
        , Array.of_list
            (List.map Render_pipeline.raw_color_attachment color_attachments) )

  let with_render_descriptor operation callback ?label ?fragment
      ?(reflection = false) ?(raster_sample_count = 1)
      ?color_formats ?color_attachments ?vertex_descriptor
      ?(alpha_to_coverage = false) ?(alpha_to_one = false)
      ?(max_vertex_amplification_count = 1)
      ?(color_attachment_mapping = Render_pipeline.Identity)
      ?(support_vertex_binary_linking = false)
      ?(support_fragment_binary_linking = false) ?vertex_dynamic_linking
      ?fragment_dynamic_linking ?vertex_static_linking
      ?fragment_static_linking
      ?(rasterization_enabled = true)
      ?(primitive_topology = Render_pipeline.Triangle)
      ?(support_indirect_command_buffers = false) ?(lookup_archives = [])
      (value : t) ~(library : Library.t) ~vertex =
    on_main operation (fun () ->
      let ( let* ) result callback = Result.bind result callback in
      let* () = ensure_live operation value.lifetime in
      let* () = ensure_live operation library.lifetime in
      let* () = ensure_same_device operation value.device library.device in
      let* () = validate_pipeline_entry operation library ~stage:"vertex" vertex in
      let* () =
        validate_optional_pipeline_entry operation library ~stage:"fragment"
          fragment
      in
      let render_function_pointers =
        Metal_raw.device_supports_function_pointers_from_render value.device.raw
      in
      if option_exists contains_nul label then
        error operation Invalid_argument
          "render-pipeline label contains a NUL byte"
      else if max_vertex_amplification_count <= 0 then
        error operation Invalid_argument
          "maximum vertex amplification count must be positive"
      else if
        not
          (Metal_raw.device_supports_vertex_amplification_count
             value.device.raw max_vertex_amplification_count)
      then
        error operation Unsupported
          "the Metal device does not support the vertex amplification count"
      else if
        Option.is_none fragment
        && (support_fragment_binary_linking
            || Option.is_some fragment_dynamic_linking
            || Option.is_some fragment_static_linking)
      then
        error operation Invalid_argument
          "fragment-stage linking requires a fragment function"
      else
        let* color_attachments =
          resolve_color_attachments operation ?color_formats ?color_attachments
            ()
        in
        let* raster_sample_count, color_formats, raw_color_attachments =
          validate_render_target operation value.device
            ~has_fragment:(Option.is_some fragment) ~raster_sample_count
            ~color_attachments ~rasterization_enabled
        in
        let* () =
          if
            (support_vertex_binary_linking
            || support_fragment_binary_linking)
            && not render_function_pointers
          then
            error operation Unsupported
              "render binary linking requires function-pointer support"
          else Ok ()
        in
        let* vertex_dynamic_linking =
          raw_stage_dynamic_linking operation value.device
            ~support_binary_linking:support_vertex_binary_linking
            ~stage:"vertex" vertex_dynamic_linking
        in
        let* fragment_dynamic_linking =
          raw_stage_dynamic_linking operation value.device
            ~support_binary_linking:support_fragment_binary_linking
            ~stage:"fragment" fragment_dynamic_linking
        in
        let* vertex_static_linking =
          validate_static_linking
            ~supports_public_linking:render_function_pointers operation
            value.device vertex_static_linking
        in
        let* fragment_static_linking =
          validate_static_linking
            ~supports_public_linking:render_function_pointers operation
            value.device fragment_static_linking
        in
        let* () =
          validate_pipeline_archives operation value.device lookup_archives
        in
        let descriptor : Metal_raw.metal4_render_descriptor =
          { label
          ; library = library.raw
          ; vertex_function = vertex
          ; fragment_function = fragment
          ; reflection
          ; raster_sample_count
          ; color_attachments = raw_color_attachments
          ; rasterization_enabled
          ; primitive_topology =
              Render_pipeline.topology_code primitive_topology
          ; support_indirect_commands = support_indirect_command_buffers
          ; lookup_archives =
              Array.of_list
                (List.map
                   (fun (archive : Pipeline_archive.t) -> archive.raw)
                   lookup_archives)
          ; vertex_descriptor = Option.map Vertex_descriptor.raw vertex_descriptor
          ; support_vertex_binary_linking
          ; support_fragment_binary_linking
          ; vertex_dynamic_linking
          ; fragment_dynamic_linking
          ; vertex_static_linking
          ; fragment_static_linking
          ; alpha_to_coverage
          ; alpha_to_one
          ; max_vertex_amplification_count =
              Int64.of_int max_vertex_amplification_count
          ; color_attachment_mapping =
              Render_pipeline.color_attachment_mapping_code
                color_attachment_mapping
          }
        in
        callback reflection vertex_descriptor color_attachments color_formats
          descriptor)

  let create_render_pipeline ?label ?fragment ?(reflection = false)
      ?(raster_sample_count = 1)
      ?color_formats ?color_attachments ?vertex_descriptor
      ?(alpha_to_coverage = false) ?(alpha_to_one = false)
      ?(max_vertex_amplification_count = 1)
      ?(color_attachment_mapping = Render_pipeline.Identity)
      ?(support_vertex_binary_linking = false)
      ?(support_fragment_binary_linking = false) ?vertex_dynamic_linking
      ?fragment_dynamic_linking ?vertex_static_linking
      ?fragment_static_linking
      ?(rasterization_enabled = true)
