                       ~max_vertex_amplification_count
                       ~color_attachment_mapping
                       ~color_formats ~color_attachments ?vertex_descriptor
                       ~reflection raw raw_reflection)
                   raw))
      ?label ?fragment ~reflection ~raster_sample_count ?color_formats
      ?color_attachments ?vertex_descriptor
      ~alpha_to_coverage ~alpha_to_one ~max_vertex_amplification_count
      ~color_attachment_mapping
      ~support_vertex_binary_linking ~support_fragment_binary_linking
      ?vertex_dynamic_linking ?fragment_dynamic_linking
      ?vertex_static_linking ?fragment_static_linking
      ~rasterization_enabled ~primitive_topology
      ~support_indirect_command_buffers ~lookup_archives value ~library
      ~vertex

  let validate_threadgroup_constraint operation ~stage ~maximum ~required =
    let maximum =
      match maximum with
      | None -> Ok 0L
      | Some count when count <= 0 ->
          error operation Invalid_argument
            (stage ^ " maximum total threads must be positive")
      | Some count -> Ok (Int64.of_int count)
    in
    let ( let* ) result callback = Result.bind result callback in
    let* maximum = maximum in
    match required with
    | None -> Ok (maximum, 0L, 0L, 0L)
    | Some (width, height, depth)
      when width <= 0 || height <= 0 || depth <= 0 ->
        error operation Invalid_argument
          (stage ^ " required threadgroup dimensions must be positive")
    | Some (width, height, depth) ->
        (match product3 width height depth with
         | None ->
             error operation Invalid_argument
               (stage ^ " required threadgroup cardinality overflows an OCaml integer")
         | Some product
           when maximum <> 0L && Int64.of_int product <> maximum ->
             error operation Invalid_argument
               (stage ^ " maximum threads must equal required threadgroup cardinality")
         | Some _ ->
             Ok
               ( maximum
               , Int64.of_int width
               , Int64.of_int height
               , Int64.of_int depth ))

  let with_mesh_descriptor operation callback ?label ?object_function
      ?fragment ?(reflection = false)
      ?max_total_threads_per_object_threadgroup
      ?max_total_threads_per_mesh_threadgroup
      ?required_threads_per_object_threadgroup
      ?required_threads_per_mesh_threadgroup
      ?(object_threadgroup_size_multiple = false)
      ?(mesh_threadgroup_size_multiple = false) ?payload_memory_length
      ?max_total_threadgroups_per_mesh_grid ?(raster_sample_count = 1)
      ?color_formats ?color_attachments
      ?(alpha_to_coverage = false) ?(alpha_to_one = false)
      ?(max_vertex_amplification_count = 1)
      ?(color_attachment_mapping = Render_pipeline.Identity)
      ?(support_object_binary_linking = false)
      ?(support_mesh_binary_linking = false)
      ?(support_fragment_binary_linking = false) ?object_dynamic_linking
      ?mesh_dynamic_linking ?fragment_dynamic_linking ?object_static_linking
      ?mesh_static_linking ?fragment_static_linking
      ?(rasterization_enabled = true)
      ?(support_indirect_command_buffers = false) ?(lookup_archives = [])
      (value : t) ~(library : Library.t) ~mesh =
    on_main operation (fun () ->
      let ( let* ) result callback = Result.bind result callback in
      let* () = ensure_live operation value.lifetime in
      let* () = ensure_live operation library.lifetime in
      let* () = ensure_same_device operation value.device library.device in
      let* () = validate_pipeline_entry operation library ~stage:"mesh" mesh in
      let* () =
        validate_optional_pipeline_entry operation library ~stage:"object"
          object_function
      in
      let* () =
        validate_optional_pipeline_entry operation library ~stage:"fragment"
          fragment
      in
      let render_function_pointers =
        Metal_raw.device_supports_function_pointers_from_render value.device.raw
      in
      if option_exists contains_nul label then
        error operation Invalid_argument
          "mesh-pipeline label contains a NUL byte"
      else if max_vertex_amplification_count <= 0 then
        error operation Invalid_argument
          "maximum vertex amplification count must be positive"
      else if
        not
          (Metal_raw.device_supports_vertex_amplification_count
             value.device.raw max_vertex_amplification_count)
      then
        error operation Unsupported
          "the Metal device does not support the vertex amplification count"
      else if
        not
          (Metal_raw.device_supports_family value.device.raw
             (Device.family_code Device.Apple7)
           || Metal_raw.device_supports_family value.device.raw
                (Device.family_code Device.Mac2))
      then
        error operation Unsupported
          "mesh shading requires an Apple7-or-newer or Mac2 GPU"
      else if
        Option.is_none object_function
        && (Option.is_some max_total_threads_per_object_threadgroup
            || Option.is_some required_threads_per_object_threadgroup
            || object_threadgroup_size_multiple
            || Option.is_some payload_memory_length
            || Option.is_some max_total_threadgroups_per_mesh_grid
            || support_object_binary_linking
            || Option.is_some object_dynamic_linking
            || Option.is_some object_static_linking)
      then
        error operation Invalid_argument
          "object-stage configuration requires an object function"
      else if
        Option.is_none fragment
        && (support_fragment_binary_linking
            || Option.is_some fragment_dynamic_linking
            || Option.is_some fragment_static_linking)
      then
        error operation Invalid_argument
          "fragment-stage linking requires a fragment function"
      else if
        (support_object_binary_linking || support_mesh_binary_linking)
        && not
             (Metal_raw.device_supports_family value.device.raw
                (Device.family_code Device.Apple9))
      then
        error operation Unsupported
          "object/mesh binary linking requires an Apple9/M3-or-newer GPU"
      else if
        (support_object_binary_linking || support_mesh_binary_linking
        || support_fragment_binary_linking)
        && not render_function_pointers
      then
        error operation Unsupported
          "mesh binary linking requires Metal function-pointer support"
      else if
        support_indirect_command_buffers
        && not
             (Metal_raw.device_supports_family value.device.raw
                (Device.family_code Device.Apple9))
      then
        error operation Unsupported
          "indirect mesh draws require an Apple9/M3-or-newer GPU"
      else
        let* max_object, object_width, object_height, object_depth =
          validate_threadgroup_constraint operation ~stage:"object"
            ~maximum:max_total_threads_per_object_threadgroup
            ~required:required_threads_per_object_threadgroup
        in
        let* max_mesh, mesh_width, mesh_height, mesh_depth =
          validate_threadgroup_constraint operation ~stage:"mesh"
            ~maximum:max_total_threads_per_mesh_threadgroup
            ~required:required_threads_per_mesh_threadgroup
        in
        let* payload_memory_length =
          match payload_memory_length with
          | None -> Ok 0L
          | Some length when length <= 0 || length > 16_384 ->
              error operation Invalid_argument
                "mesh payload length must be between 1 and 16384 bytes"
          | Some length -> Ok (Int64.of_int length)
        in
        let* max_total_threadgroups_per_mesh_grid =
          match max_total_threadgroups_per_mesh_grid with
          | None -> Ok 0L
          | Some count when count <= 0 ->
              error operation Invalid_argument
                "maximum mesh-grid threadgroups must be positive"
          | Some count -> Ok (Int64.of_int count)
        in
        let* color_attachments =
          resolve_color_attachments operation ?color_formats ?color_attachments
            ()
        in
        let* raster_sample_count, color_formats, raw_color_attachments =
          validate_render_target operation value.device
            ~has_fragment:(Option.is_some fragment) ~raster_sample_count
            ~color_attachments ~rasterization_enabled
        in
        let* object_dynamic_linking =
          raw_stage_dynamic_linking operation value.device
            ~support_binary_linking:support_object_binary_linking
            ~stage:"object" object_dynamic_linking
        in
        let* mesh_dynamic_linking =
          raw_stage_dynamic_linking operation value.device
            ~support_binary_linking:support_mesh_binary_linking ~stage:"mesh"
            mesh_dynamic_linking
        in
        let* fragment_dynamic_linking =
          raw_stage_dynamic_linking operation value.device
            ~support_binary_linking:support_fragment_binary_linking
            ~stage:"fragment" fragment_dynamic_linking
        in
        let* object_static_linking =
          validate_static_linking
            ~supports_public_linking:render_function_pointers operation
            value.device object_static_linking
        in
        let* mesh_static_linking =
          validate_static_linking
            ~supports_public_linking:render_function_pointers operation
            value.device mesh_static_linking
        in
        let* fragment_static_linking =
          validate_static_linking
            ~supports_public_linking:render_function_pointers operation
            value.device fragment_static_linking
        in
        let* () =
          validate_pipeline_archives operation value.device lookup_archives
        in
        let descriptor : Metal_raw.metal4_mesh_descriptor =
          { label
          ; library = library.raw
          ; object_function
          ; mesh_function = mesh
          ; fragment_function = fragment
          ; reflection
          ; max_total_object_threads = max_object
          ; max_total_mesh_threads = max_mesh
          ; required_object_width = object_width
          ; required_object_height = object_height
          ; required_object_depth = object_depth
          ; required_mesh_width = mesh_width
          ; required_mesh_height = mesh_height
          ; required_mesh_depth = mesh_depth
          ; object_threadgroup_size_multiple
          ; mesh_threadgroup_size_multiple
          ; payload_memory_length
          ; max_total_threadgroups_per_mesh_grid
          ; raster_sample_count
          ; color_attachments = raw_color_attachments
          ; rasterization_enabled
          ; support_indirect_commands = support_indirect_command_buffers
          ; lookup_archives =
              Array.of_list
                (List.map
                   (fun (archive : Pipeline_archive.t) -> archive.raw)
                   lookup_archives)
          ; support_object_binary_linking
          ; support_mesh_binary_linking
          ; support_fragment_binary_linking
          ; object_dynamic_linking
          ; mesh_dynamic_linking
          ; fragment_dynamic_linking
          ; object_static_linking
          ; mesh_static_linking
          ; fragment_static_linking
          ; alpha_to_coverage
          ; alpha_to_one
          ; max_vertex_amplification_count =
              Int64.of_int max_vertex_amplification_count
          ; color_attachment_mapping =
              Render_pipeline.color_attachment_mapping_code
                color_attachment_mapping
          }
        in
        callback reflection color_attachments color_formats descriptor)

  let mesh_pipeline_constraints ?object_function
      ?max_total_threads_per_object_threadgroup
      ?max_total_threads_per_mesh_threadgroup
      ?required_threads_per_object_threadgroup
      ?required_threads_per_mesh_threadgroup ~object_threadgroup_size_multiple
      ~mesh_threadgroup_size_multiple ?max_total_threadgroups_per_mesh_grid () =
    { has_object_stage = Option.is_some object_function
    ; configured_max_object_threads =
        max_total_threads_per_object_threadgroup
    ; configured_max_mesh_threads = max_total_threads_per_mesh_threadgroup
    ; required_object_threads = required_threads_per_object_threadgroup
    ; required_mesh_threads = required_threads_per_mesh_threadgroup
    ; object_threadgroup_size_multiple
    ; mesh_threadgroup_size_multiple
    ; configured_max_mesh_threadgroups = max_total_threadgroups_per_mesh_grid
    }

  let specialization_descriptor operation (value:t) ~(source:Render_pipeline.t)
      ~(library:Library.t) ~vertex ?fragment ~color_format () =
    let invalid_fragment=match fragment with Some name->name=""||contains_nul name|None->false in
    Result.bind(ensure_live operation value.lifetime)(fun()->Result.bind(ensure_live operation source.lifetime)(fun()->Result.bind(ensure_live operation library.lifetime)(fun()->Result.bind(ensure_same_device operation value.device source.device)(fun()->Result.bind(ensure_same_device operation value.device library.device)(fun()->
      if source.kind<>Render_pipeline.Render||source.color_formats<>[color_format] then error operation Invalid_argument "specialization source metadata does not match descriptor"else if vertex=""||contains_nul vertex||invalid_fragment then error operation Invalid_argument "specialization function name is invalid"else
      let attachment=Render_pipeline.color_attachment color_format in let raw_attachment=Render_pipeline.raw_color_attachment attachment in
      let descriptor:Metal_raw.metal4_render_descriptor={label=None;library=library.raw;vertex_function=vertex;fragment_function=fragment;reflection=false;raster_sample_count=1L;color_attachments=[|raw_attachment|];rasterization_enabled=true;primitive_topology=3;support_indirect_commands=false;lookup_archives=[||];vertex_descriptor=None;support_vertex_binary_linking=false;support_fragment_binary_linking=false;vertex_dynamic_linking=None;fragment_dynamic_linking=None;vertex_static_linking=None;fragment_static_linking=None;alpha_to_coverage=false;alpha_to_one=false;max_vertex_amplification_count=1L;color_attachment_mapping=0}in Ok(attachment,descriptor))))))

  let specialize_render_pipeline value ~(source:Render_pipeline.t) ~library ~vertex ?fragment ~color_format ()=
    let operation="Metal.Compiler.specialize_render_pipeline"in on_main operation(fun()->Result.bind(specialization_descriptor operation value~source~library~vertex ?fragment~color_format())(fun(attachment,descriptor)->match Metal_raw.compiler_specialize_render_pipeline value.raw descriptor source.raw with Error m->native_error operation m|Ok(raw,reflected)->Ok(Render_pipeline.make value.device~kind:Render_pipeline.Render~raster_sample_count:1~alpha_to_coverage:false~alpha_to_one:false~max_vertex_amplification_count:1~color_attachment_mapping:Render_pipeline.Identity~color_formats:[color_format]~color_attachments:[attachment]~reflection:false raw reflected)))

  let specialize_render_pipeline_async value ~(source:Render_pipeline.t) ~library ~vertex ?fragment ~color_format ()=
    let operation="Metal.Compiler.specialize_render_pipeline_async"in on_main operation(fun()->Result.bind(specialization_descriptor operation value~source~library~vertex ?fragment~color_format())(fun(attachment,descriptor)->match Metal_raw.compiler_specialize_render_pipeline_async value.raw descriptor source.raw with Error m->native_error operation m|Ok raw->Ok(Compiler_task.make value Metal_raw.compiler_task_take_render_pipeline(fun(raw,reflected)->Render_pipeline.make value.device~kind:Render_pipeline.Render~raster_sample_count:1~alpha_to_coverage:false~alpha_to_one:false~max_vertex_amplification_count:1~color_attachment_mapping:Render_pipeline.Identity~color_formats:[color_format]~color_attachments:[attachment]~reflection:false raw reflected)raw)))

  let create_mesh_pipeline ?label ?object_function ?fragment
      ?(reflection = false) ?max_total_threads_per_object_threadgroup
      ?max_total_threads_per_mesh_threadgroup
      ?required_threads_per_object_threadgroup
      ?required_threads_per_mesh_threadgroup
      ?(object_threadgroup_size_multiple = false)
      ?(mesh_threadgroup_size_multiple = false) ?payload_memory_length
      ?max_total_threadgroups_per_mesh_grid ?(raster_sample_count = 1)
      ?color_formats ?color_attachments
      ?(alpha_to_coverage = false) ?(alpha_to_one = false)
      ?(max_vertex_amplification_count = 1)
      ?(color_attachment_mapping = Render_pipeline.Identity)
      ?(support_object_binary_linking = false)
      ?(support_mesh_binary_linking = false)
      ?(support_fragment_binary_linking = false) ?object_dynamic_linking
      ?mesh_dynamic_linking ?fragment_dynamic_linking ?object_static_linking
      ?mesh_static_linking ?fragment_static_linking
