      (fun reflection color_attachments color_formats descriptor ->
        if
          (Option.is_some descriptor.object_dynamic_linking
          || Option.is_some descriptor.mesh_dynamic_linking
          || Option.is_some descriptor.fragment_dynamic_linking)
          && not
               (Metal_raw.device_supports_family value.device.raw
                  (Device.family_code Device.Apple9))
        then
          error operation Unsupported
            "asynchronous dynamic mesh linking requires an Apple9/M3-or-newer GPU"
        else
          match
            Metal_raw.compiler_create_mesh_pipeline_async value.raw descriptor
          with
          | Error message -> native_error operation message
          | Ok raw ->
              let mesh_constraints =
                mesh_pipeline_constraints ?object_function
                  ?max_total_threads_per_object_threadgroup
                  ?max_total_threads_per_mesh_threadgroup
                  ?required_threads_per_object_threadgroup
                  ?required_threads_per_mesh_threadgroup
                  ~object_threadgroup_size_multiple
                  ~mesh_threadgroup_size_multiple
                  ?max_total_threadgroups_per_mesh_grid ()
              in
              Ok
                (Compiler_task.make value
                   Metal_raw.compiler_task_take_render_pipeline
                   (fun (raw, raw_reflection) ->
                     Render_pipeline.make ~mesh_constraints value.device
                       ~kind:Render_pipeline.Mesh ~raster_sample_count
                       ~alpha_to_coverage ~alpha_to_one
                       ~max_vertex_amplification_count
                       ~color_attachment_mapping
                       ~color_formats ~color_attachments ~reflection raw
                       raw_reflection)
                   raw))
      ?label ?object_function ?fragment ~reflection
      ?max_total_threads_per_object_threadgroup
      ?max_total_threads_per_mesh_threadgroup
      ?required_threads_per_object_threadgroup
      ?required_threads_per_mesh_threadgroup
      ~object_threadgroup_size_multiple ~mesh_threadgroup_size_multiple
      ?payload_memory_length ?max_total_threadgroups_per_mesh_grid
      ~raster_sample_count ?color_formats ?color_attachments
      ~alpha_to_coverage ~alpha_to_one ~max_vertex_amplification_count
      ~color_attachment_mapping
      ~support_object_binary_linking ~support_mesh_binary_linking
      ~support_fragment_binary_linking ?object_dynamic_linking
      ?mesh_dynamic_linking ?fragment_dynamic_linking
      ?object_static_linking ?mesh_static_linking ?fragment_static_linking
      ~rasterization_enabled
      ~support_indirect_command_buffers ~lookup_archives value ~library ~mesh

  let validate_tile_target operation (device : Device.t) ~raster_sample_count
      ~color_formats =
    if List.length color_formats > 8 then
      error operation Invalid_argument
        "tile color attachments must not exceed eight"
    else if raster_sample_count <= 0 then
      error operation Invalid_argument
        "tile raster sample count must be positive"
    else if
      not
        (Metal_raw.device_supports_texture_sample_count device.raw
           raster_sample_count)
    then
      error operation Unsupported
        "the Metal device does not support the tile sample count"
    else
      Ok
        ( Int64.of_int raster_sample_count
        , Array.of_list (List.map Metal_format.code color_formats) )

  let with_tile_descriptor operation callback ?label ?(reflection = false)
      ?(raster_sample_count = 1)
      ?(color_formats = [ Texture.Bgra8_unorm ])
      ?(threadgroup_size_matches_tile_size = false)
      ?max_total_threads_per_threadgroup ?required_threads_per_threadgroup
      ?(support_binary_linking = false) ?static_linking ?dynamic_linking
      ?(lookup_archives = []) (value : t) ~(library : Library.t) ~tile =
    on_main operation (fun () ->
      let ( let* ) result callback = Result.bind result callback in
      let* () = ensure_live operation value.lifetime in
      let* () = ensure_live operation library.lifetime in
      let* () = ensure_same_device operation value.device library.device in
      let* () = validate_pipeline_entry operation library ~stage:"tile" tile in
      let render_function_pointers =
        Metal_raw.device_supports_function_pointers_from_render value.device.raw
      in
      if option_exists contains_nul label then
        error operation Invalid_argument
          "tile-pipeline label contains a NUL byte"
      else if
        not
          (Metal_raw.device_supports_family value.device.raw
             (Device.family_code Device.Apple4))
      then
        error operation Unsupported "tile shaders require an Apple4-or-newer GPU"
      else if
        support_binary_linking
        && not render_function_pointers
      then
        error operation Unsupported
          "tile binary linking requires Metal function-pointer support"
      else
        let* max_total_threads, required_width, required_height, required_depth =
          validate_threadgroup_constraint operation ~stage:"tile"
            ~maximum:max_total_threads_per_threadgroup
            ~required:required_threads_per_threadgroup
        in
        let* raster_sample_count, color_formats =
          validate_tile_target operation value.device ~raster_sample_count
            ~color_formats
        in
        let* static_linking =
          validate_static_linking
            ~supports_public_linking:render_function_pointers operation
            value.device static_linking
        in
        let* dynamic_linking =
          raw_stage_dynamic_linking operation value.device
            ~support_binary_linking ~stage:"tile" dynamic_linking
        in
        let* () =
          validate_pipeline_archives operation value.device lookup_archives
        in
        let descriptor : Metal_raw.metal4_tile_descriptor =
          { label
          ; library = library.raw
          ; tile_function = tile
          ; reflection
          ; raster_sample_count
          ; color_formats
          ; threadgroup_size_matches_tile_size
          ; max_total_threads
          ; required_threads_width = required_width
          ; required_threads_height = required_height
          ; required_threads_depth = required_depth
          ; support_binary_linking
          ; static_linking
          ; lookup_archives =
              Array.of_list
                (List.map
                   (fun (archive : Pipeline_archive.t) -> archive.raw)
                   lookup_archives)
          ; dynamic_linking
          }
        in
        callback reflection descriptor)

  let tile_pipeline_constraints ?max_total_threads_per_threadgroup
      ?required_threads_per_threadgroup ~threadgroup_size_matches_tile_size () =
    { configured_max_tile_threads = max_total_threads_per_threadgroup
    ; required_tile_threads = required_threads_per_threadgroup
    ; threadgroup_size_matches_tile_size
    }

  let create_tile_pipeline ?label ?(reflection = false)
      ?(raster_sample_count = 1)
      ?(color_formats = [ Texture.Bgra8_unorm ])
      ?(threadgroup_size_matches_tile_size = false)
      ?max_total_threads_per_threadgroup ?required_threads_per_threadgroup
      ?(support_binary_linking = false) ?static_linking ?dynamic_linking
      ?(lookup_archives = []) (value : t) ~(library : Library.t) ~tile =
    let operation = "Metal.Compiler.create_tile_pipeline" in
    with_tile_descriptor operation
      (fun reflection descriptor ->
        match Metal_raw.compiler_create_tile_pipeline value.raw descriptor with
        | Error message -> native_error operation message
        | Ok (raw, raw_reflection) ->
            let tile_constraints =
              tile_pipeline_constraints ?max_total_threads_per_threadgroup
                ?required_threads_per_threadgroup
                ~threadgroup_size_matches_tile_size ()
            in
            Ok
              (Render_pipeline.make ~tile_constraints value.device
                 ~kind:Render_pipeline.Tile ~raster_sample_count ~color_formats
                 ~reflection raw raw_reflection))
      ?label ~reflection ~raster_sample_count ~color_formats
      ~threadgroup_size_matches_tile_size
      ?max_total_threads_per_threadgroup ?required_threads_per_threadgroup
      ~support_binary_linking ?static_linking ?dynamic_linking ~lookup_archives
      value ~library ~tile

  let create_tile_pipeline_async ?label ?(reflection = false)
      ?(raster_sample_count = 1)
      ?(color_formats = [ Texture.Bgra8_unorm ])
      ?(threadgroup_size_matches_tile_size = false)
      ?max_total_threads_per_threadgroup ?required_threads_per_threadgroup
      ?(support_binary_linking = false) ?static_linking ?dynamic_linking
      ?(lookup_archives = []) (value : t) ~(library : Library.t) ~tile =
    let operation = "Metal.Compiler.create_tile_pipeline_async" in
    with_tile_descriptor operation
      (fun reflection descriptor ->
        if
          Option.is_some descriptor.dynamic_linking
          && not
               (Metal_raw.device_supports_family value.device.raw
                  (Device.family_code Device.Apple9))
        then
          error operation Unsupported
            "asynchronous dynamic tile linking requires an Apple9/M3-or-newer GPU"
        else
          match
            Metal_raw.compiler_create_tile_pipeline_async value.raw descriptor
          with
          | Error message -> native_error operation message
          | Ok raw ->
              let tile_constraints =
                tile_pipeline_constraints ?max_total_threads_per_threadgroup
                  ?required_threads_per_threadgroup
                  ~threadgroup_size_matches_tile_size ()
              in
              Ok
                (Compiler_task.make value
                   Metal_raw.compiler_task_take_render_pipeline
                   (fun (raw, raw_reflection) ->
                     Render_pipeline.make ~tile_constraints value.device
                       ~kind:Render_pipeline.Tile ~raster_sample_count
                       ~color_formats ~reflection raw raw_reflection)
                   raw))
      ?label ~reflection ~raster_sample_count ~color_formats
      ~threadgroup_size_matches_tile_size
      ?max_total_threads_per_threadgroup ?required_threads_per_threadgroup
      ~support_binary_linking ?static_linking ?dynamic_linking ~lookup_archives
      value ~library ~tile

  let device (value : t) = value.device
  let generation (value : t) = Metal_raw.generation value.raw
  let dataset (value : t) = value.dataset
  let destroyed (value : t) = is_destroyed value.lifetime

  let label (value : t) =
    on_main "Metal.Compiler.label" (fun () ->
      match ensure_live "Metal.Compiler.label" value.lifetime with
      | Error _ as failure -> failure
      | Ok () -> Ok (Metal_raw.compiler_label value.raw))

  let destroy (value : t) =
    destroy_parent "Metal.Compiler.destroy" value.lifetime value.raw (fun () ->
      detach value.device.lifetime;
      Option.iter
        (fun (dataset : pipeline_dataset) -> detach dataset.lifetime)
        value.dataset)
end

let validate_command4_argument_bindings operation
    (table : command4_argument_table) =
  let rec validate_array validate index values =
    if index = Array.length values then Ok ()
    else
      match values.(index) with
      | None -> validate_array validate (index + 1) values
      | Some value ->
          (match validate value with
           | Error _ as failure -> failure
           | Ok () -> validate_array validate (index + 1) values)
  in
  match ensure_live operation table.lifetime with
  | Error _ as failure -> failure
  | Ok () ->
      (match
         validate_array
           (fun (buffer : buffer) ->
             match ensure_buffer_usable operation buffer with
             | Error _ as failure -> failure
             | Ok () -> ensure_same_device operation table.device buffer.device)
           0 table.buffers
       with
       | Error _ as failure -> failure
       | Ok () ->
           (match
              validate_array
                (fun (texture : texture) ->
                  match ensure_texture_usable operation texture with
                  | Error _ as failure -> failure
                  | Ok () ->
                      ensure_same_device operation table.device texture.device)
                0 table.textures
            with
            | Error _ as failure -> failure
            | Ok () ->
                validate_array
                  (fun (sampler : sampler) ->
                    match ensure_live operation sampler.lifetime with
                    | Error _ as failure -> failure
                    | Ok () ->
                        ensure_same_device operation table.device sampler.device)
                  0 table.samplers))

let retain_command4_argument_bindings operation
    (command_buffer : command4_buffer) (table : command4_argument_table) =
  match validate_command4_argument_bindings operation table with
  | Error _ as failure -> failure
  | Ok () ->
      Array.iter
        (Option.iter (retain_command4_buffer command_buffer))
        table.buffers;
      Array.iter
        (Option.iter (retain_command4_texture command_buffer))
        table.textures;
      Array.iter
        (Option.iter (retain_command4_sampler command_buffer))
        table.samplers;
      Ok ()

module Machine_learning = struct
  module Descriptor = struct
    type t=machine_learning_descriptor
    let valid_dimensions dimensions=Array.length dimensions>0&&Array.length dimensions<=8&&Array.for_all(fun x->x>0L)dimensions
    let create ?label ~(library:Library.t) ~function_name ()=
      let operation="Metal.Machine_learning.Descriptor.create"in
      if function_name=""||contains_nul function_name||option_exists contains_nul label then error operation Invalid_argument "ML name or label is invalid"else on_main operation(fun()->Result.bind(ensure_live operation library.lifetime)(fun()->match Metal_raw.metal4_ml_descriptor_create library.raw function_name label with Error m->native_error operation m|Ok raw->let value:t={raw;lifetime=lifetime();library;function_name;ml_label=label;ml_inputs=Hashtbl.create 8}in attach library.lifetime;attach_finalizer value value.lifetime library.lifetime;Ok value))
    let set_label (value:t) label=let operation="Metal.Machine_learning.Descriptor.set_label"in if option_exists contains_nul label then error operation Invalid_argument "ML label contains NUL"else on_main operation(fun()->Result.bind(ensure_live operation value.lifetime)(fun()->match Metal_raw.metal4_ml_descriptor_label value.raw label with Error m->native_error operation m|Ok returned when returned<>label->native_error operation "Metal changed ML label"|Ok _->value.ml_label<-label;Ok()))
    let label (value:t)=value.ml_label
    let function_ (value:t)=let operation="Metal.Machine_learning.Descriptor.function_"in on_main operation(fun()->Result.bind(ensure_live operation value.lifetime)(fun()->match Metal_raw.metal4_ml_descriptor_function value.raw with Error m->native_error operation m|Ok(raw,name)->ignore(Metal_raw.destroy raw);if name<>value.function_name then native_error operation "ML function identity changed"else Ok(value.library,name)))
    let set_input_dimensions (value:t) ~index dimensions=let operation="Metal.Machine_learning.Descriptor.set_input_dimensions"in if index<0L||index>255L||not(valid_dimensions dimensions)then error operation Invalid_argument "ML input dimensions are invalid"else on_main operation(fun()->Result.bind(ensure_live operation value.lifetime)(fun()->match Metal_raw.metal4_ml_descriptor_input value.raw index(Some dimensions)with Error m->native_error operation m|Ok returned when returned<>Some dimensions->native_error operation "Metal changed ML dimensions"|Ok _->Hashtbl.replace value.ml_inputs index(Some(Array.copy dimensions));Ok()))
    let input_dimensions (value:t) ~index=let operation="Metal.Machine_learning.Descriptor.input_dimensions"in if index<0L||index>255L then error operation Invalid_argument "ML input index is invalid"else on_main operation(fun()->Result.bind(ensure_live operation value.lifetime)(fun()->match Metal_raw.metal4_ml_descriptor_input value.raw index None with Error m->native_error operation m|Ok dimensions->Ok(Option.map Array.copy dimensions)))
    let set_input_dimensions_range (value:t) ~start dimensions=
      let operation="Metal.Machine_learning.Descriptor.set_input_dimensions_range"in
      let invalid=Array.exists(function Some x->not(valid_dimensions x)|None->false)dimensions in
      if start<0L||start>255L||Array.length dimensions=0||
         Int64.of_int(Array.length dimensions)>Int64.sub 256L start||invalid
      then error operation Invalid_argument "ML input range is invalid"
      else on_main operation(fun()->Result.bind(ensure_live operation value.lifetime)(fun()->
        match Metal_raw.metal4_ml_descriptor_inputs value.raw start dimensions with
        |Error m->native_error operation m
        |Ok()->Array.iteri(fun i dims->Hashtbl.replace value.ml_inputs
            (Int64.add start(Int64.of_int i))(Option.map Array.copy dims))dimensions;Ok()))
    let reset (value:t)=let operation="Metal.Machine_learning.Descriptor.reset"in on_main operation(fun()->Result.bind(ensure_live operation value.lifetime)(fun()->match Metal_raw.metal4_ml_descriptor_reset value.raw with Error m->native_error operation m|Ok()->Hashtbl.clear value.ml_inputs;value.ml_label<-None;Ok()))
    let destroy (value:t)=destroy_leaf "Metal.Machine_learning.Descriptor.destroy" value.lifetime value.raw(fun()->detach value.library.lifetime)
  end
  module Pipeline = struct
    type t=machine_learning_pipeline
    let compile (compiler:Compiler.t) (descriptor:Descriptor.t)=
      let operation="Metal.Machine_learning.Pipeline.compile"in
      on_main operation(fun()->
        Result.bind(ensure_live operation compiler.lifetime)(fun()->
          Result.bind(ensure_live operation descriptor.lifetime)(fun()->
            Result.bind(ensure_same_device operation compiler.device descriptor.library.device)(fun()->
              match Metal_raw.metal4_ml_compile compiler.raw descriptor.raw with
              |Error m->native_error operation m
              |Ok(raw,(label,registry,heap,bindings))->
                  if registry<>compiler.device.registry_id then begin
                    ignore(Metal_raw.destroy raw);
                    error operation Device_mismatch "ML pipeline returned another device"
                  end else
                    let value:t={raw;lifetime=lifetime();device=compiler.device;
                      ml_pipeline_label=label;intermediates_heap_size=heap;
                      ml_bindings=Array.to_list(Array.map Binding.of_raw bindings)}in
                    attach compiler.device.lifetime;
                    attach_finalizer value value.lifetime compiler.device.lifetime;
                    Ok value))))
    let label(value:t)=value.ml_pipeline_label
    let intermediates_heap_size(value:t)=value.intermediates_heap_size
    let bindings(value:t)=value.ml_bindings
    let device(value:t)=value.device
    let destroyed(value:t)=is_destroyed value.lifetime
    let destroy(value:t)=destroy_leaf "Metal.Machine_learning.Pipeline.destroy" value.lifetime value.raw(fun()->detach value.device.lifetime)
  end
end

module Command4 = struct
  let positive_size (x, y, z) = x > 0 && y > 0 && z > 0

  let product3 x y z =
    if x > max_int / y then None
    else
      let xy = x * y in
      if xy > max_int / z then None else Some (xy * z)

  module Counter_heap = struct
    type t = command4_counter_heap
    type kind = Timestamp
    let kind_code Timestamp = 1
    let kind_of_code = function 1 -> Some Timestamp | _ -> None
    let create ?label (device : Device.t) ~kind ~count =
      let operation = "Metal.Command4.Counter_heap.create" in
      on_main operation (fun () ->
        match ensure_metal4 operation device with
        | Error _ as failure -> failure
        | Ok () when count <= 0L ->
            error operation Invalid_argument "counter count must be positive"
        | Ok () when option_exists contains_nul label ->
            error operation Invalid_argument "counter label contains a NUL byte"
        | Ok () ->
            let code = kind_code kind in
            match Metal_raw.metal4_counter_descriptor_roundtrip code count with
            | Error message -> native_error operation message
            | Ok (roundtrip_kind, roundtrip_count)
              when roundtrip_kind <> code || roundtrip_count <> count ->
                native_error operation "Metal changed the counter descriptor"
            | Ok _ ->
                match Metal_raw.metal4_counter_create device.raw code count label with
                | Error message -> native_error operation message
                | Ok raw ->
                    let value : t =
                      { raw; lifetime = lifetime (); device; count
                      ; counter_type = code; counter_label = label }
                    in
                    attach device.lifetime;
                    attach_finalizer value value.lifetime device.lifetime;
                    Ok value)
    let info (value : t) =
      let operation = "Metal.Command4.Counter_heap.info" in
      on_main operation (fun () -> match ensure_live operation value.lifetime with
        | Error _ as failure -> failure
        | Ok () -> match Metal_raw.metal4_counter_info value.raw with
          | Error message -> native_error operation message
          | Ok (count, kind, _label)
            when count <> value.count || kind <> value.counter_type ->
              native_error operation "counter metadata changed"
          | Ok (_, kind, label) -> match kind_of_code kind with
            | None -> error operation Unsupported "unknown counter kind"
            | Some kind ->
                value.counter_label <- label;
                Ok (kind, value.count, value.counter_label))
    let set_label (value : t) label =
      let operation = "Metal.Command4.Counter_heap.set_label" in
      if option_exists contains_nul label then
        error operation Invalid_argument "counter label contains a NUL byte"
      else on_main operation (fun () -> match ensure_live operation value.lifetime with
        | Error _ as failure -> failure
        | Ok () -> match Metal_raw.metal4_counter_set_label value.raw label with
          | Error message -> native_error operation message
          | Ok () -> value.counter_label <- label; Ok ())
    let validate_range operation value ~location ~length =
      if location < 0L || length < 0L || location > value.count
         || length > Int64.sub value.count location then
        error operation Invalid_argument "counter range is out of bounds"
      else Ok ()
    let invalidate (value : t) ~location ~length =
      let operation = "Metal.Command4.Counter_heap.invalidate" in
      on_main operation (fun () -> match ensure_live operation value.lifetime with
        | Error _ as failure -> failure
        | Ok () -> Result.bind (validate_range operation value ~location ~length)
          (fun () -> match Metal_raw.metal4_counter_invalidate value.raw (location,length) with
           | Error message -> native_error operation message | Ok () -> Ok ()))
    let resolve (value : t) ~location ~length =
      let operation = "Metal.Command4.Counter_heap.resolve" in
      on_main operation (fun () -> match ensure_live operation value.lifetime with
        | Error _ as failure -> failure
        | Ok () -> Result.bind (validate_range operation value ~location ~length)
          (fun () -> match Metal_raw.metal4_counter_resolve value.raw (location,length) with
           | Error message -> native_error operation message | Ok bytes -> Ok bytes))
    let device (value : t) = value.device
    let destroyed (value : t) = is_destroyed value.lifetime
    let destroy (value : t) = destroy_parent "Metal.Command4.Counter_heap.destroy"
      value.lifetime value.raw (fun () -> detach value.device.lifetime)
  end

  module Argument_table = struct
    type t = command4_argument_table

    let validate_counts operation ~max_buffers ~max_textures ~max_samplers =
      if max_buffers < 0 || max_buffers > 31 then
        error operation Invalid_argument
          "max_buffers must be between zero and 31"
      else if max_textures < 0 || max_textures > 128 then
        error operation Invalid_argument
          "max_textures must be between zero and 128"
      else if max_samplers < 0 || max_samplers > 16 then
        error operation Invalid_argument
          "max_samplers must be between zero and 16"
      else if max_buffers = 0 && max_textures = 0 && max_samplers = 0 then
        error operation Invalid_argument
          "an argument table requires at least one binding slot"
      else Ok ()

    let create ?label ?(initialize_bindings = true)
        ?(support_attribute_strides = false) ?(max_buffers = 0)
        ?(max_textures = 0) ?(max_samplers = 0) (device : Device.t) () =
      let operation = "Metal.Command4.Argument_table.create" in
      on_main operation (fun () ->
        match ensure_metal4 operation device with
        | Error _ as failure -> failure
        | Ok () ->
            (match
               validate_counts operation ~max_buffers ~max_textures
                 ~max_samplers
             with
             | Error _ as failure -> failure
             | Ok () when option_exists contains_nul label ->
                 error operation Invalid_argument "label contains a NUL byte"
             | Ok () ->
                 let descriptor : Metal_raw.metal4_argument_table_descriptor =
                   { max_buffers
                   ; max_textures
                   ; max_samplers
                   ; initialize_bindings
                   ; support_attribute_strides
                   ; label
                   }
                 in
                 match
                   Metal_raw.command4_argument_table_create device.raw descriptor
                 with
                 | Error message -> native_error operation message
                 | Ok raw ->
                     let buffers = Array.make max_buffers None
                     and buffer_strides = Array.make max_buffers None
                     and textures = Array.make max_textures None
                     and samplers = Array.make max_samplers None in
                     let value : t =
                       { raw
                       ; lifetime = lifetime ()
                       ; device
                       ; max_buffers
                       ; max_textures
                       ; max_samplers
                       ; initialize_bindings
                       ; support_attribute_strides
                       ; buffers
                       ; buffer_strides
                       ; textures
                       ; samplers
                       }
                     in
                     attach device.lifetime;
                     attach_finalizer
                       ~on_finalize:(fun () ->
                         release_command4_argument_bindings buffers textures
                           samplers)
                       value value.lifetime device.lifetime;
                     Ok value))

    let device (value : t) = value.device
    let generation (value : t) = Metal_raw.generation value.raw
    let destroyed (value : t) = is_destroyed value.lifetime
    let max_buffers (value : t) = value.max_buffers
    let max_textures (value : t) = value.max_textures
    let max_samplers (value : t) = value.max_samplers
    let initializes_bindings (value : t) = value.initialize_bindings
    let supports_attribute_strides (value : t) = value.support_attribute_strides

    let label (value : t) =
      let operation = "Metal.Command4.Argument_table.label" in
      on_main operation (fun () ->
        match ensure_live operation value.lifetime with
        | Error _ as failure -> failure
        | Ok () -> Ok (Metal_raw.command4_argument_table_label value.raw))

    let validate_index operation capacity index kind =
      if index < 0 || index >= capacity then
        error operation Invalid_argument
          (Printf.sprintf "%s binding index %d is outside [0, %d)" kind index
             capacity)
      else Ok ()

    let set_buffer (value : t) ~index ?(offset = 0L) ?attribute_stride
        (buffer : Buffer.t) =
      let operation = "Metal.Command4.Argument_table.set_buffer" in
      on_main operation (fun () ->
        match ensure_live operation value.lifetime with
        | Error _ as failure -> failure
        | Ok () ->
            (match validate_index operation value.max_buffers index "buffer" with
             | Error _ as failure -> failure
             | Ok () when offset < 0L || offset >= buffer.length ->
                 error operation Invalid_argument
                   "buffer offset is outside the buffer"
             | Ok ()
               when option_exists (fun stride -> stride <= 0) attribute_stride ->
                 error operation Invalid_argument
                   "attribute stride must be positive"
             | Ok ()
               when Option.is_some attribute_stride
                    && not value.support_attribute_strides ->
                 error operation Invalid_argument
                   "the argument table does not support attribute strides"
             | Ok () ->
