  end
  module Command_buffer = struct
    type t = command4_buffer

    type state =
      | Recording
      | Ended
      | Submitted
      | Completed
      | Failed of string

    let public_state = function
      | Command4_recording -> Recording
      | Command4_ended -> Ended
      | Command4_submitted -> Submitted
      | Command4_completed -> Completed
      | Command4_failed message -> Failed message

    let create (allocator : Allocator.t) ?label ?options () =
      let operation = "Metal.Command4.Command_buffer.create" in
      on_main operation (fun () ->
        match ensure_live operation allocator.lifetime with
        | Error _ as failure -> failure
        | Ok () when allocator.recording ->
            error operation Invalid_state
              "the allocator already services a recording command buffer"
        | Ok () when option_exists contains_nul label ->
            error operation Invalid_argument "label contains a NUL byte"
        | Ok () when option_exists (fun(options:command4_buffer_options)->is_destroyed options.lifetime) options -> error operation Destroyed "command-buffer options are destroyed"
        | Ok () when option_exists (fun(options:command4_buffer_options)->not(same_device allocator.device options.device)) options -> error operation Device_mismatch "command-buffer options belong to another device"
        | Ok () ->
            (match (match options with None->Metal_raw.command4_buffer_create allocator.raw label|Some options->Metal_raw.metal4_command_buffer_create_options allocator.raw label options.raw) with
             | Error message -> native_error operation message
             | Ok raw ->
                 let owns_recording = ref true in
                 let resources = ref [] in
                 let value : t =
                   { raw
                   ; lifetime = lifetime ()
                   ; allocator
                   ; phase = Command4_recording
                   ; owns_recording
                   ; resources
                   ; options
                   ; debug_group_depth = 0
                   }
                 in
                 allocator.recording <- true;
                 attach allocator.lifetime;
                 Option.iter(fun(options:command4_buffer_options)->attach options.lifetime)options;
                 attach_finalizer
                   ~on_finalize:(fun () ->
                     if !owns_recording then allocator.recording <- false;
                     release_command4_resources resources;Option.iter(fun(options:command4_buffer_options)->detach options.lifetime)options)
                   value value.lifetime allocator.lifetime;
                 Ok value))

    let device (value : t) = value.allocator.device
    let generation (value : t) = Metal_raw.generation value.raw
    let destroyed (value : t) = is_destroyed value.lifetime
    let state (value : t) = public_state value.phase

    let label (value : t) =
      let operation = "Metal.Command4.Command_buffer.label" in
      on_main operation (fun () ->
        match ensure_live operation value.lifetime with
        | Error _ as failure -> failure
        | Ok () -> Ok (Metal_raw.command4_buffer_label value.raw))

    let callable operation (value : t) callback =
      on_main operation (fun () ->
        match ensure_live operation value.lifetime with
        | Error _ as failure -> failure
        | Ok () when value.phase <> Command4_recording ->
            error operation Invalid_state "command buffer is not recording"
        | Ok () when dependent_count value.lifetime <> 0 ->
            error operation Invalid_state "a command encoder is active"
        | Ok () -> callback ())

    let push_debug_group (value : t) label =
      let operation = "Metal.Command4.Command_buffer.push_debug_group" in
      if label = "" || contains_nul label then
        error operation Invalid_argument "debug label is empty or contains NUL"
      else callable operation value (fun () ->
        match Metal_raw.metal4_buffer_debug value.raw label false with
        | Error message -> native_error operation message
        | Ok () -> value.debug_group_depth <- value.debug_group_depth + 1; Ok ())

    let pop_debug_group (value : t) =
      let operation = "Metal.Command4.Command_buffer.pop_debug_group" in
      callable operation value (fun () ->
        if value.debug_group_depth = 0 then
          error operation Invalid_state "debug-group stack is empty"
        else match Metal_raw.metal4_buffer_debug value.raw "" true with
          | Error message -> native_error operation message
          | Ok () -> value.debug_group_depth <- value.debug_group_depth - 1; Ok ())

    let use_residency_sets (value : t) (sets : Residency_set.t list) =
      let operation = "Metal.Command4.Command_buffer.use_residency_sets" in
      if sets = [] then error operation Invalid_argument "residency-set list is empty"
      else callable operation value (fun () ->
        let rec validate = function
          | [] -> Ok ()
          | (set : residency_set) :: rest ->
              Result.bind (ensure_live operation set.lifetime) (fun () ->
                Result.bind (ensure_same_device operation value.allocator.device set.device)
                  (fun () -> validate rest))
        in
        Result.bind (validate sets) (fun () ->
          match Metal_raw.metal4_buffer_use_residencies value.raw
            (Array.of_list (List.map (fun (set : residency_set) -> set.raw) sets)) with
          | Error message -> native_error operation message
          | Ok () -> List.iter (fun (set : residency_set) ->
              retain_command4_other value set.lifetime) sets; Ok ()))

    let write_timestamp (value : t) (heap : Counter_heap.t) ~index =
      let operation = "Metal.Command4.Command_buffer.write_timestamp" in
      callable operation value (fun () ->
        Result.bind (ensure_live operation heap.lifetime) (fun () ->
          Result.bind (ensure_same_device operation value.allocator.device heap.device)
            (fun () -> if index < 0L || index >= heap.count then
              error operation Invalid_argument "counter index is out of range"
            else match Metal_raw.metal4_buffer_timestamp value.raw heap.raw index with
              | Error message -> native_error operation message
              | Ok () -> retain_command4_other value heap.lifetime; Ok ())))

    let resolve_counter (value : t) (heap : Counter_heap.t) ~location ~length
        ~(destination : Buffer.t) ~destination_offset ?wait_fence ?update_fence () =
      let operation = "Metal.Command4.Command_buffer.resolve_counter" in
      callable operation value (fun () ->
        let range_ok total offset span = offset >= 0L && span >= 0L
          && offset <= total && span <= Int64.sub total offset in
        let output_length = Int64.mul length 8L in
        Result.bind (ensure_live operation heap.lifetime) (fun () ->
          Result.bind (ensure_same_device operation value.allocator.device heap.device) (fun () ->
            Result.bind (ensure_buffer_usable operation destination) (fun () ->
              Result.bind (ensure_same_device operation value.allocator.device destination.device) (fun () ->
                if location < 0L || length <= 0L || location > heap.count
                   || length > Int64.sub heap.count location
                   || length > Int64.div Int64.max_int 8L
                   || Int64.rem destination_offset 8L <> 0L
                   || not (range_ok destination.length destination_offset output_length)
                then error operation Invalid_argument "counter resolve range is invalid"
                else
                  let validate_fence = function None -> Ok () | Some (fence : Fence.t) ->
                    Result.bind (ensure_live operation fence.lifetime) (fun () ->
                      ensure_same_device operation value.allocator.device fence.device) in
                  Result.bind (validate_fence wait_fence) (fun () ->
                    Result.bind (validate_fence update_fence) (fun () ->
                      match Metal_raw.metal4_buffer_resolve_counter value.raw
                        (heap.raw,(location,length),(destination.raw,destination_offset,output_length),
                         Option.map (fun (f : Fence.t) -> f.raw) wait_fence,
                         Option.map (fun (f : Fence.t) -> f.raw) update_fence) with
                      | Error message -> native_error operation message
                      | Ok () ->
                          retain_command4_other value heap.lifetime;
                          retain_command4_buffer value destination;
                          Option.iter (fun (f : Fence.t) -> retain_command4_other value f.lifetime) wait_fence;
                          Option.iter (fun (f : Fence.t) -> retain_command4_other value f.lifetime) update_fence;
                          Ok ())))))))

    let end_recording (value : t) =
      let operation = "Metal.Command4.Command_buffer.end_recording" in
      on_main operation (fun () ->
        match ensure_live operation value.lifetime with
        | Error _ as failure -> failure
        | Ok () when value.phase <> Command4_recording ->
            error operation Invalid_state "command buffer is not recording"
        | Ok () when dependent_count value.lifetime <> 0 ->
            error operation Invalid_state "a command encoder is still open"
        | Ok () when value.debug_group_depth <> 0 ->
            error operation Invalid_state "a command-buffer debug group is still open"
        | Ok () ->
            (match Metal_raw.command4_buffer_end value.raw with
             | Error message -> native_error operation message
             | Ok () ->
                 value.phase <- Command4_ended;
                 value.owns_recording := false;
                 value.allocator.recording <- false;
                 Ok ()))

    let destroy (value : t) =
      let operation = "Metal.Command4.Command_buffer.destroy" in
      on_main operation (fun () ->
        if is_destroyed value.lifetime then Ok ()
        else if value.phase = Command4_submitted then
            error operation Invalid_state
              "wait for the command submission before destroying its buffer"
        else if dependent_count value.lifetime <> 0 then
            error operation Parent_has_dependents
              "command buffer has a live encoder or submission"
        else begin
            if Atomic.compare_and_set value.lifetime.destroyed false true then begin
              ignore (Metal_raw.destroy value.raw);
              if !(value.owns_recording) then begin
                value.owns_recording := false;
                value.allocator.recording <- false
              end;
              release_command4_resources value.resources;
              Option.iter(fun(options:command4_buffer_options)->detach options.lifetime)value.options;
              detach value.allocator.lifetime
            end;
            Ok ()
        end)
  end

  module Submission = struct
    type t = command4_submission
    type feedback={gpu_start_time:float;gpu_end_time:float;gpu_duration:float}

    let release_buffers buffers phase =
      let retained = !buffers in
      buffers := [];
      List.iter
        (fun (buffer : command4_buffer) ->
          buffer.phase <- phase;
          release_command4_resources buffer.resources;
          detach buffer.lifetime)
        retained

    let make (queue : command4_queue) buffers raw =
      let retained = ref buffers in
      let value : t =
        { raw
        ; lifetime = lifetime ()
        ; queue
        ; buffers = retained
        ; outcome = None
        }
      in
      attach queue.lifetime;
      List.iter (fun (buffer : command4_buffer) -> attach buffer.lifetime) buffers;
      attach_finalizer
        ~on_finalize:(fun () ->
          release_buffers retained
            (Command4_failed "command submission was abandoned before wait"))
        value value.lifetime queue.lifetime;
      value

    let device (value : t) = value.queue.device
    let generation (value : t) = Metal_raw.generation value.raw
    let destroyed (value : t) = is_destroyed value.lifetime
    let completed (value : t) = Option.is_some value.outcome

    let feedback (value:t)=
      let operation="Metal.Command4.Submission.feedback"in
      on_main operation(fun()->Result.bind(ensure_live operation value.lifetime)(fun()->
        match value.outcome with
        |None->error operation Invalid_state "submission has not completed"
        |Some(Error _ as failure)->failure
        |Some(Ok())->match Metal_raw.command4_submission_times value.raw with
          |Error message->native_error operation message
          |Ok(start_time,end_time) when not(Float.is_finite start_time&&Float.is_finite end_time)||end_time<start_time->native_error operation "Metal returned invalid GPU timing feedback"
          |Ok(start_time,end_time)->Ok{gpu_start_time=start_time;gpu_end_time=end_time;gpu_duration=end_time-.start_time}))

    let wait (value : t) =
      let operation = "Metal.Command4.Submission.wait" in
      on_main operation (fun () ->
        match ensure_live operation value.lifetime with
        | Error _ as failure -> failure
        | Ok () ->
            (match value.outcome with
             | Some outcome -> outcome
             | None ->
                 let outcome =
                   match Metal_raw.command4_submission_wait value.raw with
                   | Ok () -> Ok ()
                   | Error message -> native_error operation message
                 in
                 let phase =
                   match outcome with
                   | Ok () -> Command4_completed
                   | Error error -> Command4_failed error.message
                 in
                 release_buffers value.buffers phase;
                 value.outcome <- Some outcome;
                 outcome))

    let destroy (value : t) =
      let operation = "Metal.Command4.Submission.destroy" in
      on_main operation (fun () ->
        if is_destroyed value.lifetime then Ok ()
        else if Option.is_none value.outcome then
            error operation Invalid_state
              "wait for the submission before destroying it"
        else begin
            if Atomic.compare_and_set value.lifetime.destroyed false true then begin
              ignore (Metal_raw.destroy value.raw);
              release_buffers value.buffers
                (Command4_failed "command submission was destroyed");
              detach value.queue.lifetime
            end;
            Ok ()
        end)
  end

  module Queue = struct
    type t = command4_queue

    let create ?label (device : Device.t) =
      let operation = "Metal.Command4.Queue.create" in
      on_main operation (fun () ->
        match ensure_metal4 operation device with
        | Error _ as failure -> failure
        | Ok () when option_exists contains_nul label ->
            error operation Invalid_argument "label contains a NUL byte"
        | Ok () ->
            (match Metal_raw.command4_queue_create device.raw label with
             | Error message -> native_error operation message
             | Ok raw ->
                 let value : t =
                   { raw; lifetime = lifetime (); device
                   ; residency_lifetimes = ref []
                   ; synchronization_lifetimes = ref [] }
                 in
                 attach device.lifetime;
                 attach_finalizer value value.lifetime device.lifetime;
                 Ok value))

    let device (value : t) = value.device
    let generation (value : t) = Metal_raw.generation value.raw
    let destroyed (value : t) = is_destroyed value.lifetime
    let label (value : t) =
      let operation = "Metal.Command4.Queue.label" in
      on_main operation (fun () ->
        match ensure_live operation value.lifetime with
        | Error _ as failure -> failure
        | Ok () -> Ok (Metal_raw.command4_queue_label value.raw))

    type buffer_mapping_copy =
      { source_offset : int64
      ; length : int64
      ; destination_offset : int64
      }

    type texture_mapping_copy =
      { source_origin : int64 * int64 * int64
      ; size : int64 * int64 * int64
      ; source_level : int64
      ; source_slice : int64
      ; destination_origin : int64 * int64 * int64
      ; destination_level : int64
      ; destination_slice : int64
      }

    type event = Event of Event.t | Shared_event of Shared_event.t

    let retain_synchronization (value : t) lifetime =
      if not (List.exists ((==) lifetime) !(value.synchronization_lifetimes)) then begin
        attach lifetime;
        value.synchronization_lifetimes := lifetime :: !(value.synchronization_lifetimes)
      end

    let copy_buffer_mappings (value : t) ~(source : Buffer.t)
        ~(destination : Buffer.t) operations =
      let operation = "Metal.Command4.Queue.copy_buffer_mappings" in
      on_main operation (fun () ->
        Result.bind (ensure_live operation value.lifetime) (fun () ->
        Result.bind (ensure_buffer_usable operation source) (fun () ->
        Result.bind (ensure_buffer_usable operation destination) (fun () ->
        Result.bind (ensure_same_device operation value.device source.device) (fun () ->
        Result.bind (ensure_same_device operation value.device destination.device) (fun () ->
          if operations = [] then
            error operation Invalid_argument "sparse buffer mapping copy requires operations"
          else
            let native = Array.of_list (List.map (fun item ->
              item.source_offset, item.length, item.destination_offset) operations) in
            match Metal_raw.metal4_queue_copy_buffer_mappings value.raw source.raw
                    destination.raw native true with
            | Error message -> native_error operation message
            | Ok () ->
                retain_synchronization value source.lifetime;
                retain_synchronization value destination.lifetime;
                Ok ()))))))

    let copy_texture_mappings (value : t) ~(source : Texture.t)
        ~(destination : Texture.t) operations =
      let operation = "Metal.Command4.Queue.copy_texture_mappings" in
      on_main operation (fun () ->
        Result.bind (ensure_live operation value.lifetime) (fun () ->
        Result.bind (ensure_texture_usable operation source) (fun () ->
        Result.bind (ensure_texture_usable operation destination) (fun () ->
        Result.bind (ensure_same_device operation value.device source.device) (fun () ->
        Result.bind (ensure_same_device operation value.device destination.device) (fun () ->
          if operations = [] then
            error operation Invalid_argument "sparse texture mapping copy requires operations"
          else
            let native = Array.of_list (List.map (fun item ->
              let sx,sy,sz = item.source_origin and w,h,d = item.size
              and dx,dy,dz = item.destination_origin in
              sx,sy,sz,w,h,d,item.source_level,item.source_slice,
              dx,dy,dz,item.destination_level,item.destination_slice) operations) in
            match Metal_raw.metal4_queue_copy_texture_mappings value.raw source.raw
                    destination.raw native true with
            | Error message -> native_error operation message
            | Ok () ->
                retain_synchronization value source.lifetime;
                retain_synchronization value destination.lifetime;
                Ok ()))))))

    let add_residency_set (value : t) (set : Residency_set.t) =
      let operation = "Metal.Command4.Queue.add_residency_set" in
      on_main operation (fun () ->
        Result.bind (ensure_live operation value.lifetime) (fun () ->
        Result.bind (ensure_live operation set.lifetime) (fun () ->
        Result.bind (ensure_same_device operation value.device set.device) (fun () ->
          match Metal_raw.metal4_queue_synchronize value.raw 0 set.raw 0L false true with
          | Error message -> native_error operation message
          | Ok () ->
              if not (List.exists ((==) set.lifetime) !(value.residency_lifetimes)) then begin
                attach set.lifetime;
                value.residency_lifetimes := set.lifetime :: !(value.residency_lifetimes)
              end;
              Ok ()))))

    let synchronize_drawable operation code (value : t) (drawable : Drawable.t) =
      on_main operation (fun () ->
        Result.bind (ensure_live operation value.lifetime) (fun () ->
        Result.bind (ensure_live operation drawable.lifetime) (fun () ->
        Result.bind (ensure_same_device operation value.device drawable.layer.device) (fun () ->
          match Metal_raw.metal4_queue_synchronize value.raw code drawable.raw 0L false true with
          | Error message -> native_error operation message
          | Ok () -> retain_synchronization value drawable.lifetime; Ok ()))))

    let signal_drawable value drawable =
      synchronize_drawable "Metal.Command4.Queue.signal_drawable" 1 value drawable

    let wait_for_drawable value drawable =
      synchronize_drawable "Metal.Command4.Queue.wait_for_drawable" 2 value drawable

    let wait_for_event (value : t) event ~value:event_value =
      let operation = "Metal.Command4.Queue.wait_for_event" in
      on_main operation (fun () ->
        let raw, lifetime, device, shared = match event with
          | Event item -> item.raw, item.lifetime, item.device, false
          | Shared_event item -> item.raw, item.lifetime, item.device, true in
        Result.bind (ensure_live operation value.lifetime) (fun () ->
        Result.bind (ensure_live operation lifetime) (fun () ->
        Result.bind (ensure_same_device operation value.device device) (fun () ->
          if event_value < 0L then
            error operation Invalid_argument "Metal 4 event value must be nonnegative"
          else match Metal_raw.metal4_queue_synchronize value.raw 3 raw event_value shared true with
            | Error message -> native_error operation message
            | Ok () -> retain_synchronization value lifetime; Ok ()))))

    let same_buffer (left : command4_buffer) (right : command4_buffer) =
      left.lifetime == right.lifetime

    let rec validate_buffers operation (queue : command4_queue) seen = function
      | [] -> Ok ()
      | (buffer : command4_buffer) :: rest ->
          if List.exists (same_buffer buffer) seen then
            error operation Invalid_argument
              "command-buffer list contains a duplicate handle"
          else
            (match ensure_live operation buffer.lifetime with
             | Error _ as failure -> failure
             | Ok () when buffer.phase <> Command4_ended ->
                 error operation Invalid_state
                   "every Metal 4 command buffer must be ended before commit"
             | Ok () when dependent_count buffer.lifetime <> 0 ->
                 error operation Invalid_state
                   "a Metal 4 command buffer still owns an open encoder"
             | Ok () ->
                 (match
                    ensure_same_device operation queue.device
                      buffer.allocator.device
                  with
                  | Error _ as failure -> failure
                  | Ok () -> validate_buffers operation queue (buffer :: seen) rest))

    let commit (value : t) buffers =
      let operation = "Metal.Command4.Queue.commit" in
      on_main operation (fun () ->
        match ensure_live operation value.lifetime with
        | Error _ as failure -> failure
        | Ok () when buffers = [] ->
            error operation Invalid_argument
              "at least one command buffer is required"
        | Ok () when List.length buffers > 64 ->
            error operation Invalid_argument
              "a submission may contain at most 64 command buffers"
        | Ok () ->
            (match validate_buffers operation value [] buffers with
             | Error _ as failure -> failure
             | Ok () ->
                 let raw_buffers =
                   Array.of_list
                     (List.map
                        (fun (buffer : command4_buffer) -> buffer.raw)
                        buffers)
                 in
                 match Metal_raw.command4_queue_commit value.raw raw_buffers with
                 | Error message -> native_error operation message
                 | Ok raw ->
                     List.iter
                       (fun (buffer : command4_buffer) ->
                         buffer.phase <- Command4_submitted)
                       buffers;
                     Ok (Submission.make value buffers raw)))

    let validate_residencies operation (value : t) sets =
      let rec loop seen = function
        | [] -> Ok ()
        | (set : Residency_set.t) :: rest ->
            if List.exists (fun (item : residency_set) ->
                 item.lifetime == set.lifetime) seen then
              error operation Invalid_argument "duplicate residency set"
            else Result.bind (ensure_live operation set.lifetime) (fun () ->
              Result.bind (ensure_same_device operation value.device set.device)
                (fun () -> loop (set :: seen) rest))
      in loop [] sets

    let add_residency_sets (value : t) sets =
      let operation = "Metal.Command4.Queue.add_residency_sets" in
      on_main operation (fun () -> match ensure_live operation value.lifetime with
        | Error _ as failure -> failure
        | Ok () when sets = [] ->
            error operation Invalid_argument "residency-set list is empty"
        | Ok () -> Result.bind (validate_residencies operation value sets) (fun () ->
            let fresh = List.filter (fun (set : residency_set) ->
              not (List.exists ((==) set.lifetime) !(value.residency_lifetimes))) sets in
            if fresh = [] then Ok () else
            match Metal_raw.metal4_queue_add_residencies value.raw
                    (Array.of_list (List.map (fun (set : residency_set) -> set.raw) fresh)) with
            | Error message -> native_error operation message
            | Ok () -> List.iter (fun (set : residency_set) ->
                attach set.lifetime;
                value.residency_lifetimes := set.lifetime :: !(value.residency_lifetimes)) fresh;
                Ok ()))

    let remove_residency_set (value : t) (set : Residency_set.t) =
      let operation = "Metal.Command4.Queue.remove_residency_set" in
      on_main operation (fun () -> match ensure_live operation value.lifetime with
        | Error _ as failure -> failure
        | Ok () -> Result.bind (validate_residencies operation value [set]) (fun () ->
            if not (List.exists ((==) set.lifetime) !(value.residency_lifetimes)) then
              error operation Invalid_state "residency set is not on this queue"
            else match Metal_raw.metal4_queue_remove_residency value.raw set.raw with
              | Error message -> native_error operation message
              | Ok () ->
                  value.residency_lifetimes := List.filter
                    (fun lifetime -> lifetime != set.lifetime) !(value.residency_lifetimes);
                  detach set.lifetime; Ok ()))

    let remove_residency_sets (value : t) sets =
      let operation = "Metal.Command4.Queue.remove_residency_sets" in
      on_main operation (fun () -> match ensure_live operation value.lifetime with
        | Error _ as failure -> failure
        | Ok () when sets = [] ->
            error operation Invalid_argument "residency-set list is empty"
        | Ok () -> Result.bind (validate_residencies operation value sets) (fun () ->
            if List.exists (fun (set : residency_set) ->
                 not (List.exists ((==) set.lifetime) !(value.residency_lifetimes))) sets then
              error operation Invalid_state "a residency set is not on this queue"
            else match Metal_raw.metal4_queue_remove_residencies value.raw
                    (Array.of_list (List.map (fun (set : residency_set) -> set.raw) sets)) with
              | Error message -> native_error operation message
              | Ok () -> List.iter (fun (set : residency_set) ->
                    value.residency_lifetimes := List.filter
                      (fun lifetime -> lifetime != set.lifetime) !(value.residency_lifetimes);
                    detach set.lifetime) sets; Ok ()))

    let destroy (value : t) =
      destroy_parent "Metal.Command4.Queue.destroy" value.lifetime value.raw
        (fun () -> List.iter detach !(value.residency_lifetimes);
          List.iter detach !(value.synchronization_lifetimes);
          value.residency_lifetimes := [];
          value.synchronization_lifetimes := [];
          detach value.device.lifetime)
  end

  module Render_encoder = struct
    type t = command4_render_encoder

    type vertex_amplification_view_mapping =
      { viewport_array_index_offset : int
      ; render_target_array_index_offset : int
      }

    type color =
      { red : float
      ; green : float
      ; blue : float
      ; alpha : float
      }

    type load_action =
      | Load_dont_care
      | Load
      | Clear of color

    type store_action = render_store_action =
      | Store_dont_care
      | Store
      | Store_deferred

    type visibility_result_mode =
      | Visibility_disabled
      | Visibility_boolean
      | Visibility_counting

    type visibility_result_type =
      | Visibility_reset
      | Visibility_accumulate

    type depth_load_action =
      | Depth_load_dont_care
      | Depth_load
      | Depth_clear

    type stencil_load_action =
      | Stencil_load_dont_care
      | Stencil_load
      | Stencil_clear

    type color_attachment =
      { texture : Texture.t
      ; load_action : load_action
      ; store_action : store_action
      }

    type depth_attachment =
      { texture : Texture.t
      ; load_action : depth_load_action
      ; store_action : store_action
      ; clear_depth : float
      }

    type stencil_attachment =
      { texture : Texture.t
      ; load_action : stencil_load_action
      ; store_action : store_action
      ; clear_stencil : int32
      }

    type viewport =
      { x : float
      ; y : float
      ; width : float
      ; height : float
      ; z_near : float
      ; z_far : float
      }

    type scissor_rect =
      { x : int
      ; y : int
      ; width : int
      ; height : int
      }

    type winding =
      | Clockwise
      | Counter_clockwise

    type cull_mode =
      | Cull_none
      | Cull_front
      | Cull_back

    type depth_clip_mode =
      | Depth_clip
      | Depth_clamp

    type triangle_fill_mode =
      | Triangle_fill
      | Triangle_lines

    type primitive =
      | Point
      | Line
      | Line_strip
      | Triangle
      | Triangle_strip

    type index_type =
      | Uint16
      | Uint32

    type timestamp_granularity = Relaxed | Precise
    let timestamp_granularity_code=function Relaxed->0|Precise->1

    type stage =
      | Vertex
      | Fragment
      | Tile
      | Object
      | Mesh

    let color ~red ~green ~blue ~alpha = { red; green; blue; alpha }
    let transparent_black = color ~red:0. ~green:0. ~blue:0. ~alpha:0.

    let color_attachment ?(load_action = Clear transparent_black)
        ?(store_action = Store) texture =
      { texture; load_action; store_action }

    let depth_attachment ?(load_action = Depth_clear)
        ?(store_action = Store) ?(clear_depth = 1.) texture =
      { texture; load_action; store_action; clear_depth }

    let stencil_attachment ?(load_action = Stencil_clear)
        ?(store_action = Store) ?(clear_stencil = Int32.zero) texture =
      { texture; load_action; store_action; clear_stencil }

    let vertex_amplification_view_mapping
        ?(viewport_array_index_offset = 0)
        ?(render_target_array_index_offset = 0) () =
      { viewport_array_index_offset; render_target_array_index_offset }

    let finite_color color =
      Float.is_finite color.red && Float.is_finite color.green
      && Float.is_finite color.blue && Float.is_finite color.alpha

    let finite_float32 value =
      Float.is_finite value && Float.abs value <= 0x1.fffffep+127

    let load_code = function
      | Load_dont_care -> 0
      | Load -> 1
      | Clear _ -> 2

    let store_code = function
      | Store_dont_care -> 0
      | Store -> 1
      | Store_deferred -> 4

    let visibility_result_type_code = function
      | Visibility_reset -> 0
      | Visibility_accumulate -> 1

    let depth_load_code = function
      | Depth_load_dont_care -> 0
      | Depth_load -> 1
      | Depth_clear -> 2

    let stencil_load_code = function
      | Stencil_load_dont_care -> 0
      | Stencil_load -> 1
      | Stencil_clear -> 2

    let clear_color = function
      | Clear color -> color
      | Load_dont_care | Load -> transparent_black

    let same_attachment (left : color_attachment) (right : color_attachment) =
      left.texture.lifetime == right.texture.lifetime

    let validate_attachments operation device attachments =
      let rec loop seen dimensions formats = function
        | [] -> Ok (Option.get dimensions, List.rev formats)
        | (attachment : color_attachment) :: rest ->
            if List.exists (same_attachment attachment) seen then
              error operation Invalid_argument
                "color-attachment list contains a duplicate texture"
            else
              (match ensure_texture_usable operation attachment.texture with
               | Error _ as failure -> failure
               | Ok () ->
                   (match
                      ensure_same_device operation device attachment.texture.device
                    with
                    | Error _ as failure -> failure
                    | Ok () ->
                        let descriptor = attachment.texture.descriptor in
                        let color = clear_color attachment.load_action in
                        if descriptor.kind <> Texture_2d then
                          error operation Invalid_argument
                            "Metal 4 base render attachments must be 2D textures"
                        else if descriptor.sample_count <> 1 then
                          error operation Invalid_argument
                            "Metal 4 base render attachments must be single-sample"
                        else if not (List.mem Render_target descriptor.usage) then
                          error operation Invalid_argument
                            "color attachment lacks render-target usage"
                        else if not (finite_color color) then
                          error operation Invalid_argument
                            "clear-color components must be finite"
                        else
                          let current = descriptor.width, descriptor.height in
                          (match dimensions with
                           | Some expected when expected <> current ->
                               error operation Invalid_argument
                                 "color attachments have different dimensions"
                           | None | Some _ ->
                               loop (attachment :: seen) (Some current)
                                 (descriptor.format :: formats) rest)))
      in
      loop [] None [] attachments

    let raw_attachment (attachment : color_attachment) =
      let clear = clear_color attachment.load_action in
      ({ Metal_raw.texture = attachment.texture.raw
       ; load_action = load_code attachment.load_action
       ; store_action = store_code attachment.store_action
       ; clear_red = clear.red
       ; clear_green = clear.green
       ; clear_blue = clear.blue
       ; clear_alpha = clear.alpha
       }
        : Metal_raw.metal4_render_attachment)

    let depth_capable_format = function
      | Texture.Depth16_unorm | Texture.Depth32_float
      | Texture.Depth24_unorm_stencil8 | Texture.Depth32_float_stencil8 -> true
      | _ -> false

    let validate_depth_attachment operation device ~width ~height = function
      | None -> Ok ()
      | Some (attachment : depth_attachment) ->
          let ( let* ) result callback = Result.bind result callback in
          let* () = ensure_texture_usable operation attachment.texture in
          let* () =
            ensure_same_device operation device attachment.texture.device
          in
          let descriptor = attachment.texture.descriptor in
          if descriptor.kind <> Texture_2d then
            error operation Invalid_argument
              "Metal 4 depth attachments must be 2D textures"
          else if descriptor.sample_count <> 1 then
            error operation Invalid_argument
              "Metal 4 depth attachments must be single-sample"
          else if descriptor.width <> width || descriptor.height <> height then
            error operation Invalid_argument
              "depth and color attachments have different dimensions"
          else if not (List.mem Render_target descriptor.usage) then
            error operation Invalid_argument
              "depth attachment lacks render-target usage"
          else if not (depth_capable_format descriptor.format) then
            error operation Invalid_argument
              "depth attachment does not use a depth-capable format"
          else if
            not (Float.is_finite attachment.clear_depth)
            || attachment.clear_depth < 0. || attachment.clear_depth > 1.
          then
            error operation Invalid_argument
              "clear depth must be finite and in [0, 1]"
          else Ok ()

    let raw_depth_attachment (attachment : depth_attachment) =
      ({ Metal_raw.texture = attachment.texture.raw
       ; load_action = depth_load_code attachment.load_action
       ; store_action = store_code attachment.store_action
       ; clear_depth = attachment.clear_depth
       }
        : Metal_raw.metal4_render_depth_attachment)

    let stencil_capable_format = function
      | Texture.Stencil8 | Texture.Depth24_unorm_stencil8
      | Texture.Depth32_float_stencil8 | Texture.X32_stencil8
      | Texture.X24_stencil8 -> true
      | _ -> false

    let validate_stencil_attachment operation device ~width ~height = function
      | None -> Ok ()
      | Some (attachment : stencil_attachment) ->
          let ( let* ) result callback = Result.bind result callback in
          let* () = ensure_texture_usable operation attachment.texture in
          let* () =
            ensure_same_device operation device attachment.texture.device
          in
          let descriptor = attachment.texture.descriptor in
          if descriptor.kind <> Texture_2d then
            error operation Invalid_argument
              "Metal 4 stencil attachments must be 2D textures"
          else if descriptor.sample_count <> 1 then
            error operation Invalid_argument
              "Metal 4 stencil attachments must be single-sample"
          else if descriptor.width <> width || descriptor.height <> height then
            error operation Invalid_argument
              "stencil and color attachments have different dimensions"
          else if not (List.mem Render_target descriptor.usage) then
            error operation Invalid_argument
              "stencil attachment lacks render-target usage"
          else if not (stencil_capable_format descriptor.format) then
            error operation Invalid_argument
              "stencil attachment does not use a stencil-capable format"
          else Ok ()

    let raw_stencil_attachment (attachment : stencil_attachment) =
      ({ Metal_raw.texture = attachment.texture.raw
       ; load_action = stencil_load_code attachment.load_action
       ; store_action = store_code attachment.store_action
       ; clear_stencil = attachment.clear_stencil
       }
        : Metal_raw.metal4_render_stencil_attachment)

    let validate_visibility_result_buffer operation device = function
      | None -> Ok ()
      | Some (buffer : Buffer.t) ->
          let ( let* ) result callback = Result.bind result callback in
          let* () = ensure_buffer_usable operation buffer in
          let* () = ensure_same_device operation device buffer.device in
          if buffer.length < 8L then
            error operation Invalid_argument
              "a visibility-result buffer must contain at least eight bytes"
          else Ok ()

    let create ?label ?depth_attachment ?stencil_attachment
        ?visibility_result_buffer
        ?(visibility_result_type = Visibility_reset)
        ?(support_color_attachment_mapping = false)
        (command_buffer : Command_buffer.t) ~color_attachments =
      let operation = "Metal.Command4.Render_encoder.create" in
      on_main operation (fun () ->
        match ensure_live operation command_buffer.lifetime with
        | Error _ as failure -> failure
        | Ok () when command_buffer.phase <> Command4_recording ->
            error operation Invalid_state "command buffer is not recording"
        | Ok () when dependent_count command_buffer.lifetime <> 0 ->
            error operation Invalid_state
              "command buffer already owns an open encoder"
        | Ok () when color_attachments = [] ->
            error operation Invalid_argument
              "at least one color attachment is required"
        | Ok () when List.length color_attachments > 8 ->
            error operation Invalid_argument
              "a render pass may contain at most eight color attachments"
        | Ok () when option_exists contains_nul label ->
            error operation Invalid_argument "label contains a NUL byte"
        | Ok ()
          when visibility_result_type = Visibility_accumulate
               && Option.is_none visibility_result_buffer ->
            error operation Invalid_argument
              "accumulated visibility results require a result buffer"
        | Ok () ->
            (match
               validate_attachments operation command_buffer.allocator.device
                 color_attachments
             with
             | Error _ as failure -> failure
             | Ok ((width, height), color_formats) ->
                 (match
                    validate_depth_attachment operation
                      command_buffer.allocator.device ~width ~height
                      depth_attachment
                  with
                  | Error _ as failure -> failure
                  | Ok () ->
                      (match
                         validate_stencil_attachment operation
                           command_buffer.allocator.device ~width ~height
                           stencil_attachment
                       with
                       | Error _ as failure -> failure
                       | Ok () ->
                           (match
                              validate_visibility_result_buffer operation
                                command_buffer.allocator.device
                                visibility_result_buffer
                            with
                            | Error _ as failure -> failure
                            | Ok () ->
                                let raw_descriptor :
                                    Metal_raw.metal4_render_pass_descriptor =
                                  { color_attachments =
                                      Array.of_list
                                        (List.map raw_attachment
                                           color_attachments)
                                  ; depth_attachment =
                                      Option.map raw_depth_attachment
                                        depth_attachment
                                  ; stencil_attachment =
                                      Option.map raw_stencil_attachment
                                        stencil_attachment
                                  ; width
                                  ; height
                                  ; label
                                  ; support_color_attachment_mapping
                                  ; visibility_result_buffer =
                                      Option.map
                                        (fun (buffer : Buffer.t) -> buffer.raw)
                                        visibility_result_buffer
                                  ; visibility_result_type =
                                      visibility_result_type_code
                                        visibility_result_type
                                  }
                                in
                                match
                                  Metal_raw.command4_render_encoder_create
                                    command_buffer.raw raw_descriptor
                                with
                                | Error message -> native_error operation message
                                | Ok (raw, tile_width, tile_height) ->
                                    List.iter
                                      (fun (attachment : color_attachment) ->
                                        retain_command4_texture command_buffer
                                          attachment.texture)
                                      color_attachments;
                                    Option.iter
                                      (fun (attachment : depth_attachment) ->
                                        retain_command4_texture command_buffer
                                          attachment.texture)
                                      depth_attachment;
                                    Option.iter
                                      (fun (attachment : stencil_attachment) ->
                                        retain_command4_texture command_buffer
                                          attachment.texture)
                                      stencil_attachment;
                                    Option.iter
                                      (retain_command4_buffer command_buffer)
                                      visibility_result_buffer;
                                    let value : t =
                                      { raw
                                      ; lifetime = lifetime ()
                                      ; command_buffer
                                      ; width
                                      ; height
                                      ; tile_width
                                      ; tile_height
                                      ; color_formats
                                      ; depth_format =
                                          Option.map
                                            (fun
                                              (attachment : depth_attachment) ->
                                              attachment.texture.descriptor.format)
                                            depth_attachment
                                      ; stencil_format =
                                          Option.map
                                            (fun
                                              (attachment : stencil_attachment) ->
                                              attachment.texture.descriptor.format)
                                            stencil_attachment
                                      ; support_color_attachment_mapping
                                      ; visibility_result_buffer
                                      ; color_store_actions =
                                          Array.of_list
                                            (List.map
                                               (fun
                                                 (attachment : color_attachment) ->
                                                 attachment.store_action)
                                               color_attachments)
                                      ; depth_store_action =
                                          Option.map
                                            (fun
                                              (attachment : depth_attachment) ->
                                              attachment.store_action)
                                            depth_attachment
                                      ; stencil_store_action =
                                          Option.map
                                            (fun
                                              (attachment : stencil_attachment) ->
                                              attachment.store_action)
                                            stencil_attachment
                                      ; vertex_amplification_count = 1
                                      ; pipeline = None
                                      ; mesh_limits = None
                                      ; tile_limits = None
                                      ; argument_tables = Array.make 5 None
                                      }
                                    in
                                    attach command_buffer.lifetime;
                                    attach_finalizer
                                      ~on_finalize:(fun () ->
                                        if
                                          command_buffer.phase
                                          = Command4_recording
                                        then
                                          command_buffer.phase <-
                                            Command4_failed
                                              "render encoder was abandoned before end_encoding")
                                      value value.lifetime
                                      command_buffer.lifetime;
                                    Ok value)))))

    let destroyed (value : t) = is_destroyed value.lifetime

    let observed_mesh_limits operation (pipeline : Render_pipeline.t) =
      match pipeline.mesh_constraints with
      | None ->
          error operation Native_error
            "mesh pipeline is missing its checked dispatch constraints"
      | Some constraints ->
          (match Metal_raw.render_pipeline_mesh_limits pipeline.raw with
           | Error message -> native_error operation message
           | Ok
               ( observed_max_object, observed_max_mesh
               , object_execution_width, mesh_execution_width
               , observed_max_threadgroups ) ->
               let select_limit observed configured =
                 if observed > 0 then observed
                 else Option.value configured ~default:0
               in
               let max_object_threads =
                 select_limit observed_max_object
                   constraints.configured_max_object_threads
               in
               let max_mesh_threads =
                 select_limit observed_max_mesh
                   constraints.configured_max_mesh_threads
               in
               let max_mesh_threadgroups =
                 select_limit observed_max_threadgroups
                   constraints.configured_max_mesh_threadgroups
               in
               if max_mesh_threads <= 0 || mesh_execution_width <= 0 then
                 error operation Native_error
                   "Metal returned incomplete mesh-stage execution limits"
               else if
                 constraints.has_object_stage
                 && (max_object_threads <= 0 || object_execution_width <= 0
                    || max_mesh_threadgroups <= 0)
               then
                 error operation Native_error
                   "Metal returned incomplete object-stage execution limits"
               else
                 Ok
                   { max_object_threads
                   ; max_mesh_threads
                   ; object_execution_width
                   ; mesh_execution_width
                   ; max_mesh_threadgroups
                   })

    let observed_tile_limits operation (value : t)
        (pipeline : Render_pipeline.t) =
      match pipeline.tile_constraints with
      | None ->
          error operation Native_error
            "tile pipeline is missing its checked dispatch constraints"
      | Some constraints ->
          (match Metal_raw.render_pipeline_tile_limits pipeline.raw with
           | Error message -> native_error operation message
           | Ok (observed_maximum, matches_tile_size) ->
               if
                 matches_tile_size
                 <> constraints.threadgroup_size_matches_tile_size
               then
                 error operation Native_error
                   "Metal changed the tile-size matching guarantee"
               else
                 let configured_maximum =
                   Option.value constraints.configured_max_tile_threads
                     ~default:0
                 in
                 let tile_area =
                   match product3 value.tile_width value.tile_height 1 with
                   | Some area -> area
                   | None -> 0
                 in
                 let max_tile_threads =
                   if observed_maximum > 0 then observed_maximum
                   else if configured_maximum > 0 then configured_maximum
                   else if matches_tile_size then tile_area
                   else 0
                 in
                 if max_tile_threads <= 0 then
                   error operation Native_error
                     "Metal returned no usable tile-threadgroup maximum"
                 else Ok { max_tile_threads; matches_tile_size })

    let set_pipeline (value : t) (pipeline : Render_pipeline.t) =
      let operation = "Metal.Command4.Render_encoder.set_pipeline" in
      on_main operation (fun () ->
        match ensure_live operation value.lifetime with
        | Error _ as failure -> failure
        | Ok () ->
            (match ensure_live operation pipeline.lifetime with
             | Error _ as failure -> failure
             | Ok () ->
                 (match
                    ensure_same_device operation
                      value.command_buffer.allocator.device pipeline.device
                  with
                  | Error _ as failure -> failure
                  | Ok () when pipeline.raster_sample_count <> 1 ->
                      error operation Invalid_argument
                        "pipeline sample count does not match the render pass"
                  | Ok () when pipeline.color_formats <> value.color_formats ->
                      error operation Invalid_argument
                        "pipeline color formats do not match the render pass"
                  | Ok ()
                    when pipeline.color_attachment_mapping = Inherited
                         && not value.support_color_attachment_mapping ->
                      error operation Invalid_argument
                        "an inherited color-attachment mapping pipeline requires render-pass mapping support"
                  | Ok ()
                    when value.vertex_amplification_count
                         > pipeline.max_vertex_amplification_count ->
                      error operation Invalid_argument
                        "pipeline maximum is below the active vertex amplification count"
                  | Ok () ->
                      let limits =
                        match pipeline.kind with
                        | Mesh ->
                            Result.map (fun limits -> Some limits, None)
                              (observed_mesh_limits operation pipeline)
                        | Tile ->
                            Result.map (fun limits -> None, Some limits)
                              (observed_tile_limits operation value pipeline)
                        | Render -> Ok (None, None)
                      in
                      (match limits with
                       | Error _ as failure -> failure
                       | Ok (mesh_limits, tile_limits) ->
                           match
                             Metal_raw.command4_render_encoder_set_pipeline
                               value.raw value.command_buffer.raw pipeline.raw
                           with
                           | Error message -> native_error operation message
                           | Ok () ->
                               retain_command4_render_pipeline
                                 value.command_buffer pipeline;
                               value.pipeline <- Some pipeline;
                               value.mesh_limits <- mesh_limits;
                               value.tile_limits <- tile_limits;
                               Ok ()))))

    let uint32_offset value =
      value >= 0 && Int64.compare (Int64.of_int value) 0xFFFF_FFFFL <= 0

    let raw_view_mapping (mapping : vertex_amplification_view_mapping) =
      ({ Metal_raw.viewport_array_index_offset =
           Int64.of_int mapping.viewport_array_index_offset
       ; render_target_array_index_offset =
           Int64.of_int mapping.render_target_array_index_offset
       }
        : Metal_raw.metal4_vertex_amplification_view_mapping)

    let set_vertex_amplification_count (value : t) ?view_mappings count =
      let operation =
        "Metal.Command4.Render_encoder.set_vertex_amplification_count"
      in
      on_main operation (fun () ->
        match ensure_live operation value.lifetime with
        | Error _ as failure -> failure
        | Ok () when count <= 0 || count > 2 ->
            error operation Invalid_argument
              "Metal 4 vertex amplification count must be between one and two"
        | Ok () ->
            (match value.pipeline with
             | None ->
                 error operation Invalid_state
                   "vertex amplification requires a bound render pipeline"
             | Some pipeline when pipeline.kind = Tile ->
                 error operation Invalid_state
                   "vertex amplification is unavailable for tile pipelines"
             | Some pipeline
               when count > pipeline.max_vertex_amplification_count ->
                 error operation Invalid_argument
                   "vertex amplification count exceeds the pipeline maximum"
             | Some _
               when not
                      (Metal_raw.device_supports_vertex_amplification_count
                         value.command_buffer.allocator.device.raw count) ->
                 error operation Unsupported
                   "the Metal device does not support the vertex amplification count"
             | Some _ ->
                 let mapping_validation =
                   match view_mappings with
                   | None -> Ok ()
                   | Some mappings when List.length mappings <> count ->
                       error operation Invalid_argument
                         "the view-mapping count must equal the vertex amplification count"
                   | Some mappings
                     when List.exists
                            (fun mapping ->
                              not
                                (uint32_offset
                                   mapping.viewport_array_index_offset
                                 && uint32_offset
                                      mapping.render_target_array_index_offset))
                            mappings ->
                       error operation Invalid_argument
                         "vertex amplification view offsets must fit uint32"
                   | Some _ -> Ok ()
                 in
                 (match mapping_validation with
                  | Error _ as failure -> failure
                  | Ok () ->
                      let raw_mappings =
                        Option.map
                          (fun mappings ->
                            Array.of_list (List.map raw_view_mapping mappings))
                          view_mappings
                      in
                      match
                        Metal_raw
                        .command4_render_encoder_set_vertex_amplification_count
                          value.raw value.command_buffer.raw count raw_mappings
                      with
                      | Error message -> native_error operation message
                      | Ok () ->
                          value.vertex_amplification_count <- count;
                          Ok ())))

    let validate_color_attachment_map operation attachment_count = function
      | None -> Ok None
      | Some physical_indices
        when List.length physical_indices <> attachment_count ->
          error operation Invalid_argument
            "the color-attachment map must cover every render attachment"
      | Some physical_indices
        when List.exists
               (fun index -> index < 0 || index >= attachment_count)
               physical_indices ->
          error operation Invalid_argument
            "a mapped physical color-attachment index is out of range"
      | Some physical_indices
        when List.length (List.sort_uniq Int.compare physical_indices)
             <> attachment_count ->
          error operation Invalid_argument
            "the color-attachment map must be a permutation"
      | Some physical_indices -> Ok (Some (Array.of_list physical_indices))

    let set_color_attachment_map (value : t) physical_indices =
      let operation =
        "Metal.Command4.Render_encoder.set_color_attachment_map"
      in
      on_main operation (fun () ->
        match ensure_live operation value.lifetime with
        | Error _ as failure -> failure
        | Ok () when not value.support_color_attachment_mapping ->
            error operation Invalid_state
              "the render pass did not enable color-attachment mapping"
        | Ok () ->
            (match value.pipeline with
             | None ->
                 error operation Invalid_state
                   "color-attachment mapping requires a bound render pipeline"
             | Some pipeline
               when pipeline.color_attachment_mapping <> Inherited ->
                 error operation Invalid_state
                   "the bound pipeline does not inherit its color-attachment mapping"
             | Some _ ->
                 (match
                    validate_color_attachment_map operation
                      (List.length value.color_formats) physical_indices
                  with
                  | Error _ as failure -> failure
                  | Ok raw_map ->
                      match
                        Metal_raw.command4_render_encoder_set_color_attachment_map
                          value.raw value.command_buffer.raw raw_map
                      with
                      | Error message -> native_error operation message
                      | Ok () -> Ok ())))

    let set_depth_stencil_state (value : t) state =
      let operation =
        "Metal.Command4.Render_encoder.set_depth_stencil_state"
      in
      on_main operation (fun () ->
        let ( let* ) result callback = Result.bind result callback in
        let* () = ensure_live operation value.lifetime in
        let* () =
          match state with
          | None -> Ok ()
          | Some (state : Depth_stencil.t) ->
              let* () = ensure_live operation state.lifetime in
              let* () =
                ensure_same_device operation
                  value.command_buffer.allocator.device state.device
              in
              if
                Option.is_none value.depth_format
                && (state.depth_write || state.depth_compare <> Always)
              then
                error operation Invalid_state
                  "active depth testing requires a depth attachment"
              else if
                Option.is_none value.stencil_format
                && (Option.is_some state.front_stencil
                   || Option.is_some state.back_stencil)
              then
                error operation Invalid_state
                  "active stencil testing requires a stencil attachment"
              else Ok ()
        in
        let raw_state =
          Option.map (fun (state : depth_stencil) -> state.raw) state
        in
        match
          Metal_raw.command4_render_encoder_set_depth_stencil value.raw
            value.command_buffer.raw raw_state
        with
        | Error message -> native_error operation message
        | Ok () ->
            Option.iter
              (retain_command4_depth_stencil value.command_buffer)
              state;
            Ok ())

    let set_stencil_reference (value : t) reference =
      let operation = "Metal.Command4.Render_encoder.set_stencil_reference" in
      on_main operation (fun () ->
        match ensure_live operation value.lifetime with
        | Error _ as failure -> failure
        | Ok () when Option.is_none value.stencil_format ->
            error operation Invalid_state
              "stencil reference requires a stencil attachment"
        | Ok () ->
            (match
               Metal_raw.command4_render_encoder_set_stencil_reference
                 value.raw value.command_buffer.raw reference
             with
             | Error message -> native_error operation message
             | Ok () -> Ok ()))

    let set_stencil_references (value : t) ~front ~back =
      let operation = "Metal.Command4.Render_encoder.set_stencil_references" in
      on_main operation (fun () ->
        match ensure_live operation value.lifetime with
        | Error _ as failure -> failure
        | Ok () when Option.is_none value.stencil_format ->
            error operation Invalid_state
              "stencil references require a stencil attachment"
        | Ok () ->
            (match
               Metal_raw.command4_render_encoder_set_stencil_references
                 value.raw value.command_buffer.raw front back
             with
             | Error message -> native_error operation message
             | Ok () -> Ok ()))

    let set_blend_color (value : t) color =
      let operation = "Metal.Command4.Render_encoder.set_blend_color" in
      on_main operation (fun () ->
        match ensure_live operation value.lifetime with
        | Error _ as failure -> failure
        | Ok ()
          when not
                 (finite_float32 color.red && finite_float32 color.green
                 && finite_float32 color.blue && finite_float32 color.alpha) ->
            error operation Invalid_argument
              "blend-color components must be finite float32 values"
        | Ok () ->
            (match
               Metal_raw.command4_render_encoder_set_blend_color value.raw
                 value.command_buffer.raw
                 (color.red, color.green, color.blue, color.alpha)
             with
             | Error message -> native_error operation message
             | Ok () -> Ok ()))

    let stage_index = function
      | Vertex -> 0
      | Fragment -> 1
      | Tile -> 2
      | Object -> 3
      | Mesh -> 4

    let stage_bit stage = 1 lsl stage_index stage

    let validate_stages operation stages =
      if stages = [] then
        error operation Invalid_argument
          "at least one render stage is required"
      else if List.length stages <> List.length (List.sort_uniq compare stages)
      then
        error operation Invalid_argument
          "render-stage list contains a duplicate"
      else
        Ok (List.fold_left (fun bits stage -> bits lor stage_bit stage) 0 stages)

    let set_argument_table (value : t) ~stages table =
      let operation = "Metal.Command4.Render_encoder.set_argument_table" in
      on_main operation (fun () ->
        match ensure_live operation value.lifetime with
        | Error _ as failure -> failure
        | Ok () ->
            (match validate_stages operation stages with
             | Error _ as failure -> failure
             | Ok stage_mask ->
                 let validation =
                   match table with
                   | None -> Ok ()
                   | Some (table : Argument_table.t) ->
                       (match ensure_live operation table.lifetime with
                        | Error _ as failure -> failure
                        | Ok () ->
                            ensure_same_device operation
                              value.command_buffer.allocator.device table.device)
                 in
                 (match validation with
                  | Error _ as failure -> failure
                  | Ok () ->
                      let raw_table =
                        Option.map
                          (fun (table : command4_argument_table) -> table.raw)
                          table
                      in
                      match
                        Metal_raw.command4_render_encoder_set_argument_table
                          value.raw value.command_buffer.raw raw_table stage_mask
                      with
                      | Error message -> native_error operation message
                      | Ok () ->
                          Option.iter
                            (retain_command4_argument_table value.command_buffer)
                            table;
                          List.iter
                            (fun stage ->
                              value.argument_tables.(stage_index stage) <- table)
                            stages;
                          Ok ())))

    let tile_size (value : t) = value.tile_width, value.tile_height

    let viewport ~x ~y ~width ~height ~z_near ~z_far =
      { x; y; width; height; z_near; z_far }

    let scissor_rect ~x ~y ~width ~height = { x; y; width; height }

    let validate_viewport operation (value : t) (viewport : viewport) =
      let fields =
        [ viewport.x; viewport.y; viewport.width; viewport.height
        ; viewport.z_near; viewport.z_far
        ]
      in
      if not (List.for_all Float.is_finite fields) then
        error operation Invalid_argument "viewport values must be finite"
      else if
        viewport.x < 0. || viewport.y < 0. || viewport.width <= 0.
        || viewport.height <= 0.
        || viewport.width > float value.width -. viewport.x
        || viewport.height > float value.height -. viewport.y
        || viewport.z_near < 0. || viewport.z_near > 1.
        || viewport.z_far < 0. || viewport.z_far > 1.
        || viewport.z_near > viewport.z_far
      then
        error operation Invalid_argument
          "viewport lies outside the render target or depth range"
      else Ok ()

    let raw_viewport (viewport : viewport) =
      ( viewport.x, viewport.y, viewport.width, viewport.height
      , viewport.z_near, viewport.z_far )

    let set_viewport (value : t) viewport =
      let operation = "Metal.Command4.Render_encoder.set_viewport" in
      on_main operation (fun () ->
        let ( let* ) result callback = Result.bind result callback in
        let* () = ensure_live operation value.lifetime in
        let* () = validate_viewport operation value viewport in
        match
          Metal_raw.command4_render_encoder_set_viewport value.raw
            (raw_viewport viewport)
        with
        | Ok () -> Ok ()
        | Error message -> native_error operation message)

    let set_viewports (value : t) viewports =
      let operation = "Metal.Command4.Render_encoder.set_viewports" in
      on_main operation (fun () ->
        let ( let* ) result callback = Result.bind result callback in
        let* () = ensure_live operation value.lifetime in
        let count = List.length viewports in
        if count = 0 || count > 16 then
          error operation Invalid_argument
            "viewport arrays must contain between one and sixteen entries"
        else
          let rec validate = function
            | [] -> Ok ()
            | viewport :: rest ->
                let* () = validate_viewport operation value viewport in
                validate rest
          in
          let* () = validate viewports in
          match
            Metal_raw.command4_render_encoder_set_viewports value.raw
              (Array.of_list (List.map raw_viewport viewports))
          with
          | Ok () -> Ok ()
          | Error message -> native_error operation message)

    let validate_scissor_rect operation (value : t) (rect : scissor_rect) =
      if rect.x < 0 || rect.y < 0 || rect.width <= 0 || rect.height <= 0 then
        error operation Invalid_argument
          "scissor coordinates must be nonnegative and dimensions positive"
      else if
        rect.x > value.width - rect.width
        || rect.y > value.height - rect.height
      then
        error operation Invalid_argument
          "scissor rectangle lies outside the render target"
      else Ok ()

    let raw_scissor_rect (rect : scissor_rect) =
      ({ Metal_raw.x = Int64.of_int rect.x
       ; y = Int64.of_int rect.y
       ; width = Int64.of_int rect.width
       ; height = Int64.of_int rect.height
       }
        : Metal_raw.metal4_scissor_rect)

    let set_scissor_rect (value : t) rect =
      let operation = "Metal.Command4.Render_encoder.set_scissor_rect" in
      on_main operation (fun () ->
        let ( let* ) result callback = Result.bind result callback in
        let* () = ensure_live operation value.lifetime in
        let* () = validate_scissor_rect operation value rect in
        match
          Metal_raw.command4_render_encoder_set_scissor_rect value.raw
            (raw_scissor_rect rect)
        with
        | Ok () -> Ok ()
        | Error message -> native_error operation message)

    let set_scissor_rects (value : t) rects =
      let operation = "Metal.Command4.Render_encoder.set_scissor_rects" in
      on_main operation (fun () ->
        let ( let* ) result callback = Result.bind result callback in
        let* () = ensure_live operation value.lifetime in
        let count = List.length rects in
        if count = 0 || count > 16 then
          error operation Invalid_argument
            "scissor arrays must contain between one and sixteen entries"
        else
          let rec validate = function
            | [] -> Ok ()
            | rect :: rest ->
                let* () = validate_scissor_rect operation value rect in
                validate rest
          in
          let* () = validate rects in
          match
            Metal_raw.command4_render_encoder_set_scissor_rects value.raw
              (Array.of_list (List.map raw_scissor_rect rects))
          with
          | Ok () -> Ok ()
          | Error message -> native_error operation message)

    let winding_code = function Clockwise -> 0 | Counter_clockwise -> 1

    let set_front_facing_winding (value : t) winding =
      let operation =
        "Metal.Command4.Render_encoder.set_front_facing_winding"
      in
      on_main operation (fun () ->
