    let visibility_result_mode_code = function
      | Visibility_disabled -> 0
      | Visibility_boolean -> 1
      | Visibility_counting -> 2

    let set_visibility_result_mode (value : t) mode ~offset =
      let operation =
        "Metal.Command4.Render_encoder.set_visibility_result_mode"
      in
      on_main operation (fun () ->
        let ( let* ) result callback = Result.bind result callback in
        let* () = ensure_live operation value.lifetime in
        if offset < 0L || Int64.rem offset 8L <> 0L then
          error operation Invalid_argument
            "visibility-result offsets must be nonnegative multiples of eight"
        else
          let* () =
            match mode, value.visibility_result_buffer with
            | Visibility_disabled, _ -> Ok ()
            | (Visibility_boolean | Visibility_counting), None ->
                error operation Invalid_state
                  "active visibility testing requires a result buffer"
            | (Visibility_boolean | Visibility_counting), Some buffer ->
                let* () = ensure_buffer_usable operation buffer in
                if
                  buffer.length < 8L
                  || offset > Int64.sub buffer.length 8L
                then
                  error operation Invalid_argument
                    "visibility-result slot exceeds the result buffer"
                else Ok ()
          in
          match
            Metal_raw.command4_render_encoder_set_visibility_result_mode
              value.raw (visibility_result_mode_code mode) offset
          with
          | Ok () -> Ok ()
          | Error message -> native_error operation message)

    let primitive_code = function
      | Point -> 0
      | Line -> 1
      | Line_strip -> 2
      | Triangle -> 3
      | Triangle_strip -> 4

    let index_type_code = function Uint16 -> 0 | Uint32 -> 1
    let index_stride = function Uint16 -> 2L | Uint32 -> 4L

    let current_argument_tables (value : t) =
      Array.fold_left
        (fun (tables : command4_argument_table list) -> function
          | None -> tables
          | Some (table : command4_argument_table)
            when List.exists
                   (fun (candidate : command4_argument_table) ->
                     candidate.lifetime == table.lifetime)
                   tables -> tables
          | Some table -> table :: tables)
        [] value.argument_tables
      |> List.rev

    let retain_argument_tables operation (value : t)
        (tables : command4_argument_table list) =
      let rec loop = function
        | [] -> Ok ()
        | table :: rest ->
            (match
               retain_command4_argument_bindings operation value.command_buffer
                 table
             with
             | Error _ as failure -> failure
             | Ok () -> loop rest)
      in
      loop tables

    let ensure_conventional_pipeline operation (value : t) =
      match value.pipeline with
      | None -> error operation Invalid_state "no render pipeline is bound"
      | Some pipeline when pipeline.kind <> Render ->
          error operation Invalid_state
            "primitive draws require a conventional render pipeline"
      | Some _ -> Ok ()

    let validate_vertex_range operation ~vertex_start ~vertex_count =
      if
        vertex_start < 0 || vertex_count <= 0
        || vertex_start > max_int - (vertex_count - 1)
      then
        error operation Invalid_argument
          "draw range must be positive and fit in an OCaml integer"
      else Ok ()

    let validate_instance_range operation ~instance_count ~base_instance =
      if
        instance_count <= 0 || base_instance < 0
        || base_instance > max_int - (instance_count - 1)
      then
        error operation Invalid_argument
          "instance range must be positive and fit in an OCaml integer"
      else Ok ()

    let prepare_argument_tables operation (value : t) =
      let validate_vertex_bindings () =
        match value.pipeline with
        | None -> Ok ()
        | Some { vertex_descriptor = None; _ } -> Ok ()
        | Some { vertex_descriptor = Some descriptor; _ } ->
            (match value.argument_tables.(stage_index Vertex) with
             | None ->
                 error operation Invalid_state
                   "a vertex descriptor requires a vertex argument table"
             | Some table ->
                 let rec loop = function
                   | [] -> Ok ()
                   | (layout : Vertex_descriptor.layout) :: rest ->
                       if layout.buffer_index >= table.max_buffers then
                         error operation Invalid_state
                           "a vertex layout exceeds the argument-table capacity"
                       else if Option.is_none table.buffers.(layout.buffer_index)
                       then
                         error operation Invalid_state
                           "a vertex layout has no bound buffer"
                       else
                         (match
                            layout.stride,
                            table.buffer_strides.(layout.buffer_index)
                          with
                          | Vertex_descriptor.Dynamic, Some _ -> loop rest
                          | Dynamic, None ->
                              error operation Invalid_state
                                "a dynamic vertex layout has no bound stride"
                          | Static _, None -> loop rest
                          | Static _, Some _ ->
                              error operation Invalid_state
                                "a static vertex layout received a dynamic stride")
                 in
                 loop (Vertex_descriptor.layouts descriptor))
      in
      let ( let* ) result callback = Result.bind result callback in
      let* () = validate_vertex_bindings () in
      let tables = current_argument_tables value in
      let* () = retain_argument_tables operation value tables in
      Ok
        (Array.of_list
           (List.map
              (fun (table : command4_argument_table) -> table.raw)
              tables))

    let validate_index_range operation index_type (index_buffer : Buffer.t)
        ~index_offset ~index_count =
      let stride = index_stride index_type in
      let count = Int64.of_int index_count in
      let ( let* ) result callback = Result.bind result callback in
      let* index_length =
        if index_count <= 0 then
          error operation Invalid_argument "index count must be positive"
        else if index_offset < 0L || Int64.rem index_offset stride <> 0L then
          error operation Invalid_argument
            "index-buffer offset is negative or misaligned"
        else if count > Int64.div Int64.max_int stride then
          error operation Invalid_argument "index-buffer byte span overflows"
        else Ok (Int64.mul count stride)
      in
      if
        index_offset > index_buffer.length
        || index_length > Int64.sub index_buffer.length index_offset
      then
        error operation Invalid_argument
          "indexed draw exceeds the index-buffer bounds"
      else Ok ()

    let ensure_buffer_device operation (value : t) (buffer : Buffer.t) =
      let ( let* ) result callback = Result.bind result callback in
      let* () = ensure_buffer_usable operation buffer in
      ensure_same_device operation value.command_buffer.allocator.device
        buffer.device

    let validate_aligned_buffer_range operation (buffer : Buffer.t) ~name
        ~offset ~length ~alignment =
      if offset < 0L || Int64.rem offset alignment <> 0L then
        error operation Invalid_argument
          (Printf.sprintf "%s offset is negative or misaligned" name)
      else if length <= 0L || Int64.rem length alignment <> 0L then
        error operation Invalid_argument
          (Printf.sprintf "%s length is not a positive aligned span" name)
      else if
        offset > buffer.length || length > Int64.sub buffer.length offset
      then
        error operation Invalid_argument
          (Printf.sprintf "%s range exceeds its buffer" name)
      else Ok ()

    let validate_indirect_arguments operation (buffer : Buffer.t) ~offset
        ~size =
      validate_aligned_buffer_range operation buffer ~name:"indirect-buffer"
        ~offset ~length:size ~alignment:4L

    let draw_primitives (value : t) primitive ~vertex_start ~vertex_count =
      let operation = "Metal.Command4.Render_encoder.draw_primitives" in
      on_main operation (fun () ->
        let ( let* ) result callback = Result.bind result callback in
        let* () = ensure_live operation value.lifetime in
        let* () = ensure_conventional_pipeline operation value in
        let* () = validate_vertex_range operation ~vertex_start ~vertex_count in
        let* raw_tables = prepare_argument_tables operation value in
        match
          Metal_raw.command4_render_encoder_draw_primitives value.raw
            value.command_buffer.raw raw_tables
            (primitive_code primitive, vertex_start, vertex_count)
        with
        | Ok () -> Ok ()
        | Error message -> native_error operation message)

