  let sample_counters (value:t) (samples:counter_sample_buffer) ~index ~barrier=
    let operation="Metal.Acceleration_encoder.sample_counters"in on_main operation(fun()->
      match ensure_live operation value.lifetime with Error _ as e->e|Ok()->
      Result.bind(ensure_live operation samples.lifetime)(fun()->
      Result.bind(ensure_same_device operation value.command_buffer.queue.device samples.device)(fun()->
      if index<0L||index>=samples.sample_count then error operation Invalid_argument "counter sample index is out of range"
      else match Metal_raw.acceleration_supports_counters samples.device.raw with Error m->native_error operation m|Ok false->error operation Unsupported "device does not support acceleration stage-boundary counters"|Ok true->
      match Metal_raw.acceleration_encoder_sample value.raw samples.raw index barrier with Error m->native_error operation m|Ok()->
        if not(List.exists((==)samples.lifetime)!(value.command_buffer.presentation_events))then begin attach samples.lifetime;value.command_buffer.presentation_events:=samples.lifetime::!(value.command_buffer.presentation_events)end;Ok())))

  let usage_code=function Read->1L|Write->2L|Read_write->3L
  let use_resources (value:t) ~usage resources=
    let operation="Metal.Acceleration_encoder.use_resources"in on_main operation(fun()->
      match ensure_live operation value.lifetime with Error _ as e->e|Ok()->if resources=[]then error operation Invalid_argument "resources must not be empty"else
      let device=value.command_buffer.queue.device in
      let rec validate=function []->Ok()|Buffer_resource b::rest->Result.bind(ensure_buffer_usable operation b)(fun()->Result.bind(ensure_same_device operation device b.device)(fun()->validate rest))|Texture_resource t::rest->Result.bind(ensure_texture_usable operation t)(fun()->Result.bind(ensure_same_device operation device t.device)(fun()->validate rest))in
      Result.bind(validate resources)(fun()->let raw=Array.of_list(List.map(function Buffer_resource b->0,b.raw|Texture_resource t->1,t.raw)resources)in match Metal_raw.acceleration_encoder_use value.raw[||]raw(usage_code usage)with Error m->native_error operation m|Ok()->List.iter(function Buffer_resource b->retain_command_buffer_buffer value.command_buffer b|Texture_resource t->retain_command_buffer_texture value.command_buffer t)resources;Ok()))
  let use_heaps (value:t) heaps=
    let operation="Metal.Acceleration_encoder.use_heaps"in on_main operation(fun()->match ensure_live operation value.lifetime with Error _ as e->e|Ok()->if heaps=[]then error operation Invalid_argument "heaps must not be empty"else let device=value.command_buffer.queue.device in let rec validate=function []->Ok()|(heap:heap)::rest->Result.bind(ensure_live operation heap.lifetime)(fun()->Result.bind(ensure_same_device operation device heap.device)(fun()->validate rest))in Result.bind(validate heaps)(fun()->match Metal_raw.acceleration_encoder_use value.raw(Array.of_list(List.map(fun(h:heap)->h.raw)heaps))[||]1L with Error m->native_error operation m|Ok()->List.iter(retain_command_buffer_heap value.command_buffer)heaps;Ok()))

  let write_compacted_size_typed (value:t) ~source ~destination ~offset kind=
    let operation="Metal.Acceleration_encoder.write_compacted_size_typed"in on_main operation(fun()->match ensure_live operation value.lifetime with Error _ as e->e|Ok()->let bytes,code=match kind with Uint32->4L,0|Uint64->8L,1 in Result.bind(validate_acceleration operation value.command_buffer.queue.device source)(fun()->Result.bind(ensure_buffer_usable operation destination)(fun()->Result.bind(ensure_same_device operation value.command_buffer.queue.device destination.device)(fun()->if offset<0L||Int64.rem offset bytes<>0L||offset>destination.length||bytes>Int64.sub destination.length offset then error operation Invalid_argument "compacted-size output range is invalid"else match Metal_raw.acceleration_encoder_write_type value.raw source.raw destination.raw offset code with Error m->native_error operation m|Ok()->retain_command_buffer_acceleration_structure value.command_buffer source;retain_command_buffer_buffer value.command_buffer destination;Ok()))))

  let destroyed value = is_destroyed value.lifetime

  let end_encoding value =
    let operation = "Metal.Acceleration_encoder.end_encoding" in
    on_main operation (fun () ->
      match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () ->
          match Metal_raw.acceleration_encoder_end value.raw with
          | Error message -> native_error operation message
          | Ok () ->
              if Atomic.compare_and_set value.lifetime.destroyed false true then begin
                ignore (Metal_raw.destroy value.raw);
                detach value.command_buffer.lifetime
              end;
              Ok ())
end

module Render_encoder = struct
  type t = render_encoder

  type cull_mode = No_cull | Cull_front | Cull_back
  type winding = Clockwise | Counter_clockwise
  type fill_mode = Fill | Lines
  type visibility = Visibility_disabled | Visibility_boolean | Visibility_counting
  type store_action = Store_dont_care | Store | Multisample_resolve
                    | Store_and_multisample_resolve
  type stage = Vertex | Fragment | Tile | Object | Mesh
  type barrier_scope = Buffers | Textures | Render_targets
  type resource_usage = Read | Write | Sample
  type resource = Buffer_resource of Buffer.t | Texture_resource of Texture.t
  type primitive = Point | Line | Line_strip | Triangle | Triangle_strip
  type index_type = Uint16 | Uint32

  type viewport =
    { x : float; y : float; width : float; height : float
    ; znear : float; zfar : float }

  type scissor = { x : int; y : int; width : int; height : int }

  let create (command_buffer : Command_buffer.t) ~(target : Texture.t)
      ?(clear = (0., 0., 0., 1.)) ?(depth : Texture.t option)
      ?(stencil : Texture.t option) () =
    let operation = "Metal.Render_encoder.create" in
    on_main operation (fun () ->
      match ensure_live operation command_buffer.lifetime with
      | Error _ as failure -> failure
      | Ok () when command_buffer.phase <> Recording ->
          error operation Invalid_state "command buffer is no longer recording"
      | Ok () when dependent_count command_buffer.lifetime <> 0 ->
          error operation Invalid_state "command buffer already has an open encoder"
      | Ok () ->
          (match ensure_texture_usable operation target with
           | Error _ as failure -> failure
           | Ok () when not (List.mem Render_target target.descriptor.usage) ->
               error operation Invalid_argument
                 "render target texture lacks Render_target usage"
           | Ok () when target.descriptor.sample_count <> 1 ->
               error operation Invalid_argument
                 "classic render encoder currently requires one sample"
           | Ok () when
               not
                 (same_device command_buffer.queue.device target.device) ->
               error operation Device_mismatch
                 "render target belongs to another device"
           | Ok () ->
               let valid_attachment texture formats =
                 match ensure_texture_usable operation texture with
                 | Error _ as failure -> failure
                 | Ok () when not (List.mem Render_target texture.descriptor.usage) ->
                     error operation Invalid_argument "attachment lacks Render_target usage"
                 | Ok () when not (List.mem texture.descriptor.format formats) ->
                     error operation Invalid_argument "attachment pixel format is incompatible"
                 | Ok () when texture.descriptor.width <> target.descriptor.width
                              || texture.descriptor.height <> target.descriptor.height
                              || texture.descriptor.sample_count <> target.descriptor.sample_count ->
                     error operation Invalid_argument "attachment dimensions or sample count differ"
                 | Ok () -> ensure_same_device operation command_buffer.queue.device texture.device
               in
               let depth_formats = [ Texture.Depth16_unorm; Texture.Depth32_float; Texture.Depth24_unorm_stencil8; Texture.Depth32_float_stencil8 ] in
               let stencil_formats = [ Texture.Stencil8; Texture.Depth24_unorm_stencil8; Texture.Depth32_float_stencil8 ] in
               let attachment_check =
                 match depth with Some texture -> valid_attachment texture depth_formats | None -> Ok ()
               in
               let attachment_check = Result.bind attachment_check (fun () -> match stencil with Some texture -> valid_attachment texture stencil_formats | None -> Ok ()) in
               Result.bind attachment_check (fun () ->
               let r, g, b, a = clear in
               if not (List.for_all Float.is_finite [ r; g; b; a ]) then
                 error operation Invalid_argument "clear color must be finite"
               else
                 match
                   Metal_raw.command_buffer_render_encoder_attachments command_buffer.raw
                     target.raw (Option.map (fun (x:texture)->x.raw) depth)
                     (Option.map (fun (x:texture)->x.raw) stencil) clear
                 with
                 | Error message -> native_error operation message
                 | Ok raw ->
                     let value : t =
                       { raw; lifetime = lifetime (); command_buffer; target
                       ; depth; stencil; pipeline = None }
                     in
                     attach command_buffer.lifetime;
                     retain_command_buffer_texture command_buffer target;
                     Option.iter (retain_command_buffer_texture command_buffer) depth;
                     Option.iter (retain_command_buffer_texture command_buffer) stencil;
                     attach_finalizer value value.lifetime command_buffer.lifetime;
                     Ok value)))

  let create_from_pass (command_buffer : Command_buffer.t)
      (pass : render_pass_descriptor) =
    let operation = "Metal.Render_encoder.create_from_pass" in
    on_main operation (fun () ->
      match ensure_live operation command_buffer.lifetime with
      | Error _ as failure -> failure
      | Ok () when command_buffer.phase <> Recording ->
          error operation Invalid_state "command buffer is no longer recording"
      | Ok () when dependent_count command_buffer.lifetime <> 0 ->
          error operation Invalid_state "command buffer already has an open encoder"
      | Ok () ->
          (match ensure_live operation pass.lifetime with
           | Error _ as failure -> failure
           | Ok () ->
               (match pass.pass_color with
                | None ->
                    error operation Invalid_state
                      "render pass has no color attachment"
                | Some target ->
                    (match ensure_same_device operation
                             command_buffer.queue.device target.device with
                     | Error _ as failure -> failure
                     | Ok () ->
                         match Metal_raw.command_buffer_render_encoder_from_pass
                                 command_buffer.raw pass.raw with
                         | Error message -> native_error operation message
                         | Ok raw ->
                             let value : t =
                               { raw; lifetime=lifetime (); command_buffer; target
                               ; depth=pass.pass_depth; stencil=pass.pass_stencil
                               ; pipeline=None }
                             in
                             attach command_buffer.lifetime;
                             retain_command_buffer_texture command_buffer target;
                             Option.iter (retain_command_buffer_texture command_buffer)
                               pass.pass_depth;
                             Option.iter (retain_command_buffer_texture command_buffer)
                               pass.pass_stencil;
                             Option.iter (retain_command_buffer_buffer command_buffer)
                               pass.pass_visibility;
                             attach_finalizer value value.lifetime
                               command_buffer.lifetime;
                             Ok value))))

  let destroyed (value : t) = is_destroyed value.lifetime

  let set_pipeline (value : t) (pipeline : Render_pipeline.t) =
    let operation = "Metal.Render_encoder.set_pipeline" in
    on_main operation (fun () ->
      match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () ->
          (match ensure_live operation pipeline.lifetime with
           | Error _ as failure -> failure
           | Ok () ->
               (match
                  ensure_same_device operation value.command_buffer.queue.device
                    pipeline.device
                with
                | Error _ as failure -> failure
                | Ok () when pipeline.kind <> Render ->
                    error operation Invalid_argument
                      "classic render encoder requires a render pipeline"
                | Ok () when pipeline.raster_sample_count <> 1 ->
                    error operation Invalid_argument
                      "pipeline sample count differs from the render target"
                | Ok () when
                    pipeline.color_formats = []
                    || List.hd pipeline.color_formats
                       <> value.target.descriptor.format ->
                    error operation Invalid_argument
                      "pipeline color format differs from the render target"
                | Ok () ->
                    (match
                       Metal_raw.render_encoder_set_pipeline value.raw pipeline.raw
                     with
                     | Error message -> native_error operation message
                     | Ok () ->
                         value.pipeline <- Some pipeline;
                         retain_command_buffer_render_pipeline
                           value.command_buffer pipeline;
                         Ok ()))))

  let set_buffer operation raw_call (value : t) ~index ~offset
      (buffer : Buffer.t) =
    on_main operation (fun () ->
      match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () ->
          (match ensure_buffer_usable operation buffer with
           | Error _ as failure -> failure
           | Ok () when index < 0 || index >= 31 ->
               error operation Invalid_argument "buffer index must be in [0, 31)"
           | Ok () when offset < 0L || offset > buffer.length ->
               error operation Invalid_argument "buffer offset is outside the resource"
           | Ok () ->
               (match
                  ensure_same_device operation value.command_buffer.queue.device
                    buffer.device
                with
                | Error _ as failure -> failure
                | Ok () ->
                    (match raw_call value.raw buffer.raw offset index with
                     | Error message -> native_error operation message
                     | Ok () ->
                         retain_command_buffer_buffer value.command_buffer buffer;
                         Ok ()))))

  let set_vertex_buffer =
    set_buffer "Metal.Render_encoder.set_vertex_buffer"
      Metal_raw.render_encoder_set_vertex_buffer

  let set_fragment_buffer =
    set_buffer "Metal.Render_encoder.set_fragment_buffer"
      Metal_raw.render_encoder_set_fragment_buffer

  let set_texture operation raw_call (value : t) ~index (texture : Texture.t) =
    on_main operation (fun () ->
      match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () ->
          (match ensure_texture_usable operation texture with
           | Error _ as failure -> failure
           | Ok () when index < 0 || index >= 31 ->
               error operation Invalid_argument "texture index must be in [0, 31)"
           | Ok () ->
               (match ensure_same_device operation value.command_buffer.queue.device
                        texture.device with
                | Error _ as failure -> failure
                | Ok () ->
                    (match raw_call value.raw texture.raw index with
                     | Error message -> native_error operation message
                     | Ok () ->
                         retain_command_buffer_texture value.command_buffer texture;
                         Ok ()))))

  let set_vertex_texture =
    set_texture "Metal.Render_encoder.set_vertex_texture"
      Metal_raw.render_encoder_set_vertex_texture

  let set_fragment_texture =
    set_texture "Metal.Render_encoder.set_fragment_texture"
      Metal_raw.render_encoder_set_fragment_texture

  let set_bytes operation raw_call (value : t) ~index bytes =
    on_main operation (fun () ->
      match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () when index < 0 || index >= 31 ->
          error operation Invalid_argument "byte index must be in [0, 31)"
      | Ok () when Bytes.length bytes = 0 || Bytes.length bytes > 4096 ->
          error operation Invalid_argument "inline bytes must contain 1..4096 bytes"
      | Ok () ->
          (match raw_call value.raw bytes index with
           | Ok () -> Ok () | Error message -> native_error operation message))

  let set_vertex_bytes =
    set_bytes "Metal.Render_encoder.set_vertex_bytes"
      Metal_raw.render_encoder_set_vertex_bytes
  let set_fragment_bytes =
    set_bytes "Metal.Render_encoder.set_fragment_bytes"
      Metal_raw.render_encoder_set_fragment_bytes

  let set_sampler operation raw_call (value : t) ~index ?lod_min ?lod_max
      (sampler : Sampler.t) =
    on_main operation (fun () ->
      match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () ->
          (match ensure_live operation sampler.lifetime with
           | Error _ as failure -> failure
           | Ok () when index < 0 || index >= 31 ->
               error operation Invalid_argument "sampler index must be in [0, 31)"
           | Ok () when
               (match lod_min, lod_max with
                | None, None -> false
                | Some lo, Some hi ->
                    not (Float.is_finite lo && Float.is_finite hi
                         && lo >= 0. && lo <= hi)
                | _ -> true) ->
               error operation Invalid_argument
                 "LOD clamps must be finite, nonnegative, ordered, and supplied together"
           | Ok () ->
               (match ensure_same_device operation value.command_buffer.queue.device sampler.device with
                | Error _ as failure -> failure
                | Ok () ->
                    let result = match lod_min, lod_max with
                      | None, None -> raw_call `Plain value.raw sampler.raw index
                      | Some lo, Some hi ->
                          raw_call (`Lod (lo, hi)) value.raw sampler.raw index
                      | _ -> assert false
                    in
                    (match result with
                     | Error message -> native_error operation message
                     | Ok () -> retain_command_buffer_sampler value.command_buffer sampler; Ok ()))))

  let sampler_call plain lod = function
    | `Plain -> plain | `Lod clamps -> fun encoder sampler index -> lod encoder sampler clamps index

  let set_vertex_sampler =
    set_sampler "Metal.Render_encoder.set_vertex_sampler"
      (sampler_call Metal_raw.render_encoder_set_vertex_sampler
         Metal_raw.render_encoder_set_vertex_sampler_lod)
  let set_fragment_sampler =
    set_sampler "Metal.Render_encoder.set_fragment_sampler"
      (sampler_call Metal_raw.render_encoder_set_fragment_sampler
         Metal_raw.render_encoder_set_fragment_sampler_lod)

  let set_validated operation validate raw_call (value : t) argument =
    on_main operation (fun () ->
      match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () ->
          (match validate value argument with
           | Error _ as failure -> failure
           | Ok raw_argument ->
               (match raw_call value.raw raw_argument with
                | Ok () -> Ok ()
                | Error message -> native_error operation message)))

  let set_viewport =
    set_validated "Metal.Render_encoder.set_viewport"
      (fun value (viewport : viewport) ->
        let values =
          [ viewport.x; viewport.y; viewport.width; viewport.height
          ; viewport.znear; viewport.zfar ]
        in
        if not (List.for_all Float.is_finite values) then
          error "Metal.Render_encoder.set_viewport" Invalid_argument
            "viewport values must be finite"
        else if viewport.x < 0. || viewport.y < 0. || viewport.width <= 0.
             || viewport.height <= 0.
             || viewport.x +. viewport.width > float value.target.descriptor.width
             || viewport.y +. viewport.height > float value.target.descriptor.height
             || viewport.znear < 0. || viewport.znear > 1.
             || viewport.zfar < 0. || viewport.zfar > 1.
             || viewport.znear > viewport.zfar then
          error "Metal.Render_encoder.set_viewport" Invalid_argument
            "viewport is outside the render target or depth range"
        else Ok (viewport.x, viewport.y, viewport.width, viewport.height,
                 viewport.znear, viewport.zfar))
      Metal_raw.render_encoder_set_viewport

  let set_scissor =
    set_validated "Metal.Render_encoder.set_scissor"
      (fun value (scissor : scissor) ->
        if scissor.x < 0 || scissor.y < 0 || scissor.width <= 0
           || scissor.height <= 0
           || scissor.x > value.target.descriptor.width - scissor.width
           || scissor.y > value.target.descriptor.height - scissor.height then
          error "Metal.Render_encoder.set_scissor" Invalid_argument
            "scissor rectangle is outside the render target"
        else Ok (scissor.x, scissor.y, scissor.width, scissor.height))
      Metal_raw.render_encoder_set_scissor

  let set_cull_mode =
    set_validated "Metal.Render_encoder.set_cull_mode"
      (fun _ mode -> Ok (match mode with No_cull -> 0 | Cull_front -> 1 | Cull_back -> 2))
      Metal_raw.render_encoder_set_cull_mode

  let set_front_facing_winding =
    set_validated "Metal.Render_encoder.set_front_facing_winding"
      (fun _ winding -> Ok (match winding with Clockwise -> 0 | Counter_clockwise -> 1))
      Metal_raw.render_encoder_set_winding

  let set_triangle_fill_mode =
    set_validated "Metal.Render_encoder.set_triangle_fill_mode"
      (fun _ mode -> Ok (match mode with Fill -> 0 | Lines -> 1))
      Metal_raw.render_encoder_set_fill_mode

  let finite_floats operation values =
    if List.for_all Float.is_finite values then Ok values
    else error operation Invalid_argument "values must be finite"

  let set_blend_color value ~red ~green ~blue ~alpha =
    set_validated "Metal.Render_encoder.set_blend_color"
      (fun _ _ ->
        match finite_floats "Metal.Render_encoder.set_blend_color"
                [ red; green; blue; alpha ] with
        | Error _ as failure -> failure
        | Ok _ -> Ok (red, green, blue, alpha))
      Metal_raw.render_encoder_set_blend_color value ()

  let set_depth_bias value ~bias ~slope_scale ~clamp =
    set_validated "Metal.Render_encoder.set_depth_bias"
      (fun _ _ ->
        match finite_floats "Metal.Render_encoder.set_depth_bias"
                [ bias; slope_scale; clamp ] with
        | Error _ as failure -> failure
        | Ok _ -> Ok (bias, slope_scale, clamp))
      Metal_raw.render_encoder_set_depth_bias value ()

  let set_stencil_reference_values (value : t) ~front ~back =
    on_main "Metal.Render_encoder.set_stencil_reference_values" (fun () ->
      match ensure_live "Metal.Render_encoder.set_stencil_reference_values" value.lifetime with
      | Error _ as failure -> failure
      | Ok () ->
          (match Metal_raw.render_encoder_set_stencil_reference value.raw front back with
           | Ok () -> Ok ()
           | Error message -> native_error "Metal.Render_encoder.set_stencil_reference_values" message))

  let set_stencil_reference_value (value : t) reference =
    set_stencil_reference_values value ~front:reference ~back:reference

  let set_visibility_result (value : t) ~mode ~offset =
    on_main "Metal.Render_encoder.set_visibility_result" (fun () ->
      match ensure_live "Metal.Render_encoder.set_visibility_result" value.lifetime with
      | Error _ as failure -> failure
      | Ok () when offset < 0L || Int64.rem offset 8L <> 0L ->
          error "Metal.Render_encoder.set_visibility_result" Invalid_argument
            "visibility offset must be nonnegative and 8-byte aligned"
      | Ok () ->
          let raw_mode = match mode with
            | Visibility_disabled -> 0 | Visibility_boolean -> 1
            | Visibility_counting -> 2
          in
          (match Metal_raw.render_encoder_set_visibility value.raw raw_mode offset with
           | Ok () -> Ok ()
           | Error message -> native_error "Metal.Render_encoder.set_visibility_result" message))

  let tile_width (value : t) =
    on_main "Metal.Render_encoder.tile_width" (fun () ->
      match ensure_live "Metal.Render_encoder.tile_width" value.lifetime with
      | Error _ as failure -> failure
      | Ok () -> Ok (Metal_raw.render_encoder_tile_width value.raw))

  let tile_height (value : t) =
    on_main "Metal.Render_encoder.tile_height" (fun () ->
      match ensure_live "Metal.Render_encoder.tile_height" value.lifetime with
      | Error _ as failure -> failure
      | Ok () -> Ok (Metal_raw.render_encoder_tile_height value.raw))

  let set_color_store_action (value : t) ?(attachment = 0) action =
    let operation = "Metal.Render_encoder.set_color_store_action" in
    on_main operation (fun () -> match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () when attachment <> 0 ->
          error operation Invalid_argument "classic render pass has only color attachment zero"
      | Ok () ->
          let code = match action with Store_dont_care->0 | Store->1
            | Multisample_resolve->2 | Store_and_multisample_resolve->3 in
          if code >= 2 && value.target.descriptor.sample_count = 1 then
            error operation Invalid_argument "resolve store actions require multisampling"
          else match Metal_raw.render_encoder_set_color_store_action value.raw code attachment with
            | Ok () -> Ok () | Error message -> native_error operation message)

  let set_color_store_options (value : t) ?(attachment = 0) ~custom_sample_positions () =
    let operation = "Metal.Render_encoder.set_color_store_options" in
    on_main operation (fun () -> match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () when attachment <> 0 ->
          error operation Invalid_argument "classic render pass has only color attachment zero"
      | Ok () ->
          match Metal_raw.render_encoder_set_color_store_options value.raw
                  (if custom_sample_positions then 1 else 0) attachment with
          | Ok () -> Ok () | Error message -> native_error operation message)

  let bits code values = List.fold_left (fun mask value -> mask lor code value) 0 values
  let stage_code = function Vertex->1 | Fragment->2 | Tile->4 | Object->8 | Mesh->16
  let scope_code = function Buffers->1 | Textures->2 | Render_targets->4
  let usage_code = function Read->1 | Write->2 | Sample->4
  let validate_nonempty operation what values =
    if values=[] then error operation Invalid_argument (what ^ " must be nonempty") else Ok ()
  let validate_resource operation device = function
    | Buffer_resource b ->
        Result.bind (ensure_buffer_usable operation b) (fun () -> ensure_same_device operation device b.device)
    | Texture_resource t ->
        Result.bind (ensure_texture_usable operation t) (fun () -> ensure_same_device operation device t.device)
  let resource_raw = function Buffer_resource b -> b.raw | Texture_resource t -> t.raw
  let resource_lifetime = function Buffer_resource b -> b.lifetime | Texture_resource t -> t.lifetime
  let has_duplicate_lifetimes lifetimes =
    let rec loop seen = function
      | [] -> false
      | value :: rest ->
          List.exists (fun current -> current == value) seen || loop (value :: seen) rest
    in
    loop [] lifetimes
  let retain_resource command_buffer = function
    | Buffer_resource b -> retain_command_buffer_buffer command_buffer b
    | Texture_resource t -> retain_command_buffer_texture command_buffer t

  let memory_barrier (value : t) ~scope ~after ~before =
    let operation="Metal.Render_encoder.memory_barrier" in on_main operation (fun()->
      match ensure_live operation value.lifetime with Error _ as e->e | Ok()->
      Result.bind(validate_nonempty operation "barrier scope" scope)(fun()->
      Result.bind(validate_nonempty operation "after stages" after)(fun()->
      Result.bind(validate_nonempty operation "before stages" before)(fun()->
      match Metal_raw.render_encoder_memory_barrier_scope value.raw (bits scope_code scope) (bits stage_code after) (bits stage_code before) with Error m->native_error operation m|Ok()->Ok()))))

  let memory_barrier_resources (value : t) resources ~after ~before =
    let operation="Metal.Render_encoder.memory_barrier_resources" in on_main operation (fun()->
      match ensure_live operation value.lifetime with Error _ as e->e | Ok()->
      Result.bind(validate_nonempty operation "resources" resources)(fun()->
