                      && valid_axis dx source_region.width
                        (tile_limit destination_descriptor.width destination_level destination_info.tile_width)
                      && valid_axis dy source_region.height
                        (tile_limit destination_descriptor.height destination_level destination_info.tile_height)
                      && valid_axis dz source_region.depth
                        (tile_limit destination_descriptor.depth destination_level destination_info.tile_depth)
                    in
                    if not valid then error operation Invalid_argument
                        "mapping move exceeds a sparse mip extent"
                    else
                      let origin = Int64.of_int source_region.x,
                        Int64.of_int source_region.y, Int64.of_int source_region.z
                      and size = Int64.of_int source_region.width,
                        Int64.of_int source_region.height, Int64.of_int source_region.depth
                      and destination_origin =
                        Int64.of_int dx, Int64.of_int dy, Int64.of_int dz in
                      match Metal_raw.resource_encoder_move_texture value.raw source.raw
                        (Int64.of_int source_slice) (Int64.of_int source_level)
                        origin size destination.raw (Int64.of_int destination_slice)
                        (Int64.of_int destination_level) destination_origin with
                      | Error message -> native_error operation message
                      | Ok () ->
                          retain_command_buffer_texture value.command_buffer source;
                          retain_command_buffer_texture value.command_buffer destination;
                          Ok ()))))))))

  let end_encoding (value : t) =
    on_main "Metal.Resource_state_encoder.end_encoding" (fun () ->
      match ensure_live "Metal.Resource_state_encoder.end_encoding" value.lifetime with
      | Error _ as failure -> failure
      | Ok () ->
          (match Metal_raw.resource_state_encoder_end value.raw with
           | Error message ->
               native_error "Metal.Resource_state_encoder.end_encoding" message
           | Ok () ->
               if Atomic.compare_and_set value.lifetime.destroyed false true
               then begin
                 ignore (Metal_raw.destroy value.raw);
                 detach value.command_buffer.lifetime
               end;
               Ok ()))
end

module Placement_mapping = struct
  type queue = placement_mapping_queue
  type t = placement_mapping

  type tile_range =
    { offset : int
    ; length : int
    }

  type kind =
    | Buffer
    | Texture

  let ( let* ) value callback = Result.bind value callback
  let operation_prefix name = "Metal.Placement_mapping." ^ name

  let require operation kind condition message =
    if condition then Ok () else error operation kind message

  let create_queue ?label (device : Device.t) =
    let operation = operation_prefix "create_queue" in
    on_main operation (fun () ->
      let* () = ensure_live operation device.lifetime in
      let* () =
        require operation Invalid_argument
          (not (option_exists contains_nul label))
          "queue label contains a NUL byte"
      in
      let* () =
        require operation Unsupported
          (Metal_raw.device_supports_placement_sparse device.raw)
          "device does not support Metal 4 placement mappings"
      in
      match Metal_raw.placement_mapping_queue_create device.raw label with
      | Error message -> native_error operation message
      | Ok raw ->
          let value : queue =
            { raw; lifetime = lifetime (); device; mappings = ref [] }
          in
          attach device.lifetime;
          attach_finalizer value value.lifetime device.lifetime;
          Ok value)

  let queue_device (value : queue) = value.device
  let queue_generation (value : queue) = Metal_raw.generation value.raw
  let queue_destroyed (value : queue) = is_destroyed value.lifetime

  let queue_label (value : queue) =
    let operation = operation_prefix "queue_label" in
    on_main operation (fun () ->
      let* () = ensure_live operation value.lifetime in
      Ok (Metal_raw.placement_mapping_queue_label value.raw))

  let destroy_queue (value : queue) =
    destroy_parent (operation_prefix "destroy_queue") value.lifetime value.raw
      (fun () -> detach value.device.lifetime)

  let kind (value : t) =
    match value.target with
    | Placement_buffer_mapping _ -> Buffer
    | Placement_texture_mapping _ -> Texture

  let heap (value : t) = value.heap
  let page_size (value : t) = value.page_size
  let heap_offset (value : t) = value.heap_offset
  let mapped_bytes (value : t) = value.mapped_bytes
  let destroyed (value : t) = not (Atomic.get value.active)

  let active_mappings (mappings : placement_mapping list ref) =
    let active =
      List.filter
        (fun (mapping : placement_mapping) -> Atomic.get mapping.active)
        !mappings
    in
    mappings := active;
    active

  let ensure_only_mapping_dependents operation lifetime
      (mappings : placement_mapping list ref) =
    let active = active_mappings mappings in
    let* () =
      require operation Parent_has_dependents
        (dependent_count lifetime = List.length active)
        "resource has a live view, CPU mapping, or command dependency"
    in
    Ok active

  let page_compatible maximum requested =
    Sparse_page_size.bytes maximum >= Sparse_page_size.bytes requested

  let validate_heap operation (queue : queue) (heap : Heap.t) ~storage
      ~cpu_cache page_size =
    let* () = ensure_live operation heap.lifetime in
    let* () = ensure_same_device operation queue.device heap.device in
    let* () =
      require operation Invalid_argument
        (heap.descriptor.kind = Placement)
        "placement sparse mappings require a placement heap"
    in
    let* () =
      require operation Invalid_state
        (Atomic.get heap.purgeable = Nonvolatile)
        "placement heap must be nonvolatile before mapping"
    in
    let* () =
      require operation Invalid_argument
        (heap.descriptor.storage = storage
         && heap.descriptor.cpu_cache = cpu_cache)
        "placement heap storage and cache modes must match the resource"
    in
    match heap.descriptor.sparse_page_size with
    | None ->
        error operation Invalid_argument
          "placement heap has no sparse-page compatibility"
    | Some maximum when not (page_compatible maximum page_size) ->
        error operation Invalid_argument
          "placement heap sparse pages are smaller than the resource pages"
    | Some _ -> Ok ()

  let prepare_mapping (value : t)
      (resource_mappings : placement_mapping list ref) =
    let queue = value.queue and heap = value.heap in
    let queue_entries = value :: !(queue.mappings)
    and resource_entries = value :: !resource_mappings
    and allocations = value.allocation :: !(heap.allocations) in
    resource_mappings, queue_entries, resource_entries, allocations

  let register_mapping (value : t)
      (resource_mappings, queue_entries, resource_entries, allocations) =
    let queue = value.queue and heap = value.heap in
    attach queue.lifetime;
    attach heap.lifetime;
    Atomic.incr heap.active_uses;
    (match value.target with
     | Placement_buffer_mapping target -> attach target.buffer.lifetime
     | Placement_texture_mapping target -> attach target.texture.lifetime);
    queue.mappings := queue_entries;
    resource_mappings := resource_entries;
    heap.allocations := allocations

  let validate_physical_span operation (heap : Heap.t) ~page_bytes
      ~physical_tiles ~heap_offset =
    let* () =
      require operation Invalid_argument
        (heap_offset >= 0L && Int64.rem heap_offset page_bytes = 0L)
        "heap offset must be aligned to the resource page size"
    in
    let* () =
      require operation Invalid_argument
        (physical_tiles <= Int64.div Int64.max_int page_bytes)
        "mapped byte cardinality overflows int64"
    in
    let mapped_bytes = Int64.mul physical_tiles page_bytes in
    let required : Heap.size_and_align =
      { size = mapped_bytes; alignment = page_bytes }
    in
    let* () =
      Heap.validate_placement operation heap (Some heap_offset) required
    in
    Ok mapped_bytes

  let make_mapping queue heap target page_size heap_offset mapped_bytes =
    let allocation : heap_allocation =
      { offset = heap_offset; size = mapped_bytes; active = Atomic.make true }
    in
    ({ queue
     ; heap
     ; allocation
     ; target
     ; page_size
     ; heap_offset
     ; mapped_bytes
     ; active = Atomic.make true
     }
      : t)

  let interval_overlaps left_offset left_length right_offset right_length =
    left_offset < Int64.add right_offset right_length
    && right_offset < Int64.add left_offset left_length

  let buffer_range_overlaps tile_offset tile_count (mapping : t) =
    match mapping.target with
    | Placement_buffer_mapping target ->
        interval_overlaps tile_offset tile_count target.tile_offset
          target.tile_count
    | Placement_texture_mapping _ -> false

  let map_buffer (queue : queue) ~(heap : Heap.t) ~heap_offset
      (buffer : Buffer.t) ~(range : tile_range) =
    let operation = operation_prefix "map_buffer" in
    on_main operation (fun () ->
      let* () = ensure_live operation queue.lifetime in
      let* () = ensure_buffer_usable operation buffer in
      let* () = ensure_same_device operation queue.device buffer.device in
      let* page_size =
        match buffer.placement_sparse_page_size with
        | Some page_size -> Ok page_size
        | None ->
            error operation Invalid_argument "buffer is not placement sparse"
      in
      let* () =
        validate_heap operation queue heap ~storage:buffer.storage
          ~cpu_cache:buffer.cpu_cache page_size
      in
      let* active =
        ensure_only_mapping_dependents operation buffer.lifetime
          buffer.placement_mappings
      in
      let* () =
        require operation Invalid_argument
          (range.offset >= 0 && range.length > 0)
          "buffer tile range must be positive"
      in
      let page_bytes = Sparse_page_size.bytes page_size in
      let tile_offset = Int64.of_int range.offset
      and tile_count = Int64.of_int range.length in
      let whole_tiles = Int64.div buffer.length page_bytes in
      let virtual_tiles =
        if Int64.rem buffer.length page_bytes = 0L then whole_tiles
        else Int64.succ whole_tiles
      in
      let* () =
        require operation Invalid_argument
          (tile_offset <= virtual_tiles
           && tile_count <= Int64.sub virtual_tiles tile_offset)
          "buffer tile range exceeds the virtual resource"
      in
      let* () =
        require operation Invalid_state
          (not (List.exists (buffer_range_overlaps tile_offset tile_count) active))
          "buffer tile range overlaps a live mapping"
      in
      let* mapped_bytes =
        validate_physical_span operation heap ~page_bytes
          ~physical_tiles:tile_count ~heap_offset
      in
      let target =
        Placement_buffer_mapping { buffer; tile_offset; tile_count }
      in
      let value =
        make_mapping queue heap target page_size heap_offset mapped_bytes
      in
      let registration = prepare_mapping value buffer.placement_mappings in
      let raw_heap_offset = Int64.div heap_offset page_bytes in
      match
        Metal_raw.placement_mapping_update_buffer queue.raw buffer.raw
          (Some heap.raw) 0
          ( tile_offset
          , tile_count
          , raw_heap_offset
          , sparse_page_size_code page_size )
      with
      | Error message -> native_error operation message
      | Ok () ->
          register_mapping value registration;
          Ok value)

  let texture_regions_overlap left right =
    let lx, ly, lz, lw, lh, ld = left
    and rx, ry, rz, rw, rh, rd = right in
    lx < rx + rw && rx < lx + lw
    && ly < ry + rh && ry < ly + lh
    && lz < rz + rd && rz < lz + ld

  let texture_region_overlaps raw_region mip_level slice (mapping : t) =
    match mapping.target with
    | Placement_texture_mapping target ->
        target.mip_level = mip_level && target.slice = slice
        && texture_regions_overlap raw_region target.region
    | Placement_buffer_mapping _ -> false

  let validate_texture_parent operation (texture : Texture.t) =
    match texture.parent with
    | Texture_resource (Device_resource _) -> Ok ()
    | Texture_view _ ->
        error operation Invalid_argument
          "map the base placement sparse texture, not a view"
    | Texture_buffer_resource _ | Texture_io_surface_resource _
    | Texture_drawable_resource _
    | Texture_resource (Heap_resource _ | External_resource _) ->
        error operation Invalid_argument
          "texture is not a device-owned placement sparse resource"

  let validate_texture_region operation (texture : Texture.t) ~mip_level
      ~slice (region : Resource_state_encoder.tile_region) =
    let* info =
      match Texture.sparse_info_raw operation texture with
      | Ok (Some info) -> Ok info
      | Ok None -> error operation Invalid_argument "texture is not sparse"
      | Error _ as failure -> failure
    in
    let descriptor = texture.descriptor in
    let* () =
      require operation Invalid_argument
        (mip_level >= 0 && mip_level < descriptor.mip_levels)
        "mapping mip level is outside the texture"
    in
    let* () =
      require operation Invalid_argument
        (slice >= 0 && slice < Texture.total_slices descriptor)
        "mapping slice is outside the texture"
    in
    let mip_width = Texture.mip_dimension descriptor.width mip_level
    and mip_height = Texture.mip_dimension descriptor.height mip_level
    and mip_depth = Texture.mip_dimension descriptor.depth mip_level in
    let tile_width =
      Resource_state_encoder.ceil_div mip_width info.tile_width
    and tile_height =
      Resource_state_encoder.ceil_div mip_height info.tile_height
    and tile_depth =
      Resource_state_encoder.ceil_div mip_depth info.tile_depth
    in
    let* () =
      require operation Invalid_argument
        (Resource_state_encoder.valid_axis region.x region.width tile_width
         && Resource_state_encoder.valid_axis region.y region.height tile_height
         && Resource_state_encoder.valid_axis region.z region.depth tile_depth)
        "texture tile region exceeds the selected mip level"
    in
    let tail = info.first_mip_in_tail = Some mip_level in
    let* () =
      match info.first_mip_in_tail with
      | Some first when mip_level > first ->
          error operation Invalid_argument
            "map a placement sparse mip tail through its first mip level"
      | Some _ when tail
                    && region <>
                       { x = 0; y = 0; z = 0; width = 1; height = 1
                       ; depth = 1
                       } ->
          error operation Invalid_argument
            "a placement sparse mip-tail mapping must cover its single tail tile"
      | None | Some _ -> Ok ()
    in
    let* tile_count =
      Resource_state_encoder.tile_cardinality operation region
    in
    let page_bytes = info.tile_size_in_bytes in
    let physical_tiles =
      if tail then
        let bytes = info.tail_size_in_bytes in
        if bytes = 0L then 0L
        else Int64.succ (Int64.div (Int64.pred bytes) page_bytes)
      else Int64.of_int tile_count
    in
    let* () =
      if physical_tiles > 0L then Ok ()
      else
        native_error operation
          "Metal returned an empty placement sparse mapping"
    in
    Ok (Resource_state_encoder.region_tuple region, page_bytes, physical_tiles)

  let map_texture (queue : queue) ~(heap : Heap.t) ~heap_offset
      (texture : Texture.t) ~mip_level ~slice
      ~(region : Resource_state_encoder.tile_region) =
    let operation = operation_prefix "map_texture" in
    on_main operation (fun () ->
      let* () = ensure_live operation queue.lifetime in
      let* () = ensure_texture_usable operation texture in
      let* () = ensure_same_device operation queue.device texture.device in
      let* () = validate_texture_parent operation texture in
      let* page_size =
        match texture.placement_sparse_page_size with
        | Some page_size -> Ok page_size
        | None ->
            error operation Invalid_argument "texture is not placement sparse"
      in
      let* () =
        validate_heap operation queue heap ~storage:texture.descriptor.storage
          ~cpu_cache:texture.descriptor.cpu_cache page_size
      in
      let* active =
        ensure_only_mapping_dependents operation texture.lifetime
          texture.placement_mappings
      in
      let* raw_region, page_bytes, physical_tiles =
        validate_texture_region operation texture ~mip_level ~slice region
      in
      let* () =
        require operation Invalid_state
          (not
             (List.exists
                (texture_region_overlaps raw_region mip_level slice)
                active))
          "texture tile region overlaps a live mapping"
      in
      let* mapped_bytes =
        validate_physical_span operation heap ~page_bytes ~physical_tiles
          ~heap_offset
      in
      let target =
        Placement_texture_mapping { texture; region = raw_region; mip_level; slice }
      in
      let value =
        make_mapping queue heap target page_size heap_offset mapped_bytes
      in
      let registration = prepare_mapping value texture.placement_mappings in
      let raw_heap_offset = Int64.div heap_offset page_bytes in
      match
        Metal_raw.placement_mapping_update_texture queue.raw texture.raw
          (Some heap.raw)
          ( 0
          , raw_region
          , mip_level
          , slice
          , raw_heap_offset
          , sparse_page_size_code page_size )
      with
      | Error message -> native_error operation message
      | Ok () ->
          register_mapping value registration;
          Ok value)

  let remove_mapping (value : t)
      (resource_mappings : placement_mapping list ref) =
    let keep (retained : placement_mapping) =
      retained != value && Atomic.get retained.active
    in
    value.queue.mappings := List.filter keep !(value.queue.mappings);
    resource_mappings := List.filter keep !resource_mappings;
    Atomic.set value.active false;
    Atomic.set value.allocation.active false;
    Atomic.decr value.heap.active_uses;
    (match value.target with
     | Placement_buffer_mapping target -> detach target.buffer.lifetime
     | Placement_texture_mapping target -> detach target.texture.lifetime);
    detach value.heap.lifetime;
    detach value.queue.lifetime

  let unmap_buffer operation (value : t) (buffer : buffer) ~tile_offset
      ~tile_count =
    let* () = ensure_live operation buffer.lifetime in
    let* _ =
      ensure_only_mapping_dependents operation buffer.lifetime
        buffer.placement_mappings
    in
    match
      Metal_raw.placement_mapping_update_buffer value.queue.raw buffer.raw None 1
        ( tile_offset
        , tile_count
        , 0L
        , sparse_page_size_code value.page_size )
    with
    | Error message -> native_error operation message
    | Ok () ->
        remove_mapping value buffer.placement_mappings;
        Ok ()

  let unmap_texture operation (value : t) (texture : texture) ~region
      ~mip_level ~slice =
    let* () = ensure_live operation texture.lifetime in
    let* _ =
      ensure_only_mapping_dependents operation texture.lifetime
        texture.placement_mappings
    in
    match
      Metal_raw.placement_mapping_update_texture value.queue.raw
        texture.raw None
        ( 1
        , region
        , mip_level
        , slice
        , 0L
        , sparse_page_size_code value.page_size )
    with
    | Error message -> native_error operation message
    | Ok () ->
        remove_mapping value texture.placement_mappings;
        Ok ()

  let unmap (value : t) =
    let operation = operation_prefix "unmap" in
    on_main operation (fun () ->
      if not (Atomic.get value.active) then Ok ()
      else
        let* () = ensure_live operation value.queue.lifetime in
        let* () = ensure_live operation value.heap.lifetime in
        match value.target with
        | Placement_buffer_mapping target ->
            unmap_buffer operation value target.buffer
              ~tile_offset:target.tile_offset ~tile_count:target.tile_count
        | Placement_texture_mapping target ->
            unmap_texture operation value target.texture ~region:target.region
              ~mip_level:target.mip_level ~slice:target.slice)
end

module Blit_encoder = struct
  type t = blit_encoder

  let create (command_buffer : Command_buffer.t) =
    on_main "Metal.Blit_encoder.create" (fun () ->
      match ensure_live "Metal.Blit_encoder.create" command_buffer.lifetime with
      | Error _ as failure -> failure
      | Ok () when command_buffer.phase <> Recording ->
          error "Metal.Blit_encoder.create" Invalid_state
            "command buffer is no longer recording"
      | Ok () when dependent_count command_buffer.lifetime <> 0 ->
          error "Metal.Blit_encoder.create" Invalid_state
            "command buffer already has an open encoder"
      | Ok () ->
          (match Metal_raw.command_buffer_blit_encoder command_buffer.raw with
           | Error message -> native_error "Metal.Blit_encoder.create" message
           | Ok raw ->
               let value : t =
                 { raw; lifetime = lifetime (); command_buffer }
               in
               attach command_buffer.lifetime;
               attach_finalizer value value.lifetime command_buffer.lifetime;
               Ok value))

  let destroyed (value : t) = is_destroyed value.lifetime

  let copy_buffer_to_texture (value : t) ~(source : Buffer.t) ~source_offset
      ~source_bytes_per_row ~source_bytes_per_image ~(destination : Texture.t)
      ~destination_slice ~destination_level
      ~(destination_region : Texture.region) =
    let operation = "Metal.Blit_encoder.copy_buffer_to_texture" in
    on_main operation (fun () ->
      match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () ->
          (match ensure_buffer_usable operation source with
           | Error _ as failure -> failure
           | Ok () ->
               (match ensure_texture_usable operation destination with
                | Error _ as failure -> failure
                | Ok () ->
                    let descriptor = destination.descriptor in
                    if source_offset < 0L
                       || source_bytes_per_row <= 0
                       || source_bytes_per_image <= 0
                    then
                      error operation Invalid_argument
                        "blit source offset and pitches must be nonnegative and positive"
                    else if descriptor.sample_count <> 1 then
                      error operation Unsupported
                        "multisample textures do not accept buffer blits"
                    else if destination_level < 0
                            || destination_level >= descriptor.mip_levels
                    then
                      error operation Invalid_argument
                        "blit destination mip level is outside the texture"
                    else if destination_slice < 0
                            || destination_slice >=
                               Texture.total_slices descriptor
                    then
                      error operation Invalid_argument
                        "blit destination slice is outside the texture"
                    else if destination_region.x < 0
                            || destination_region.y < 0
                            || destination_region.z < 0
                            || destination_region.width <= 0
                            || destination_region.height <= 0
                            || destination_region.depth <= 0
                    then
                      error operation Invalid_argument
                        "blit destination region is invalid"
                    else
                      let mip_width =
                        Texture.mip_dimension descriptor.width destination_level
                      and mip_height =
                        Texture.mip_dimension descriptor.height destination_level
                      and mip_depth =
                        Texture.mip_dimension descriptor.depth destination_level
                      in
                      if destination_region.x > mip_width
                         || destination_region.width
                            > mip_width - destination_region.x
                         || destination_region.y > mip_height
                         || destination_region.height
                            > mip_height - destination_region.y
                         || destination_region.z > mip_depth
                         || destination_region.depth
                            > mip_depth - destination_region.z
                      then
                        error operation Invalid_argument
                          "blit destination region exceeds the selected mip level"
                      else
                        let layout =
                          Texture.format_layout descriptor.format
                        in
                        let aligned origin length limit block =
                          origin mod block = 0
                          && (length mod block = 0
                              || origin + length = limit)
                        in
                        if
                          not
                            (aligned destination_region.x
                               destination_region.width mip_width
                               layout.block_width
                             && aligned destination_region.y
                                  destination_region.height mip_height
                                  layout.block_height)
                        then
                          error operation Invalid_argument
                            "blit destination region is not format-block aligned"
                        else
                        let blocks value block = 1 + ((value - 1) / block) in
                        let row_blocks =
                          blocks destination_region.width layout.block_width
                        in
                        (match
                           Texture.checked_mul row_blocks
                             layout.bytes_per_block
                         with
                         | None ->
                             error operation Invalid_argument
                               "blit row cardinality overflows an OCaml integer"
                         | Some minimum_row
                           when source_bytes_per_row < minimum_row
                                || source_bytes_per_row
                                   mod layout.bytes_per_block <> 0 ->
                             error operation Invalid_argument
                               "blit source row pitch is too small or not block-aligned"
                         | Some _ ->
                             (match
                                Texture.checked_mul source_bytes_per_row
                                  (blocks destination_region.height
                                     layout.block_height)
                              with
                              | None ->
                                  error operation Invalid_argument
                                    "blit image cardinality overflows an OCaml integer"
                              | Some minimum_image
                                when source_bytes_per_image < minimum_image ->
                                  error operation Invalid_argument
                                    "blit source image pitch is smaller than its rows"
                              | Some _ ->
                                  let image_bytes =
                                    Int64.of_int source_bytes_per_image
                                  and depth =
                                    Int64.of_int destination_region.depth
                                  in
                                  if image_bytes > Int64.div Int64.max_int depth
                                  then
                                    error operation Invalid_argument
                                      "blit source cardinality overflows 64 bits"
                                  else
                                    let total = Int64.mul image_bytes depth in
                                    if source_offset > source.length
                                       || total
                                          > Int64.sub source.length source_offset
                                    then
                                      error operation Invalid_argument
                                        "blit source range exceeds the buffer"
                                    else (match
                                       ensure_same_device operation
                                         value.command_buffer.queue.device
                                         source.device
                                     with
                                     | Error _ as failure -> failure
                                     | Ok () ->
                                         (match
                                            ensure_same_device operation
                                              value.command_buffer.queue.device
                                              destination.device
                                          with
                                          | Error _ as failure -> failure
                                          | Ok () ->
                                              let copy =
                                                ( source_offset
                                                , source_bytes_per_row
                                                , source_bytes_per_image
                                                , (destination_region.width,
                                                   destination_region.height,
                                                   destination_region.depth)
                                                , destination_slice
                                                , destination_level
                                                , (destination_region.x,
                                                   destination_region.y,
                                                   destination_region.z) )
                                              in
                                              match
                                                Metal_raw.blit_encoder_copy_buffer_to_texture
                                                  value.raw source.raw
                                                  destination.raw copy
                                              with
                                              | Error message ->
                                                  native_error operation message
                                              | Ok () ->
                                                  retain_command_buffer_buffer
                                                    value.command_buffer source;
                                                  retain_command_buffer_texture
                                                    value.command_buffer
                                                    destination;
                                                  Ok ())))))))

  let fill_buffer (value:t) (buffer:Buffer.t) ~offset ~length ~byte =
    let operation = "Metal.Blit_encoder.fill_buffer" in
    on_main operation (fun () -> match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () -> Result.bind (ensure_buffer_usable operation buffer) (fun () ->
          if offset < 0L || length < 0L || offset > buffer.length
             || length > Int64.sub buffer.length offset || byte < 0 || byte > 255
          then error operation Invalid_argument "invalid fill range/value"
          else Result.bind (ensure_same_device operation value.command_buffer.queue.device buffer.device)
            (fun () -> match Metal_raw.blit_fill_mipmap value.raw buffer.raw false (offset,length,Int64.of_int byte) with
             | Error message -> native_error operation message
             | Ok () -> retain_command_buffer_buffer value.command_buffer buffer; Ok ())))

  let generate_mipmaps (value:t) (texture:Texture.t) =
    let operation = "Metal.Blit_encoder.generate_mipmaps" in
    on_main operation (fun () -> match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () -> Result.bind (ensure_texture_usable operation texture) (fun () ->
          if texture.descriptor.mip_levels < 2 then
            error operation Invalid_argument "texture has no mip levels"
          else Result.bind (ensure_same_device operation value.command_buffer.queue.device texture.device)
            (fun () -> match Metal_raw.blit_fill_mipmap value.raw texture.raw true (0L,0L,0L) with
             | Error message -> native_error operation message
           | Ok () -> retain_command_buffer_texture value.command_buffer texture; Ok ())))

  let copy_buffer (value:t) ~(source:Buffer.t) ~source_offset
      ~(destination:Buffer.t) ~destination_offset ~length =
    let operation = "Metal.Blit_encoder.copy_buffer" in
    on_main operation (fun () -> match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () -> Result.bind (ensure_buffer_usable operation source) (fun () ->
          Result.bind (ensure_buffer_usable operation destination) (fun () ->
            if source_offset < 0L || destination_offset < 0L || length < 0L
               || source_offset > source.length
               || length > Int64.sub source.length source_offset
               || destination_offset > destination.length
               || length > Int64.sub destination.length destination_offset
            then error operation Invalid_argument "copy range exceeds a buffer"
            else Result.bind
              (ensure_same_device operation value.command_buffer.queue.device source.device)
              (fun () -> Result.bind
                (ensure_same_device operation source.device destination.device)
                (fun () -> match Metal_raw.blit_copy value.raw 1 source.raw destination.raw
                                  (Metal_raw.Blit_buffer_to_buffer
                                     (source_offset,destination_offset,length)) with
                 | Error message -> native_error operation message
                 | Ok () ->
                     retain_command_buffer_buffer value.command_buffer source;
                     retain_command_buffer_buffer value.command_buffer destination;
                     Ok ())))))

  let copy_texture (value:t) ~(source:Texture.t) ~(destination:Texture.t) =
    let operation = "Metal.Blit_encoder.copy_texture" in
    on_main operation (fun () -> match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () -> Result.bind (ensure_texture_usable operation source) (fun () ->
          Result.bind (ensure_texture_usable operation destination) (fun () ->
            if source.descriptor.width <> destination.descriptor.width
               || source.descriptor.height <> destination.descriptor.height
               || source.descriptor.depth <> destination.descriptor.depth
               || source.descriptor.format <> destination.descriptor.format
            then error operation Invalid_argument "whole-texture copy descriptors differ"
            else Result.bind
              (ensure_same_device operation value.command_buffer.queue.device source.device)
              (fun () -> Result.bind
                (ensure_same_device operation source.device destination.device)
                (fun () -> match Metal_raw.blit_copy value.raw 6 source.raw destination.raw
                                  Metal_raw.Blit_texture_whole with
                 | Error message -> native_error operation message
                 | Ok () -> retain_command_buffer_texture value.command_buffer source;
                     retain_command_buffer_texture value.command_buffer destination; Ok ())))))

  let copy_texture_levels (value:t) ~(source:Texture.t) ~source_slice ~source_level
      ~(destination:Texture.t) ~destination_slice ~destination_level ~slice_count ~level_count =
    let operation = "Metal.Blit_encoder.copy_texture_levels" in
    on_main operation (fun () -> match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () -> Result.bind (ensure_texture_usable operation source) (fun () ->
          Result.bind (ensure_texture_usable operation destination) (fun () ->
            let source_slices=Texture.total_slices source.descriptor
            and destination_slices=Texture.total_slices destination.descriptor in
            if source_slice<0 || destination_slice<0 || source_level<0 || destination_level<0
               || slice_count<=0 || level_count<=0
               || source_slice>source_slices-slice_count
               || destination_slice>destination_slices-slice_count
               || source_level>source.descriptor.mip_levels-level_count
               || destination_level>destination.descriptor.mip_levels-level_count
            then error operation Invalid_argument "texture level range is invalid"
            else Result.bind (ensure_same_device operation value.command_buffer.queue.device source.device)
              (fun () -> Result.bind (ensure_same_device operation source.device destination.device)
                (fun () -> match Metal_raw.blit_copy value.raw 5 source.raw destination.raw
                  (Metal_raw.Blit_texture_levels(Int64.of_int source_slice,Int64.of_int source_level,
                    Int64.of_int destination_slice,Int64.of_int destination_level,
                    Int64.of_int slice_count,Int64.of_int level_count)) with
                 | Error message->native_error operation message
                 | Ok()->retain_command_buffer_texture value.command_buffer source;
                    retain_command_buffer_texture value.command_buffer destination;Ok())))))

  let copy_indirect (value:t) ~(source:Indirect_command_buffer.t) ~source_location
      ~length ~(destination:Indirect_command_buffer.t) ~destination_index =
    let operation = "Metal.Blit_encoder.copy_indirect" in
    on_main operation (fun () -> match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () -> Result.bind (ensure_live operation source.lifetime) (fun () ->
          Result.bind (ensure_live operation destination.lifetime) (fun () ->
            if source_location<0 || length<0 || destination_index<0
               || source_location>source.max_command_count-length
               || destination_index>destination.max_command_count-length
            then error operation Invalid_argument "indirect copy range is invalid"
            else Result.bind (ensure_same_device operation value.command_buffer.queue.device source.device)
              (fun () -> Result.bind (ensure_same_device operation source.device destination.device)
                (fun () -> match Metal_raw.blit_copy value.raw 7 source.raw destination.raw
                  (Metal_raw.Blit_indirect_commands(Int64.of_int source_location,
                    Int64.of_int length,Int64.of_int destination_index)) with
                 | Error message->native_error operation message
                 | Ok()->retain_command_buffer_indirect value.command_buffer source;
                    retain_command_buffer_indirect value.command_buffer destination;Ok())))))

  let copy_tensor_private (value:t) (source:resource100_tensor)
      (destination:resource100_tensor) source_origin source_dimensions
      destination_origin destination_dimensions =
    let operation="Metal.Blit_encoder.copy_tensor" in
    on_main operation (fun()->match ensure_live operation value.lifetime with
      | Error _ as failure->failure
      | Ok()->Result.bind(ensure_live operation source.lifetime)(fun()->
          Result.bind(ensure_live operation destination.lifetime)(fun()->
            Result.bind(ensure_same_device operation value.command_buffer.queue.device source.buffer.device)(fun()->
              Result.bind(ensure_same_device operation source.buffer.device destination.buffer.device)(fun()->
                match Metal_raw.blit_copy value.raw 2 source.raw destination.raw
                  (Metal_raw.Blit_tensor_to_tensor(source_origin,source_dimensions,
                    destination_origin,destination_dimensions))with
                |Error message->native_error operation message
                |Ok()->retain_command_buffer_buffer value.command_buffer source.buffer;
                    retain_command_buffer_buffer value.command_buffer destination.buffer;Ok())))))

  let copy_texture_to_buffer (value:t) ~(source:Texture.t) ~source_slice ~source_level
      ~(source_region:Texture.region) ~(destination:Buffer.t) ~destination_offset
      ~destination_bytes_per_row ~destination_bytes_per_image ?(options=0L) () =
    let operation="Metal.Blit_encoder.copy_texture_to_buffer" in
    on_main operation(fun()->match ensure_live operation value.lifetime with
      |Error _ as failure->failure
      |Ok()->Result.bind(ensure_texture_usable operation source)(fun()->
          Result.bind(ensure_buffer_usable operation destination)(fun()->
            let d=source.descriptor in
            if source_slice<0||source_slice>=Texture.total_slices d||source_level<0
               ||source_level>=d.mip_levels||source_region.x<0||source_region.y<0
               ||source_region.z<0||source_region.width<=0||source_region.height<=0
               ||source_region.depth<=0||destination_offset<0L
               ||destination_bytes_per_row<=0L||destination_bytes_per_image<=0L
            then error operation Invalid_argument "texture-to-buffer region/layout is invalid"
            else let total=Int64.mul destination_bytes_per_image(Int64.of_int source_region.depth)in
              if total<0L||destination_offset>destination.length
                 ||total>Int64.sub destination.length destination_offset then
                error operation Invalid_argument "texture-to-buffer destination range exceeds buffer"
              else Result.bind(ensure_same_device operation value.command_buffer.queue.device source.device)(fun()->
                Result.bind(ensure_same_device operation source.device destination.device)(fun()->
                  match Metal_raw.blit_copy value.raw 3 source.raw destination.raw
                    (Metal_raw.Blit_texture_to_buffer(Int64.of_int source_slice,Int64.of_int source_level,
                      Int64.of_int source_region.x,Int64.of_int source_region.y,Int64.of_int source_region.z,
                      Int64.of_int source_region.width,Int64.of_int source_region.height,Int64.of_int source_region.depth,
                      destination_offset,destination_bytes_per_row,destination_bytes_per_image,options))with
                  |Error message->native_error operation message
                  |Ok()->retain_command_buffer_texture value.command_buffer source;
                      retain_command_buffer_buffer value.command_buffer destination;Ok())))))

  let copy_texture_region (value:t) ~(source:Texture.t) ~source_slice ~source_level
      ~(source_region:Texture.region) ~(destination:Texture.t) ~destination_slice
      ~destination_level ~destination_origin =
    let operation="Metal.Blit_encoder.copy_texture_region" in
    let dx,dy,dz=destination_origin in
    on_main operation(fun()->match ensure_live operation value.lifetime with
      |Error _ as failure->failure
      |Ok()->Result.bind(ensure_texture_usable operation source)(fun()->
          Result.bind(ensure_texture_usable operation destination)(fun()->
            if source_slice<0||destination_slice<0||source_level<0||destination_level<0
               ||source_slice>=Texture.total_slices source.descriptor
               ||destination_slice>=Texture.total_slices destination.descriptor
               ||source_level>=source.descriptor.mip_levels
               ||destination_level>=destination.descriptor.mip_levels
               ||source_region.width<=0||source_region.height<=0||source_region.depth<=0
               ||source_region.x<0||source_region.y<0||source_region.z<0||dx<0||dy<0||dz<0
               ||source.descriptor.format<>destination.descriptor.format
            then error operation Invalid_argument "texture copy region is invalid"
            else Result.bind(ensure_same_device operation value.command_buffer.queue.device source.device)(fun()->
              Result.bind(ensure_same_device operation source.device destination.device)(fun()->
                match Metal_raw.blit_copy value.raw 4 source.raw destination.raw
                  (Metal_raw.Blit_texture_region(Int64.of_int source_slice,Int64.of_int source_level,
                    Int64.of_int source_region.x,Int64.of_int source_region.y,Int64.of_int source_region.z,
                    Int64.of_int source_region.width,Int64.of_int source_region.height,Int64.of_int source_region.depth,
                    Int64.of_int destination_slice,Int64.of_int destination_level,
                    Int64.of_int dx,Int64.of_int dy,Int64.of_int dz))with
                |Error message->native_error operation message
                |Ok()->retain_command_buffer_texture value.command_buffer source;
                    retain_command_buffer_texture value.command_buffer destination;Ok())))))

  let access_counters operation reset (value:t) (texture:Texture.t)
      ~(region:Texture.region) ~level ~slice ?(buffer:Buffer.t option) ?(offset=0L) () =
    on_main operation(fun()->match ensure_live operation value.lifetime with
      |Error _ as failure->failure
      |Ok()->Result.bind(ensure_texture_usable operation texture)(fun()->
        if level<0||level>=texture.descriptor.mip_levels||slice<0
           ||slice>=Texture.total_slices texture.descriptor||region.x<0||region.y<0
           ||region.z<0||region.width<=0||region.height<=0||region.depth<=0||offset<0L
        then error operation Invalid_argument "texture access-counter region is invalid"
        else match buffer,reset with
        |None,false->error operation Invalid_argument "counter read requires a destination buffer"
        |Some _,true->error operation Invalid_argument "counter reset does not accept a buffer"
        |buffer,_->let destination_raw=match buffer with Some b->b.raw|None->texture.raw in
          Result.bind (match buffer with Some (b:buffer)->Result.bind(ensure_buffer_usable operation b)(fun()->
              Result.bind(ensure_same_device operation texture.device b.device)(fun()->Ok()))|None->Ok())
          (fun()->Result.bind(ensure_same_device operation value.command_buffer.queue.device texture.device)(fun()->
            match Metal_raw.blit_access_counters value.raw texture.raw
              (Int64.of_int region.x,Int64.of_int region.y,Int64.of_int region.z,
               Int64.of_int region.width,Int64.of_int region.height,Int64.of_int region.depth)
              (Int64.of_int level)(Int64.of_int slice)reset destination_raw offset with
            |Error message->native_error operation message
            |Ok()->retain_command_buffer_texture value.command_buffer texture;
                Option.iter(retain_command_buffer_buffer value.command_buffer)buffer;Ok()))))
  let get_access_counters value texture ~region ~level ~slice ~buffer ~offset =
    access_counters "Metal.Blit_encoder.get_access_counters" false value texture
      ~region ~level ~slice ~buffer ~offset ()
  let reset_access_counters value texture ~region ~level ~slice =
    access_counters "Metal.Blit_encoder.reset_access_counters" true value texture
      ~region ~level ~slice ()

  let fence_call operation update (value:t) (fence:Fence.t) =
    on_main operation (fun () -> match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () -> Result.bind (ensure_live operation fence.lifetime) (fun () ->
          Result.bind (ensure_same_device operation value.command_buffer.queue.device fence.device)
            (fun () -> match Metal_raw.blit_fence value.raw fence.raw update with
             | Error message -> native_error operation message
             | Ok () -> retain_command_buffer_fence value.command_buffer fence; Ok ())))
  let update_fence value fence = fence_call "Metal.Blit_encoder.update_fence" true value fence
  let wait_for_fence value fence = fence_call "Metal.Blit_encoder.wait_for_fence" false value fence

  let indirect operation optimize (value:t) (commands:Indirect_command_buffer.t)
      ~location ~length =
    on_main operation (fun () -> match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () -> Result.bind (ensure_live operation commands.lifetime) (fun () ->
          Result.bind (ensure_same_device operation value.command_buffer.queue.device commands.device)
            (fun () -> Result.bind
              (Indirect_command_buffer.validate_range operation commands ~location ~length)
              (fun () -> match Metal_raw.blit_indirect value.raw commands.raw optimize
                                (Int64.of_int location) (Int64.of_int length) with
               | Error message -> native_error operation message
               | Ok () -> retain_command_buffer_indirect value.command_buffer commands; Ok ()))))
  let optimize_indirect value commands ~location ~length =
    indirect "Metal.Blit_encoder.optimize_indirect" true value commands ~location ~length
  let reset_indirect value commands ~location ~length =
    indirect "Metal.Blit_encoder.reset_indirect" false value commands ~location ~length

  let texture_aux operation mode (value:t) (texture:Texture.t) ?slice ?level () =
    on_main operation (fun () -> match ensure_live operation value.lifetime with
      | Error _ as failure -> failure
      | Ok () -> Result.bind (ensure_texture_usable operation texture) (fun () ->
          let descriptor = texture.descriptor in
          let spec = match slice,level with
            | None,None -> Ok [||]
            | Some slice,Some level when slice >= 0 && slice < Texture.total_slices descriptor
                                         && level >= 0 && level < descriptor.mip_levels ->
                Ok [|Int64.of_int slice;Int64.of_int level|]
            | _ -> error operation Invalid_argument "texture slice/level is invalid"
          in Result.bind spec (fun spec ->
            Result.bind (ensure_same_device operation value.command_buffer.queue.device texture.device)
              (fun () -> match Metal_raw.blit_texture_aux value.raw texture.raw mode spec with
               | Error message -> native_error operation message
               | Ok () -> retain_command_buffer_texture value.command_buffer texture; Ok ()))))
  let optimize_for_cpu value texture = texture_aux "Metal.Blit_encoder.optimize_for_cpu" 0 value texture ()
  let optimize_slice_for_cpu value texture ~slice ~level = texture_aux "Metal.Blit_encoder.optimize_slice_for_cpu" 1 value texture ~slice ~level ()
  let optimize_for_gpu value texture = texture_aux "Metal.Blit_encoder.optimize_for_gpu" 2 value texture ()
  let optimize_slice_for_gpu value texture ~slice ~level = texture_aux "Metal.Blit_encoder.optimize_slice_for_gpu" 3 value texture ~slice ~level ()
  let synchronize_texture value texture = texture_aux "Metal.Blit_encoder.synchronize_texture" 4 value texture ()
  let synchronize_texture_slice value texture ~slice ~level = texture_aux "Metal.Blit_encoder.synchronize_texture_slice" 5 value texture ~slice ~level ()

  let end_encoding (value : t) =
    on_main "Metal.Blit_encoder.end_encoding" (fun () ->
      match ensure_live "Metal.Blit_encoder.end_encoding" value.lifetime with
      | Error _ as failure -> failure
      | Ok () ->
          (match Metal_raw.blit_encoder_end value.raw with
           | Error message -> native_error "Metal.Blit_encoder.end_encoding" message
           | Ok () ->
               if Atomic.compare_and_set value.lifetime.destroyed false true
               then begin
                 ignore (Metal_raw.destroy value.raw);
                 detach value.command_buffer.lifetime
               end;
               Ok ()))
end

module Resource100 = struct
  type tensor = resource100_tensor
  type sample_buffer = counter_sample_buffer

  module Texture_reference_type = struct
    type t =
      { data_type : Data_type.t
      ; texture_type : Texture.kind
      ; access : Binding.access
      ; depth : bool }

    let of_reflection = function
      | Reflection.Texture_reference {data_type;access;texture_type;depth} ->
          (match Data_type.of_int64 data_type,
                 Binding.texture_kind_of_code (Int64.to_int texture_type) with
           | Some data_type, Some texture_type ->
               Ok {data_type;texture_type;access=Binding.access_of_code(Int64.to_int access);depth}
           | _ -> error "Metal.Resource100.Texture_reference_type.of_reflection"
                    Native_error "texture-reference reflection contains an unknown SDK value")
      | _ -> error "Metal.Resource100.Texture_reference_type.of_reflection"
               Invalid_argument "reflection is not an MTLTextureReferenceType"
  end
  module Options = struct
    type cpu_cache_mode = Default | Write_combined
    type storage_mode = Memoryless
    let cpu_cache_code = function Default->0L|Write_combined->1L
    let storage_code Memoryless = 48L
  end

  module Heap_ops = struct
    let create_acceleration_structure = Heap.create_acceleration_structure
    let create_acceleration_structure_with_descriptor =
      Heap.create_acceleration_structure_with_descriptor
    let checked_device (value:Heap.t)=let operation="Metal.Resource100.Heap.checked_device"in on_main operation(fun()->match ensure_live operation value.lifetime with Error _ as e->e|Ok()->match Metal_raw.resource_heap_device value.raw with Error m->native_error operation m|Ok registry_id when registry_id<>value.device.registry_id->error operation Device_mismatch "heap device disagrees with its safe owner"|Ok _->Ok value.device)
  end

  module Resource_ops = struct
    type t = Buffer of buffer | Texture of texture

    let parts = function
      | Buffer value -> value.raw, value.lifetime, value.device,
          parent_heap value.parent
      | Texture value -> value.raw, value.lifetime, value.device,
          texture_heap value

    let device value =
      let operation = "Metal.Resource100.Resource.device" in
      on_main operation (fun () ->
        let raw, lifetime, expected, _ = parts value in
        match ensure_live operation lifetime with
        | Error _ as failure -> failure
        | Ok () -> match Metal_raw.resource_resource_device raw with
          | Error message -> native_error operation message
          | Ok registry_id when registry_id <> expected.registry_id ->
              error operation Device_mismatch
                "resource device disagrees with its safe owner"
          | Ok _ -> Ok expected)

    let heap value =
      let operation = "Metal.Resource100.Resource.heap" in
      on_main operation (fun () ->
        let raw, lifetime, _, expected = parts value in
        match ensure_live operation lifetime with
        | Error _ as failure -> failure
        | Ok () -> match Metal_raw.resource_resource_heap raw with
          | Error message -> native_error operation message
          | Ok native ->
              Option.iter (fun handle -> ignore (Metal_raw.destroy handle)) native;
              if Option.is_some native <> Option.is_some expected then
                native_error operation
                  "resource heap disagrees with its safe parent graph"
              else Ok expected)

    let set_current_owner value =
      let operation="Metal.Resource100.Resource.set_current_owner" in
      on_main operation(fun()->let raw,lifetime,_,_=parts value in
        match ensure_live operation lifetime with Error _ as e->e|Ok()->
        match Metal_raw.resource_set_current_owner raw with
        |Error message->native_error operation message|Ok()->Ok())
  end

  module Buffer_ops = struct
    let add_debug_marker (value:buffer) ~label ~offset ~length =
      let op="Metal.Resource100.Buffer.add_debug_marker"in on_main op(fun()->match ensure_buffer_usable op value with Error _ as e->e|Ok()->if contains_nul label then error op Invalid_argument "label contains a NUL byte"else if offset<0L||length<0L||offset>value.length||length>Int64.sub value.length offset then error op Invalid_argument "debug marker range exceeds the buffer"else match Metal_raw.resource_buffer_add_debug_marker value.raw label offset length with Error m->native_error op m|Ok()->Ok())
    let remove_all_debug_markers (value:buffer)=let op="Metal.Resource100.Buffer.remove_all_debug_markers"in on_main op(fun()->match ensure_buffer_usable op value with Error _ as e->e|Ok()->match Metal_raw.resource_buffer_remove_all_debug_markers value.raw with Error m->native_error op m|Ok()->Ok())

    let wrap_snapshot operation (device : device)
        (raw, length, storage_code', cache_code', hazard_code') =
      let reject message = ignore (Metal_raw.destroy raw); native_error operation message in
      let storage = match storage_code' with
        | 0 -> Some Shared | 1 -> Some Managed | 2 -> Some Private | _ -> None
      and cpu_cache = match cache_code' with
        | 0 -> Some Default_cache | 1 -> Some Write_combined | _ -> None
      and hazard_tracking = match hazard_code' with
        | 0 -> Some Default_hazard_tracking | 1 -> Some Untracked
        | 2 -> Some Tracked | _ -> None
      in
      match storage, cpu_cache, hazard_tracking with
      | Some storage, Some cpu_cache, Some hazard_tracking when length > 0L ->
          Buffer.finish_create operation ~device ~parent:(Device_resource device)
            ~length ~storage ~cpu_cache ~hazard_tracking ~heap_offset:None
            ~allocation:None ~label:None raw
      | _ -> reject "remote buffer returned invalid resource metadata"

    let remote_view (source : buffer) ~(device : device) =
      let operation = "Metal.Resource100.Buffer.remote_view" in
      on_main operation (fun () ->
        match ensure_buffer_usable operation source with
        | Error _ as failure -> failure
        | Ok () -> match ensure_live operation device.lifetime with
          | Error _ as failure -> failure
          | Ok () -> match Metal_raw.resource_buffer_remote_view source.raw device.raw with
            | Error message -> native_error operation message
            | Ok None -> Ok None
            | Ok (Some snapshot) -> Result.map Option.some
                (wrap_snapshot operation device snapshot))

    let remote_storage (source : buffer) =
      let operation = "Metal.Resource100.Buffer.remote_storage" in
      on_main operation (fun () ->
        match ensure_buffer_usable operation source with
        | Error _ as failure -> failure
        | Ok () -> match Metal_raw.resource_buffer_remote_storage source.raw with
          | Error message -> native_error operation message
          | Ok None -> Ok None
            | Ok (Some snapshot) -> Result.map Option.some
              (wrap_snapshot operation source.device snapshot))

    let tensor_element_size data_type =
      let code=Data_type.to_int64 data_type in
      let same value=code=Data_type.to_int64 value in
      if same Data_type.mtl_data_type_float || same Data_type.mtl_data_type_int
         || same Data_type.mtl_data_type_u_int then Some 4L
      else if same Data_type.mtl_data_type_half || same Data_type.mtl_data_type_short
              || same Data_type.mtl_data_type_u_short then Some 2L
      else if same Data_type.mtl_data_type_char || same Data_type.mtl_data_type_u_char
              || same Data_type.mtl_data_type_bool then Some 1L
      else if same Data_type.mtl_data_type_long || same Data_type.mtl_data_type_u_long
      then Some 8L else None

    let new_tensor (buffer:buffer) ~data_type ~dimensions ~strides ~offset =
      let operation="Metal.Resource100.Buffer_ops.new_tensor" in
      on_main operation (fun () ->
        match ensure_buffer_usable operation buffer with Error _ as e->e | Ok () ->
